window.QBANK = window.QBANK || {};
window.QBANK["kuliah-fisika-dasar"] = {
  level: "Kuliah", subject: "Fisika Dasar", duration: 1200,
  questions: [
    { q: "Sebuah mobil bergerak dengan kecepatan awal $10\\ \\text{m/s}$ dan percepatan tetap $2\\ \\text{m/s}^2$. Jarak yang ditempuh setelah $5\\ \\text{s}$ adalah ...", options: ["$75\\ \\text{m}$", "$50\\ \\text{m}$", "$100\\ \\text{m}$", "$60\\ \\text{m}$"], answer: 0, solution: "Gunakan persamaan GLBB $s = v_0 t + \\frac{1}{2}at^2 = 10\\cdot5 + \\frac{1}{2}\\cdot2\\cdot5^2 = 50 + 25 = 75\\ \\text{m}$. Kesalahan umum: hanya menghitung $v_0 t = 50\\ \\text{m}$ (lupa suku percepatan) atau memakai $at^2$ tanpa faktor $\\frac{1}{2}$." },
    { q: "Sebuah bola dijatuhkan (tanpa kecepatan awal) dari ketinggian $20\\ \\text{m}$. Jika $g = 10\\ \\text{m/s}^2$, waktu yang dibutuhkan bola mencapai tanah adalah ...", options: ["$\\sqrt{2}\\ \\text{s}$", "$2\\ \\text{s}$", "$4\\ \\text{s}$", "$1\\ \\text{s}$"], answer: 1, solution: "Gerak jatuh bebas memenuhi $h = v_0 t + \\frac{1}{2}gt^2$ dengan $v_0 = 0$. Maka $20 = \\frac{1}{2}\\cdot10\\cdot t^2 \\Rightarrow 20 = 5t^2 \\Rightarrow t^2 = 4 \\Rightarrow t = 2\\ \\text{s}$ (ambil akar positif). Kesalahan umum: memakai $h = gt^2$ sehingga dapat $t = \\sqrt{2}\\ \\text{s}$." },
    { q: "Sebuah benda bermassa $4\\ \\text{kg}$ didorong dengan gaya resultan $20\\ \\text{N}$. Percepatan benda tersebut adalah ...", options: ["$80\\ \\text{m/s}^2$", "$5\\ \\text{m/s}^2$", "$0{,}2\\ \\text{m/s}^2$", "$24\\ \\text{m/s}^2$"], answer: 1, solution: "Hukum II Newton: $\\Sigma F = m\\cdot a$, sehingga $a = \\frac{\\Sigma F}{m} = \\frac{20}{4} = 5\\ \\text{m/s}^2$. Percepatan berbanding lurus dengan gaya dan berbanding terbalik dengan massa — jadi gaya dibagi massa, bukan dikali." },
    { q: "Balok bermassa $2\\ \\text{kg}$ di atas lantai kasar ditarik dengan gaya horizontal $10\\ \\text{N}$. Jika gaya gesek kinetik yang bekerja $4\\ \\text{N}$, percepatan balok adalah ...", options: ["$5\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$", "$3\\ \\text{m/s}^2$", "$7\\ \\text{m/s}^2$"], answer: 2, solution: "Gaya gesek selalu melawan arah gerak, jadi gaya totalnya $\\Sigma F = F_{tarik} - f_{gesek} = 10 - 4 = 6\\ \\text{N}$. Dengan Hukum II Newton: $a = \\frac{\\Sigma F}{m} = \\frac{6}{2} = 3\\ \\text{m/s}^2$. Kesalahan umum: mengabaikan gesekan sehingga mendapat $10/2 = 5\\ \\text{m/s}^2$." },
    { q: "Sebuah gaya $100\\ \\text{N}$ bekerja pada benda dan membentuk sudut $60^\\circ$ terhadap arah perpindahan sejauh $10\\ \\text{m}$. Usaha yang dilakukan gaya tersebut adalah ...", options: ["$1000\\ \\text{J}$", "$500\\ \\text{J}$", "$250\\ \\text{J}$", "$500\\sqrt{3}\\ \\text{J}$"], answer: 1, solution: "Usaha oleh gaya yang membentuk sudut: $W = F\\cdot s\\cdot\\cos\\theta$. Dengan $\\cos 60^\\circ = \\frac{1}{2}$: $W = 100\\cdot10\\cdot\\frac{1}{2} = 500\\ \\text{J}$. Hanya komponen gaya yang searah perpindahan ($F\\cos\\theta$) yang melakukan usaha — itulah mengapa ada faktor $\\cos\\theta$." },
    { q: "Sebuah mobil bermassa $1000\\ \\text{kg}$ dipercepat dari $10\\ \\text{m/s}$ menjadi $20\\ \\text{m/s}$. Usaha total yang bekerja pada mobil adalah ...", options: ["$50.000\\ \\text{J}$", "$150.000\\ \\text{J}$", "$100.000\\ \\text{J}$", "$200.000\\ \\text{J}$"], answer: 1, solution: "Teorema usaha-energi: $W_{total} = \\Delta E_k = \\frac{1}{2}m(v_2^2 - v_1^2)$. Hitung: $\\frac{1}{2}\\cdot1000\\cdot(20^2 - 10^2) = 500\\cdot(400 - 100) = 500\\cdot300 = 150.000\\ \\text{J}$. Kesalahan umum: memakai $\\frac{1}{2}m(v_2 - v_1)^2 = 50.000\\ \\text{J}$ — kuadrat selisih tidak sama dengan selisih kuadrat." },
    { q: "Sebuah bola bermassa $2\\ \\text{kg}$ jatuh bebas dari ketinggian $5\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Kecepatan bola tepat sebelum menyentuh tanah adalah ...", options: ["$\\sqrt{50}\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$100\\ \\text{m/s}$"], answer: 2, solution: "Energi mekanik kekal (abaikan gesekan udara): $E_{p,awal} = E_{k,akhir} \\Rightarrow mgh = \\frac{1}{2}mv^2$. Massa $m$ saling meniadakan di kedua ruas: $v = \\sqrt{2gh} = \\sqrt{2\\cdot10\\cdot5} = \\sqrt{100} = 10\\ \\text{m/s}$. Perhatikan kecepatan jatuh bebas tidak bergantung pada massa benda." },
    { q: "Sebuah bola bermassa $0{,}5\\ \\text{kg}$ bergerak dengan kecepatan $4\\ \\text{m/s}$. Besar momentum bola tersebut adalah ...", options: ["$8\\ \\text{kg}\\cdot\\text{m/s}$", "$2\\ \\text{kg}\\cdot\\text{m/s}$", "$4\\ \\text{kg}\\cdot\\text{m/s}$", "$0{,}5\\ \\text{kg}\\cdot\\text{m/s}$"], answer: 1, solution: "Momentum linear $p = m\\cdot v = 0{,}5\\cdot4 = 2\\ \\text{kg}\\cdot\\text{m/s}$. Jangan tertukar dengan energi kinetik $E_k = \\frac{1}{2}mv^2 = 4\\ \\text{J}$ — momentum tidak memiliki faktor $\\frac{1}{2}$ dan tidak ada kuadrat kecepatan." },
    { q: "Bola bermassa $0{,}2\\ \\text{kg}$ menumbuk dinding dengan kecepatan $5\\ \\text{m/s}$ lalu memantul berbalik arah dengan kecepatan $3\\ \\text{m/s}$. Besar impuls yang dialami bola adalah ...", options: ["$0{,}4\\ \\text{N}\\cdot\\text{s}$", "$1{,}0\\ \\text{N}\\cdot\\text{s}$", "$2{,}6\\ \\text{N}\\cdot\\text{s}$", "$1{,}6\\ \\text{N}\\cdot\\text{s}$"], answer: 3, solution: "Impuls $I = \\Delta p = m(v' - v)$. Tetapkan arah datang sebagai positif: $v = +5\\ \\text{m/s}$, $v' = -3\\ \\text{m/s}$ (berbalik arah, tandanya negatif). $I = 0{,}2\\cdot(-3 - 5) = 0{,}2\\cdot(-8) = -1{,}6\\ \\text{N}\\cdot\\text{s}$. Besar impuls $1{,}6\\ \\text{N}\\cdot\\text{s}$; tanda negatif menunjukkan arahnya berlawanan dengan arah datang." },
    { q: "Gerbong kereta $2000\\ \\text{kg}$ melaju $3\\ \\text{m/s}$ menumbuk gerbong $1000\\ \\text{kg}$ yang diam, lalu keduanya menempel dan bergerak bersama. Kecepatan akhir kedua gerbong adalah ...", options: ["$3\\ \\text{m/s}$", "$1{,}5\\ \\text{m/s}$", "$2\\ \\text{m/s}$", "$6\\ \\text{m/s}$"], answer: 2, solution: "Pada tumbukan tak lenting sempurna momentum total kekal: $m_1 v_1 + m_2 v_2 = (m_1 + m_2)v'$. Substitusi: $2000\\cdot3 + 1000\\cdot0 = (2000 + 1000)\\cdot v' \\Rightarrow 6000 = 3000\\cdot v' \\Rightarrow v' = 2\\ \\text{m/s}$ searah gerak awal. (Energi kinetik tidak kekal di sini — sebagian berubah menjadi panas dan bunyi.)" },
    { q: "Sebuah bola ditendang dengan kecepatan awal $20\\ \\text{m/s}$ membentuk sudut $30^\\circ$ terhadap horizontal ($g = 10\\ \\text{m/s}^2$). Tinggi maksimum yang dicapai bola adalah ...", options: ["$10\\ \\text{m}$", "$5\\ \\text{m}$", "$20\\ \\text{m}$", "$2{,}5\\ \\text{m}$"], answer: 1, solution: "Uraikan kecepatan awal pada sumbu vertikal: $v_{0y} = v_0\\sin\\theta = 20\\cdot\\sin 30^\\circ = 20\\cdot\\frac{1}{2} = 10\\ \\text{m/s}$. Pada titik tertinggi $v_y = 0$, gunakan $v_y^2 = v_{0y}^2 - 2gh$: $0 = 10^2 - 2\\cdot10\\cdot h \\Rightarrow 20h = 100 \\Rightarrow h = 5\\ \\text{m}$. (Atau langsung $h_{maks} = \\frac{v_0^2\\sin^2\\theta}{2g} = \\frac{400\\cdot\\frac{1}{4}}{20} = 5\\ \\text{m}$.)" },
    { q: "Sebuah bola ditendang dengan kecepatan awal $20\\ \\text{m/s}$ dan sudut elevasi $30^\\circ$ ($g = 10\\ \\text{m/s}^2$). Jarak mendatar terjauh yang dicapai bola adalah ...", options: ["$20\\sqrt{3}\\ \\text{m}$", "$40\\ \\text{m}$", "$10\\sqrt{3}\\ \\text{m}$", "$20\\ \\text{m}$"], answer: 0, solution: "Jarak mendatar gerak parabola: $R = \\frac{v_0^2\\sin 2\\theta}{g}$. Hitung $\\sin 2\\theta = \\sin 60^\\circ = \\frac{\\sqrt{3}}{2}$. Maka $R = \\frac{400\\cdot\\frac{\\sqrt{3}}{2}}{10} = \\frac{200\\sqrt{3}}{10} = 20\\sqrt{3}\\ \\text{m}$. Kesalahan umum: memakai $\\sin\\theta$ bukan $\\sin 2\\theta$." },
    { q: "Sebuah mobil bermassa $1000\\ \\text{kg}$ menikung dengan jari-jari $50\\ \\text{m}$ pada kecepatan $20\\ \\text{m/s}$. Gaya sentripetal yang dibutuhkan agar mobil tidak selip adalah ...", options: ["$4000\\ \\text{N}$", "$8000\\ \\text{N}$", "$20000\\ \\text{N}$", "$400\\ \\text{N}$"], answer: 1, solution: "Gaya sentripetal $F_s = m\\frac{v^2}{r} = 1000\\cdot\\frac{20^2}{50} = 1000\\cdot\\frac{400}{50} = 1000\\cdot8 = 8000\\ \\text{N}$, mengarah ke pusat lingkaran. Gaya ini disediakan oleh gaya gesek antara ban dan jalan." },
    { q: "Roket dapat meluncur ke atas karena menyemburkan gas panas ke bawah dengan kecepatan tinggi. Peristiwa ini merupakan penerapan ...", options: ["Hukum I Newton", "Hukum II Newton", "hukum kekekalan energi mekanik", "Hukum III Newton"], answer: 3, solution: "Hukum III Newton menyatakan setiap aksi menimbulkan reaksi yang sama besar dan berlawanan arah. Gas disemburkan ke bawah (aksi), maka gas memberikan dorongan ke atas pada roket (reaksi). Inilah prinsip propulsi roket." },
    { q: "Sebuah mesin melakukan usaha $600\\ \\text{J}$ dalam waktu $3\\ \\text{s}$. Daya mesin tersebut adalah ...", options: ["$200\\ \\text{W}$", "$1800\\ \\text{W}$", "$20\\ \\text{W}$", "$600\\ \\text{W}$"], answer: 0, solution: "Daya $P = \\frac{W}{t} = \\frac{600}{3} = 200\\ \\text{W}$. Daya mengukur seberapa cepat usaha dilakukan — usaha yang sama dalam waktu lebih singkat berarti daya lebih besar." },
    { q: "Sebuah pegas dengan konstanta $200\\ \\text{N/m}$ diregangkan sejauh $0{,}1\\ \\text{m}$ dari posisi setimbangnya. Energi potensial pegas yang tersimpan adalah ...", options: ["$10\\ \\text{J}$", "$0{,}5\\ \\text{J}$", "$1\\ \\text{J}$", "$20\\ \\text{J}$"], answer: 2, solution: "Energi potensial pegas $E_p = \\frac{1}{2}kx^2 = \\frac{1}{2}\\cdot200\\cdot(0{,}1)^2 = 100\\cdot0{,}01 = 1\\ \\text{J}$. Perhatikan simpangan dikuadratkan: menggandakan regangan melipatgandakan energi empat kali lipat." },
    { q: "Dua bola identik bertumbukan lenting sempurna di atas lantai licin. Bola A datang dengan kecepatan $v$ sedangkan bola B diam. Tepat setelah tumbukan ...", options: ["keduanya menempel dan bergerak bersama dengan kecepatan $v/2$", "bola A berhenti dan bola B bergerak dengan kecepatan $v$", "bola A memantul kembali dengan kecepatan $v$ sedangkan B tetap diam", "keduanya berhenti"], answer: 1, solution: "Pada tumbukan lenting sempurna momentum dan energi kinetik keduanya kekal. Untuk dua massa identik dengan satu mula-mula diam, satu-satunya penyelesaian yang memenuhi kedua hukum kekekalan adalah kedua benda saling bertukar kecepatan: A berhenti, B bergerak dengan $v$." },
    { q: "Sebuah gaya $10\\ \\text{N}$ bekerja tegak lurus pada ujung kunci pas yang panjangnya $0{,}5\\ \\text{m}$. Besar torsi terhadap baut (pusat putaran) adalah ...", options: ["$20\\ \\text{N}\\cdot\\text{m}$", "$2{,}5\\ \\text{N}\\cdot\\text{m}$", "$10\\ \\text{N}\\cdot\\text{m}$", "$5\\ \\text{N}\\cdot\\text{m}$"], answer: 3, solution: "Torsi $\\tau = r\\cdot F\\cdot\\sin\\theta$. Karena gaya tegak lurus lengan ($\\theta = 90^\\circ$, $\\sin 90^\\circ = 1$): $\\tau = 0{,}5\\cdot10\\cdot1 = 5\\ \\text{N}\\cdot\\text{m}$. Makin panjang kunci, makin besar torsi yang dihasilkan gaya yang sama." },
    { q: "Sebuah roda berputar dengan kelajuan $120\\ \\text{rpm}$ (putaran per menit). Frekuensi putaran roda tersebut adalah ...", options: ["$120\\ \\text{Hz}$", "$0{,}5\\ \\text{Hz}$", "$2\\ \\text{Hz}$", "$12\\ \\text{Hz}$"], answer: 2, solution: "Frekuensi adalah banyak putaran per sekon: $f = \\frac{120\\ \\text{putaran}}{60\\ \\text{s}} = 2\\ \\text{Hz}$. Periode putarannya $T = \\frac{1}{f} = 0{,}5\\ \\text{s}$." },
    { q: "Tekanan hidrostatis yang dialami penyelam pada kedalaman $2\\ \\text{m}$ di air ($\\rho = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$) adalah ...", options: ["$2000\\ \\text{Pa}$", "$10000\\ \\text{Pa}$", "$5000\\ \\text{Pa}$", "$20000\\ \\text{Pa}$"], answer: 3, solution: "Tekanan hidrostatis $P = \\rho\\cdot g\\cdot h = 1000\\cdot10\\cdot2 = 20000\\ \\text{Pa}$. Tekanan bertambah $10000\\ \\text{Pa}$ setiap bertambah $1\\ \\text{m}$ kedalaman — tidak bergantung pada bentuk wadah." },
    { q: "Sebuah balok bervolume $0{,}002\\ \\text{m}^3$ tercelup seluruhnya dalam air ($\\rho_{air} = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$). Besar gaya apung (Archimedes) yang dialami balok adalah ...", options: ["$2\\ \\text{N}$", "$20\\ \\text{N}$", "$200\\ \\text{N}$", "$2000\\ \\text{N}$"], answer: 1, solution: "Hukum Archimedes: gaya apung sama dengan berat fluida yang dipindahkan, $F_A = \\rho\\cdot g\\cdot V_{celup} = 1000\\cdot10\\cdot0{,}002 = 20\\ \\text{N}$. Gaya ini bergantung pada volume yang tercelup, bukan pada massa atau bentuk benda." },
    { q: "Sejumlah gas menerima kalor $500\\ \\text{J}$ dari lingkungan dan melakukan usaha $200\\ \\text{J}$ terhadap lingkungan. Perubahan energi dalam gas tersebut adalah ...", options: ["$300\\ \\text{J}$", "$700\\ \\text{J}$", "$-300\\ \\text{J}$", "$200\\ \\text{J}$"], answer: 0, solution: "Hukum I Termodinamika (konvensi fisika): $\\Delta U = Q - W$, dengan $Q$ positif jika sistem menerima kalor dan $W$ positif jika sistem melakukan usaha. $\\Delta U = 500 - 200 = 300\\ \\text{J}$ — energi dalam gas bertambah." },
    { q: "Air bermassa $2\\ \\text{kg}$ dipanaskan dari $20^\\circ\\text{C}$ menjadi $30^\\circ\\text{C}$. Jika kalor jenis air $4200\\ \\text{J/(kg}\\cdot^\\circ\\text{C)}$, kalor yang dibutuhkan adalah ...", options: ["$42000\\ \\text{J}$", "$168000\\ \\text{J}$", "$8400\\ \\text{J}$", "$84000\\ \\text{J}$"], answer: 3, solution: "Kalor untuk menaikkan suhu: $Q = m\\cdot c\\cdot\\Delta T = 2\\cdot4200\\cdot(30 - 20) = 2\\cdot4200\\cdot10 = 84000\\ \\text{J}$. Perhatikan $\\Delta T$ adalah selisih suhu ($10^\\circ\\text{C}$), bukan suhu akhirnya." },
    { q: "Sebuah gelombang memiliki panjang gelombang $2\\ \\text{m}$ dan frekuensi $5\\ \\text{Hz}$. Cepat rambat gelombang tersebut adalah ...", options: ["$2{,}5\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$25\\ \\text{m/s}$", "$0{,}4\\ \\text{m/s}$"], answer: 1, solution: "Hubungan dasar gelombang: $v = \\lambda\\cdot f = 2\\cdot5 = 10\\ \\text{m/s}$. Kesalahan umum: membagi $\\lambda$ dengan $f$ ($2/5 = 0{,}4$) — yang benar dikalikan." },
    { q: "Sebuah ambulans dengan sirene menyala bergerak mendekati pengamat yang diam. Frekuensi bunyi sirene yang didengar pengamat akan terdengar ...", options: ["lebih rendah", "tetap sama", "lebih tinggi", "menjadi nol"], answer: 2, solution: "Efek Doppler: ketika sumber bunyi mendekati pengamat, gelombang bunyi terkompresi sehingga panjang gelombang yang diterima mengecil dan frekuensi terdengar lebih tinggi. Inilah mengapa nada sirene meninggi saat ambulans mendekat." },
    { q: "Sebuah resistor $6\\ \\Omega$ dialiri arus $2\\ \\text{A}$. Tegangan pada ujung-ujung resistor adalah ...", options: ["$3\\ \\text{V}$", "$12\\ \\text{V}$", "$8\\ \\text{V}$", "$0{,}33\\ \\text{V}$"], answer: 1, solution: "Hukum Ohm: $V = I\\cdot R = 2\\cdot6 = 12\\ \\text{V}$. Tegangan berbanding lurus dengan arus untuk hambatan yang tetap." },
    { q: "Sebuah lampu bertuliskan $220\\ \\text{V}$ dialiri arus $0{,}5\\ \\text{A}$. Daya listrik yang dipakai lampu adalah ...", options: ["$440\\ \\text{W}$", "$220\\ \\text{W}$", "$110\\ \\text{W}$", "$55\\ \\text{W}$"], answer: 2, solution: "Daya listrik $P = V\\cdot I = 220\\cdot0{,}5 = 110\\ \\text{W}$. (Bentuk lain $P = I^2 R = V^2/R$ — ketiganya setara melalui Hukum Ohm.)" },
    { q: "Tiga resistor $2\\ \\Omega$, $3\\ \\Omega$, dan $5\\ \\Omega$ dirangkai seri dan dihubungkan ke baterai $20\\ \\text{V}$. Kuat arus yang mengalir dalam rangkaian adalah ...", options: ["$2\\ \\text{A}$", "$10\\ \\text{A}$", "$4\\ \\text{A}$", "$0{,}5\\ \\text{A}$"], answer: 0, solution: "Pada rangkaian seri hambatan total dijumlahkan: $R_{total} = 2 + 3 + 5 = 10\\ \\Omega$. Arus yang sama mengalir di semua resistor: $I = \\frac{V}{R_{total}} = \\frac{20}{10} = 2\\ \\text{A}$." },
    { q: "Dua kutub magnet yang sejenis (misalnya utara dengan utara) jika didekatkan akan ...", options: ["tarik-menarik", "tolak-menolak", "saling meniadakan", "melebur menjadi satu kutub"], answer: 1, solution: "Kutub magnet yang sejenis tolak-menolak, sedangkan kutub yang tak sejenis tarik-menarik. Ini analog dengan muatan listrik: sejenis menolak, tak sejenis menarik." },
    { q: "Sebuah bandul sederhana dengan panjang tali $1\\ \\text{m}$ diayunkan dengan simpangan kecil ($g = 10\\ \\text{m/s}^2 \\approx \\pi^2$). Periode ayunan bandul tersebut adalah ...", options: ["$1\\ \\text{s}$", "$\\pi\\ \\text{s}$", "$4\\ \\text{s}$", "$2\\ \\text{s}$"], answer: 3, solution: "Periode bandul sederhana untuk simpangan kecil: $T = 2\\pi\\sqrt{\\frac{L}{g}}$. Substitusi $L = 1$ dan $g \\approx \\pi^2$: $T = 2\\pi\\sqrt{\\frac{1}{\\pi^2}} = 2\\pi\\cdot\\frac{1}{\\pi} = 2\\ \\text{s}$. Perhatikan periode tidak bergantung pada massa bandul maupun amplitudo (selama simpangannya kecil)." },
    { q: "Sebuah benda bermassa $1\\ \\text{kg}$ digantung pada pegas dengan konstanta $4\\pi^2\\ \\text{N/m}$ lalu digetarkan. Frekuensi getaran harmoniknya adalah ...", options: ["$1\\ \\text{Hz}$", "$2\\pi\\ \\text{Hz}$", "$0{,}5\\ \\text{Hz}$", "$4\\pi\\ \\text{Hz}$"], answer: 0, solution: "1. Frekuensi sudut getaran massa-pegas $\\omega = \\sqrt{\\frac{k}{m}} = \\sqrt{\\frac{4\\pi^2}{1}} = 2\\pi\\ \\text{rad/s}$. 2. Frekuensi $f = \\frac{\\omega}{2\\pi} = \\frac{2\\pi}{2\\pi} = 1\\ \\text{Hz}$. 3. Kesalahan umum: menjawab $2\\pi\\ \\text{Hz}$ — itu frekuensi sudut $\\omega$, bukan frekuensi $f$; keduanya berbeda faktor $2\\pi$." },
    { q: "Benda $2\\ \\text{kg}$ bergetar harmonik pada pegas dengan konstanta $8\\ \\text{N/m}$. Periode getarannya adalah ...", options: ["$2\\pi\\ \\text{s}$", "$\\frac{\\pi}{2}\\ \\text{s}$", "$\\pi\\ \\text{s}$", "$\\pi^2\\ \\text{s}$"], answer: 2, solution: "1. Periode massa-pegas $T = 2\\pi\\sqrt{\\frac{m}{k}} = 2\\pi\\sqrt{\\frac{2}{8}} = 2\\pi\\sqrt{\\frac{1}{4}}$. 2. Karena $\\sqrt{\\frac{1}{4}} = \\frac{1}{2}$, maka $T = 2\\pi\\cdot\\frac{1}{2} = \\pi\\ \\text{s}$. 3. Periode berbanding lurus dengan akar massa dan berbanding terbalik dengan akar konstanta pegas." },
    { q: "Pegas dengan konstanta $200\\ \\text{N/m}$ digetarkan dengan amplitudo $0{,}1\\ \\text{m}$. Energi mekanik total getaran tersebut adalah ...", options: ["$20\\ \\text{J}$", "$1\\ \\text{J}$", "$2\\ \\text{J}$", "$10\\ \\text{J}$"], answer: 1, solution: "1. Energi mekanik getaran harmonik $E = \\frac{1}{2}kA^2$. 2. $E = \\frac{1}{2}\\cdot200\\cdot(0{,}1)^2 = 100\\cdot0{,}01 = 1\\ \\text{J}$. 3. Kesalahan umum: memakai $kA = 20\\ \\text{J}$ (lupa faktor $\\frac{1}{2}$ dan kuadrat) atau $kA^2 = 2\\ \\text{J}$ (lupa faktor $\\frac{1}{2}$)." },
    { q: "Benda bergetar harmonik dengan amplitudo $0{,}05\\ \\text{m}$ dan periode $1\\ \\text{s}$. Kelajuan maksimum benda adalah ...", options: ["$\\pi\\ \\text{m/s}$", "$0{,}2\\pi\\ \\text{m/s}$", "$0{,}05\\pi\\ \\text{m/s}$", "$0{,}1\\pi\\ \\text{m/s}$"], answer: 3, solution: "1. Frekuensi sudut $\\omega = \\frac{2\\pi}{T} = \\frac{2\\pi}{1} = 2\\pi\\ \\text{rad/s}$. 2. Kelajuan maksimum terjadi saat melewati titik setimbang: $v_{maks} = A\\omega = 0{,}05\\cdot2\\pi = 0{,}1\\pi\\ \\text{m/s}$. 3. Jangan tertukar dengan $A^2\\omega$ atau $A\\omega^2$ — dimensi $v_{maks}$ harus $\\text{m/s}$." },
    { q: "Sebuah benda bergetar harmonik dengan amplitudo $A$ dan energi mekanik total $E$. Saat simpangannya $x = \\frac{A}{2}$, perbandingan energi kinetik terhadap $E$ adalah ...", options: ["$\\frac{3}{4}$", "$\\frac{1}{2}$", "$\\frac{1}{4}$", "$1$"], answer: 0, solution: "1. Energi potensial saat itu $E_p = \\frac{1}{2}kx^2 = \\frac{1}{2}k\\left(\\frac{A}{2}\\right)^2 = \\frac{1}{4}\\left(\\frac{1}{2}kA^2\\right) = \\frac{E}{4}$. 2. Energi kinetik $E_k = E - E_p = E - \\frac{E}{4} = \\frac{3E}{4}$. 3. Jadi perbandingannya $\\frac{3}{4}$ — makin jauh dari titik setimbang, porsi energi kinetik makin kecil." },
    { q: "Sebuah ayunan didorong secara periodik. Amplitudo ayunan menjadi paling besar ketika ...", options: ["frekuensi dorongan jauh lebih besar dari frekuensi alami ayunan", "frekuensi dorongan sama dengan frekuensi alami ayunan", "frekuensi dorongan setengah dari frekuensi alami ayunan", "ayunan tidak pernah didorong"], answer: 1, solution: "1. Fenomena ini disebut resonansi: sistem menyerap energi paling efisien dari gaya luar yang frekuensinya cocok. 2. Saat frekuensi gaya luar sama dengan frekuensi alami sistem, setiap dorongan tiba tepat sefase dengan gerakan sehingga amplitudo membesar. 3. Contoh nyata: mendorong ayunan anak tepat pada ritme ayunannya, atau kaca yang pecah oleh nada suara tertentu." },
    { q: "Simpangan gelombang berjalan memenuhi $y = 0{,}2\\sin(2x - 8t)$ ($y$, $x$ dalam meter, $t$ dalam sekon). Cepat rambat gelombang tersebut adalah ...", options: ["$16\\ \\text{m/s}$", "$0{,}25\\ \\text{m/s}$", "$4\\ \\text{m/s}$", "$2\\ \\text{m/s}$"], answer: 2, solution: "1. Bentuk umum $y = A\\sin(kx - \\omega t)$ dengan bilangan gelombang $k = 2\\ \\text{m}^{-1}$ dan frekuensi sudut $\\omega = 8\\ \\text{rad/s}$. 2. Cepat rambat $v = \\frac{\\omega}{k} = \\frac{8}{2} = 4\\ \\text{m/s}$. 3. Kesalahan umum: mengalikan $\\omega\\cdot k = 16$ — yang benar dibagi." },
    { q: "Pada gelombang stasioner dengan panjang gelombang $0{,}6\\ \\text{m}$, jarak antara dua simpul yang berurutan adalah ...", options: ["$0{,}3\\ \\text{m}$", "$0{,}6\\ \\text{m}$", "$1{,}2\\ \\text{m}$", "$0{,}15\\ \\text{m}$"], answer: 0, solution: "1. Simpul-simpul pada gelombang stasioner terpisah sejauh setengah panjang gelombang. 2. Jaraknya $\\frac{\\lambda}{2} = \\frac{0{,}6}{2} = 0{,}3\\ \\text{m}$. 3. Hal yang sama berlaku untuk jarak dua perut berurutan, sedangkan jarak simpul ke perut terdekat adalah $\\frac{\\lambda}{4}$." },
    { q: "Pipa organa yang terbuka di kedua ujungnya memiliki panjang $1\\ \\text{m}$. Jika cepat rambat bunyi di udara $340\\ \\text{m/s}$, frekuensi nada dasar pipa tersebut adalah ...", options: ["$340\\ \\text{Hz}$", "$85\\ \\text{Hz}$", "$680\\ \\text{Hz}$", "$170\\ \\text{Hz}$"], answer: 3, solution: "1. Pada pipa terbuka, nada dasar memenuhi $L = \\frac{\\lambda}{2}$ sehingga $\\lambda = 2L = 2\\ \\text{m}$. 2. Frekuensi $f = \\frac{v}{\\lambda} = \\frac{340}{2} = 170\\ \\text{Hz}$. 3. Ingat pada kedua ujung terbuka terbentuk perut simpangan, sehingga setengah gelombang pas sepanjang pipa." },
    { q: "Seutas tali $1{,}2\\ \\text{m}$ dengan kedua ujung terikat bergetar pada harmonik ketiga. Panjang gelombang yang terbentuk adalah ...", options: ["$1{,}2\\ \\text{m}$", "$0{,}8\\ \\text{m}$", "$0{,}4\\ \\text{m}$", "$2{,}4\\ \\text{m}$"], answer: 1, solution: "1. Untuk tali ujung terikat, harmonik ke-$n$ memenuhi $L = n\\cdot\\frac{\\lambda}{2}$. 2. Dengan $n = 3$: $1{,}2 = 3\\cdot\\frac{\\lambda}{2} \\Rightarrow \\lambda = \\frac{2\\cdot1{,}2}{3} = 0{,}8\\ \\text{m}$. 3. Pada harmonik ketiga terdapat $3$ perut dan $4$ simpul di sepanjang tali." },
    { q: "Air mengalir dalam pipa yang menyempit dari luas penampang $4\\ \\text{cm}^2$ menjadi $2\\ \\text{cm}^2$. Jika kelajuan air di bagian yang lebar $3\\ \\text{m/s}$, kelajuannya di bagian yang sempit adalah ...", options: ["$1{,}5\\ \\text{m/s}$", "$12\\ \\text{m/s}$", "$6\\ \\text{m/s}$", "$3\\ \\text{m/s}$"], answer: 2, solution: "1. Persamaan kontinuitas untuk fluida tak termampatkan: $A_1 v_1 = A_2 v_2$. 2. $v_2 = \\frac{A_1}{A_2}v_1 = \\frac{4}{2}\\cdot3 = 6\\ \\text{m/s}$. 3. Luas penampang mengecil setengahnya, kelajuan menjadi dua kali lipat — satuan $\\text{cm}^2$ saling meniadakan sehingga tak perlu dikonversi." },
    { q: "Tangki air bocor pada dindingnya $1{,}8\\ \\text{m}$ di bawah permukaan air ($g = 10\\ \\text{m/s}^2$). Kelajuan air yang menyembur keluar adalah ...", options: ["$6\\ \\text{m/s}$", "$3\\ \\text{m/s}$", "$18\\ \\text{m/s}$", "$36\\ \\text{m/s}$"], answer: 0, solution: "1. Teorema Torricelli: $v = \\sqrt{2gh}$. 2. $v = \\sqrt{2\\cdot10\\cdot1{,}8} = \\sqrt{36} = 6\\ \\text{m/s}$. 3. Hasilnya sama seperti kelajuan benda jatuh bebas dari ketinggian $h$ — jangan lupa faktor $2$ di dalam akar." },
    { q: "Air mengalir mantap dalam pipa horizontal yang menyempit. Di bagian yang sempit, kelajuan air ... dan tekanannya ...", options: ["berkurang, bertambah", "bertambah, berkurang", "tetap, bertambah", "bertambah, tetap"], answer: 1, solution: "1. Dari persamaan kontinuitas, penampang menyempit berarti kelajuan bertambah. 2. Dari persamaan Bernoulli $p + \\frac{1}{2}\\rho v^2 = \\text{tetap}$ (pipa horizontal), kelajuan yang bertambah membuat tekanan berkurang. 3. Inilah prinsip kerja venturimeter dan gaya angkat pada sayap pesawat." },
    { q: "Air ($\\rho = 1000\\ \\text{kg/m}^3$) mengalir dalam pipa horizontal. Di bagian sempit kelajuannya $4\\ \\text{m/s}$ dan tekanannya $10000\\ \\text{Pa}$; di bagian yang lebih lebar kelajuannya $2\\ \\text{m/s}$. Tekanan di bagian yang lebar adalah ...", options: ["$4000\\ \\text{Pa}$", "$10000\\ \\text{Pa}$", "$20000\\ \\text{Pa}$", "$16000\\ \\text{Pa}$"], answer: 3, solution: "1. Bernoulli untuk pipa horizontal: $p_1 + \\frac{1}{2}\\rho v_1^2 = p_2 + \\frac{1}{2}\\rho v_2^2$. 2. $p_2 = p_1 + \\frac{1}{2}\\rho(v_1^2 - v_2^2) = 10000 + \\frac{1}{2}\\cdot1000\\cdot(16 - 4) = 10000 + 6000 = 16000\\ \\text{Pa}$. 3. Kelajuan turun, tekanan naik — konsisten dengan prinsip Bernoulli." },
    { q: "Air mengalir dalam pipa berpenampang $0{,}02\\ \\text{m}^2$ dengan kelajuan $3\\ \\text{m/s}$. Debit aliran air tersebut adalah ...", options: ["$0{,}06\\ \\text{m}^3/\\text{s}$", "$60\\ \\text{m}^3/\\text{s}$", "$0{,}006\\ \\text{m}^3/\\text{s}$", "$6\\ \\text{m}^3/\\text{s}$"], answer: 0, solution: "1. Debit $Q = A\\cdot v$ (volume per satuan waktu). 2. $Q = 0{,}02\\cdot3 = 0{,}06\\ \\text{m}^3/\\text{s}$ — setara $60$ liter per sekon. 3. Perhatikan posisi koma desimal: $0{,}02\\cdot3$ bukan $0{,}6$ atau $60$." },
    { q: "Kumparan $10$ lilitan mengalami perubahan fluks magnetik sebesar $0{,}4\\ \\text{Wb}$ dalam waktu $0{,}2\\ \\text{s}$. Besar GGL induksi yang timbul adalah ...", options: ["$2\\ \\text{V}$", "$0{,}8\\ \\text{V}$", "$20\\ \\text{V}$", "$8\\ \\text{V}$"], answer: 2, solution: "1. Hukum Faraday: $\\varepsilon = -N\\frac{\\Delta\\Phi}{\\Delta t}$ (tanda negatif menyatakan Hukum Lenz: arah arus melawan perubahan). 2. Besar GGL $= 10\\cdot\\frac{0{,}4}{0{,}2} = 10\\cdot2 = 20\\ \\text{V}$. 3. Kesalahan umum: lupa mengalikan dengan jumlah lilitan $N$ sehingga menjawab $2\\ \\text{V}$." },
    { q: "Sebatang kawat $0{,}4\\ \\text{m}$ digerakkan dengan kelajuan $10\\ \\text{m/s}$ memotong tegak lurus medan magnet $0{,}5\\ \\text{T}$. GGL induksi pada ujung-ujung kawat adalah ...", options: ["$20\\ \\text{V}$", "$2\\ \\text{V}$", "$0{,}2\\ \\text{V}$", "$5\\ \\text{V}$"], answer: 1, solution: "1. GGL gerak pada kawat yang memotong medan magnet: $\\varepsilon = B\\cdot l\\cdot v$. 2. $\\varepsilon = 0{,}5\\cdot0{,}4\\cdot10 = 2\\ \\text{V}$. 3. Rumus ini berlaku saat $B$, $l$, dan $v$ saling tegak lurus; jika ada sudut, kalikan dengan $\\sin\\theta$." },
    { q: "Sebuah induktor $0{,}2\\ \\text{H}$ dialiri arus yang berubah $5\\ \\text{A/s}$. Besar GGL induksi diri yang timbul adalah ...", options: ["$25\\ \\text{V}$", "$0{,}04\\ \\text{V}$", "$4\\ \\text{V}$", "$1\\ \\text{V}$"], answer: 3, solution: "1. GGL induksi diri $\\varepsilon = -L\\frac{dI}{dt}$ — induktor melawan perubahan arus (Hukum Lenz). 2. Besar GGL $= 0{,}2\\cdot5 = 1\\ \\text{V}$. 3. Makin besar induktansi, makin kuat induktor menahan perubahan arus yang melaluinya." },
    { q: "Arus bolak-balik memiliki nilai maksimum $5\\ \\text{A}$. Nilai efektif (rms) arus tersebut adalah ...", options: ["$\\frac{5\\sqrt{2}}{2}\\ \\text{A}$", "$5\\sqrt{2}\\ \\text{A}$", "$5\\ \\text{A}$", "$2{,}5\\ \\text{A}$"], answer: 0, solution: "1. Nilai efektif arus sinusoidal $I_{rms} = \\frac{I_m}{\\sqrt{2}}$. 2. $I_{rms} = \\frac{5}{\\sqrt{2}} = \\frac{5\\sqrt{2}}{2}\\ \\text{A} \\approx 3{,}54\\ \\text{A}$. 3. Nilai efektif inilah yang setara dengan arus searah dalam menghasilkan daya/panas — bukan nilai maksimumnya." },
    { q: "Cahaya kuning berfrekuensi $6\\times10^{14}\\ \\text{Hz}$ merambat di vakum ($c = 3\\times10^8\\ \\text{m/s}$). Panjang gelombangnya adalah ...", options: ["$5\\times10^{-8}\\ \\text{m}$", "$2\\times10^6\\ \\text{m}$", "$5\\times10^{-7}\\ \\text{m}$", "$1{,}8\\times10^{23}\\ \\text{m}$"], answer: 2, solution: "1. Untuk semua gelombang elektromagnetik berlaku $c = \\lambda f$. 2. $\\lambda = \\frac{c}{f} = \\frac{3\\times10^8}{6\\times10^{14}} = 0{,}5\\times10^{-6} = 5\\times10^{-7}\\ \\text{m}$ (500 nm). 3. Kesalahan umum: membalik menjadi $\\lambda = \\frac{f}{c}$ — periksa dimensinya, $\\lambda$ harus dalam meter." },
{ q: "Sebuah mobil melaju $20\\ \\text{m/s}$ lalu direm dengan perlambatan tetap $4\\ \\text{m/s}^2$ hingga berhenti. Jarak pengereman mobil tersebut adalah ...", options: ["$100\\ \\text{m}$", "$25\\ \\text{m}$", "$80\\ \\text{m}$", "$50\\ \\text{m}$"], answer: 3, solution: "1. Perlambatan berarti $a = -4\\ \\text{m/s}^2$ dan mobil berhenti sehingga $v = 0$. 2. Gunakan $v^2 = v_0^2 + 2as$: $0 = 20^2 + 2(-4)s \\Rightarrow 8s = 400 \\Rightarrow s = 50\\ \\text{m}$. 3. Kesalahan umum: lupa faktor $2$ sehingga menghitung $s = v_0^2/a = 100\\ \\text{m}$." },
    { q: "Sebuah motor bergerak dengan kecepatan awal $5\\ \\text{m/s}$ dan percepatan tetap $3\\ \\text{m/s}^2$. Jarak yang ditempuh motor setelah $4\\ \\text{s}$ adalah ...", options: ["$68\\ \\text{m}$", "$20\\ \\text{m}$", "$44\\ \\text{m}$", "$32\\ \\text{m}$"], answer: 2, solution: "1. Gunakan $s = v_0 t + \\frac{1}{2}at^2 = 5\\cdot4 + \\frac{1}{2}\\cdot3\\cdot4^2$. 2. Hitung: $20 + 24 = 44\\ \\text{m}$. 3. Kesalahan umum: menjumlahkan $v_0 + a$ lalu dikali $t$ sehingga dapat $32\\ \\text{m}$, atau lupa faktor $\\frac{1}{2}$ sehingga dapat $68\\ \\text{m}$." },
    { q: "Mobil A mulai dari diam dengan percepatan $2\\ \\text{m/s}^2$. Pada saat yang sama mobil B berada $24\\ \\text{m}$ di depan A dan bergerak searah dengan kecepatan tetap $4\\ \\text{m/s}$. Mobil A menyusul B setelah ...", options: ["$4\\ \\text{s}$", "$6\\ \\text{s}$", "$8\\ \\text{s}$", "$12\\ \\text{s}$"], answer: 1, solution: "1. Jarak A: $s_A = \\frac{1}{2}\\cdot2\\cdot t^2 = t^2$; jarak B: $s_B = 24 + 4t$. 2. Menyusul berarti posisi sama: $t^2 = 24 + 4t \\Rightarrow t^2 - 4t - 24 = 0 \\Rightarrow (t-6)(t+4) = 0$. 3. Ambil $t$ positif: $t = 6\\ \\text{s}$. Kesalahan umum: menyamakan kecepatan ($2t = 4$) — itu waktu kecepatannya sama, bukan waktu menyusul." },
    { q: "Sebuah kereta bergerak $30\\ \\text{m/s}$ lalu diperlambat $5\\ \\text{m/s}^2$ hingga berhenti. Jarak yang ditempuh kereta selama pengereman adalah ...", options: ["$90\\ \\text{m}$", "$180\\ \\text{m}$", "$45\\ \\text{m}$", "$60\\ \\text{m}$"], answer: 0, solution: "1. Gunakan $v^2 = v_0^2 - 2as$ dengan $v = 0$: $0 = 30^2 - 2\\cdot5\\cdot s$. 2. $10s = 900 \\Rightarrow s = 90\\ \\text{m}$. 3. Kesalahan umum: memakai $s = v_0^2/a = 180\\ \\text{m}$ karena lupa faktor $2$ pada rumus." },
    { q: "Sebuah mobil melaju $60\\ \\text{km/jam}$ selama $2\\ \\text{jam}$, kemudian $90\\ \\text{km/jam}$ selama $1\\ \\text{jam}$. Kecepatan rata-rata mobil selama perjalanan adalah ...", options: ["$75\\ \\text{km/jam}$", "$105\\ \\text{km/jam}$", "$60\\ \\text{km/jam}$", "$70\\ \\text{km/jam}$"], answer: 3, solution: "1. Jarak tahap 1: $60\\cdot2 = 120\\ \\text{km}$; tahap 2: $90\\cdot1 = 90\\ \\text{km}$; total $210\\ \\text{km}$ dalam $3\\ \\text{jam}$. 2. Kecepatan rata-rata $= \\frac{210}{3} = 70\\ \\text{km/jam}$. 3. Kesalahan umum: merata-ratakan kecepatannya langsung $\\frac{60+90}{2} = 75\\ \\text{km/jam}$ — itu hanya benar bila waktu tempuh kedua tahap sama." },
    { q: "Sebuah benda diperlambat dari $30\\ \\text{m/s}$ menjadi $10\\ \\text{m/s}$ setelah menempuh jarak $100\\ \\text{m}$. Besar perlambatan benda tersebut adalah ...", options: ["$-8\\ \\text{m/s}^2$", "$-2\\ \\text{m/s}^2$", "$-4\\ \\text{m/s}^2$", "$-40\\ \\text{m/s}^2$"], answer: 2, solution: "1. Gunakan $v^2 = v_0^2 + 2as$: $10^2 = 30^2 + 2\\cdot a\\cdot100$. 2. $100 - 900 = 200a \\Rightarrow a = \\frac{-800}{200} = -4\\ \\text{m/s}^2$ (tanda negatif menunjukkan perlambatan). 3. Kesalahan umum: lupa faktor $2$ sehingga mendapat $-8\\ \\text{m/s}^2$." },
    { q: "Sebuah mobil mulai dari diam dan dipercepat $2\\ \\text{m/s}^2$ selama $5\\ \\text{s}$, kemudian bergerak dengan kecepatan tetap selama $10\\ \\text{s}$. Jarak total yang ditempuh mobil adalah ...", options: ["$100\\ \\text{m}$", "$125\\ \\text{m}$", "$150\\ \\text{m}$", "$75\\ \\text{m}$"], answer: 1, solution: "1. Tahap dipercepat: $s_1 = \\frac{1}{2}\\cdot2\\cdot5^2 = 25\\ \\text{m}$, kecepatan akhir $v = 2\\cdot5 = 10\\ \\text{m/s}$. 2. Tahap kecepatan tetap: $s_2 = 10\\cdot10 = 100\\ \\text{m}$. 3. Total $25 + 100 = 125\\ \\text{m}$. Kesalahan umum: hanya menghitung tahap kedua ($100\\ \\text{m}$) karena lupa mobil sudah menempuh jarak saat dipercepat." },
    { q: "Sebuah benda mulai dari diam dan dipercepat tetap $6\\ \\text{m/s}^2$ hingga menempuh jarak $75\\ \\text{m}$. Waktu yang dibutuhkan adalah ...", options: ["$5\\ \\text{s}$", "$25\\ \\text{s}$", "$12{,}5\\ \\text{s}$", "$2{,}5\\ \\text{s}$"], answer: 0, solution: "1. $s = \\frac{1}{2}at^2$ dengan $v_0 = 0$: $75 = \\frac{1}{2}\\cdot6\\cdot t^2 = 3t^2$. 2. $t^2 = 25 \\Rightarrow t = 5\\ \\text{s}$ (ambil akar positif). 3. Kesalahan umum: menjawab $25\\ \\text{s}$ — itu nilai $t^2$, jangan lupa diakarkan." },
    { q: "Seorang pengendara melaju dengan kecepatan tetap $72\\ \\text{km/jam}$ selama $3\\ \\text{menit}$. Jarak yang ditempuhnya adalah ...", options: ["$216\\ \\text{km}$", "$21{,}6\\ \\text{km}$", "$360\\ \\text{km}$", "$3{,}6\\ \\text{km}$"], answer: 3, solution: "1. Samakan satuan: $72\\ \\text{km/jam} = \\frac{72\\cdot1000}{3600} = 20\\ \\text{m/s}$; $3\\ \\text{menit} = 180\\ \\text{s}$. 2. $s = v\\cdot t = 20\\cdot180 = 3600\\ \\text{m} = 3{,}6\\ \\text{km}$. 3. Kesalahan umum: langsung mengalikan $72\\times3 = 216$ tanpa menyamakan satuan waktu." },
    { q: "Grafik kecepatan terhadap waktu sebuah benda berupa garis lurus dari titik $(0, 0)$ ke $(10\\ \\text{s}, 20\\ \\text{m/s})$. Jarak yang ditempuh benda selama $10\\ \\text{s}$ adalah ...", options: ["$200\\ \\text{m}$", "$20\\ \\text{m}$", "$100\\ \\text{m}$", "$10\\ \\text{m}$"], answer: 2, solution: "1. Pada grafik $v$-$t$, jarak = luas daerah di bawah kurva. 2. Luas segitiga $= \\frac{1}{2}\\cdot\\text{alas}\\cdot\\text{tinggi} = \\frac{1}{2}\\cdot10\\cdot20 = 100\\ \\text{m}$. 3. Kesalahan umum: menghitung luas persegi panjang $10\\times20 = 200\\ \\text{m}$ — itu hanya berlaku untuk grafik kecepatan tetap." },
    { q: "Sebuah truk mulai dari diam dengan percepatan tetap dan menempuh $144\\ \\text{m}$ dalam $6\\ \\text{s}$. Kecepatan truk pada akhir detik ke-$6$ adalah ...", options: ["$24\\ \\text{m/s}$", "$48\\ \\text{m/s}$", "$96\\ \\text{m/s}$", "$12\\ \\text{m/s}$"], answer: 1, solution: "1. $s = \\frac{1}{2}at^2$: $144 = \\frac{1}{2}\\cdot a\\cdot36 \\Rightarrow 18a = 144 \\Rightarrow a = 8\\ \\text{m/s}^2$. 2. $v = v_0 + at = 0 + 8\\cdot6 = 48\\ \\text{m/s}$. 3. Kesalahan umum: memakai $v = s/t = 24\\ \\text{m/s}$ — itu kecepatan rata-rata, bukan kecepatan akhir." },
    { q: "Sebuah mobil bergerak $20\\ \\text{m/s}$ dan berhenti $4\\ \\text{s}$ kemudian akibat pengereman tetap. Jarak yang ditempuh selama pengereman adalah ...", options: ["$40\\ \\text{m}$", "$80\\ \\text{m}$", "$20\\ \\text{m}$", "$60\\ \\text{m}$"], answer: 0, solution: "1. $a = \\frac{\\Delta v}{t} = \\frac{0-20}{4} = -5\\ \\text{m/s}^2$. 2. $s = v_0 t + \\frac{1}{2}at^2 = 80 - 40 = 40\\ \\text{m}$ (atau luas segitiga $\\frac{1}{2}\\cdot20\\cdot4$). 3. Kesalahan umum: $s = v_0 t = 80\\ \\text{m}$ — itu jarak jika kecepatan tidak berkurang." },
    { q: "Sebuah bola dilempar vertikal ke atas dengan kecepatan awal $30\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Ketinggian maksimum yang dicapai bola adalah ...", options: ["$90\\ \\text{m}$", "$15\\ \\text{m}$", "$60\\ \\text{m}$", "$45\\ \\text{m}$"], answer: 3, solution: "1. Pada titik tertinggi $v = 0$; gunakan $v^2 = v_0^2 - 2gh$. 2. $0 = 30^2 - 2\\cdot10\\cdot h \\Rightarrow 20h = 900 \\Rightarrow h = 45\\ \\text{m}$. 3. Kesalahan umum: lupa faktor $2$ pada $2gh$ sehingga mendapat $90\\ \\text{m}$." },
    { q: "Sebuah bola dilempar vertikal ke atas dengan kecepatan awal $30\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Waktu yang dibutuhkan bola untuk mencapai titik tertinggi adalah ...", options: ["$6\\ \\text{s}$", "$1{,}5\\ \\text{s}$", "$3\\ \\text{s}$", "$30\\ \\text{s}$"], answer: 2, solution: "1. Di titik tertinggi $v = 0$, gunakan $v = v_0 - gt$. 2. $0 = 30 - 10t \\Rightarrow t = 3\\ \\text{s}$. 3. Jangan tertukar dengan waktu total kembali ke tanah ($6\\ \\text{s}$) — waktu naik hanya setengahnya." },
    { q: "Sebuah bola dilempar vertikal ke atas dan kembali ke titik pelemparan setelah $6\\ \\text{s}$ ($g = 10\\ \\text{m/s}^2$). Waktu yang dibutuhkan bola dari titik tertinggi kembali ke titik pelemparan adalah ...", options: ["$3\\ \\text{s}$", "$6\\ \\text{s}$", "$12\\ \\text{s}$", "$9\\ \\text{s}$"], answer: 1, solution: "1. Gerak naik dan turun simetris: waktu turun = waktu naik. 2. Waktu naik $= 6/2 = 3\\ \\text{s}$, jadi waktu turunnya juga $3\\ \\text{s}$. 3. Kesalahan umum: menjawab $6\\ \\text{s}$ — itu waktu total, bukan waktu turunnya saja." }
,
    { q: "Sebuah bola dilempar vertikal ke atas dengan kecepatan $20\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Kecepatan bola $3\\ \\text{s}$ setelah dilempar adalah ...", options: ["$10\\ \\text{m/s}$ ke bawah", "$10\\ \\text{m/s}$ ke atas", "$50\\ \\text{m/s}$ ke bawah", "$0\\ \\text{m/s}$"], answer: 0, solution: "1. $v = v_0 - gt = 20 - 10\\cdot3 = -10\\ \\text{m/s}$. 2. Tanda negatif berarti arahnya ke bawah: $10\\ \\text{m/s}$ ke bawah (bola sudah melewati titik tertinggi). 3. Kesalahan umum: berhenti di $v = 20 - 10 = 10$ karena lupa mengalikan $g$ dengan $t$, lalu menyimpulkan bola masih bergerak ke atas." },
    { q: "Bola A dijatuhkan dari sebuah menara. Satu sekon kemudian bola B dijatuhkan dari titik yang sama. Setelah A jatuh selama $3\\ \\text{s}$, jarak antara kedua bola adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$15\\ \\text{m}$", "$5\\ \\text{m}$", "$45\\ \\text{m}$", "$25\\ \\text{m}$"], answer: 3, solution: "1. Jarak A setelah $3\\ \\text{s}$: $s_A = \\frac{1}{2}\\cdot10\\cdot3^2 = 45\\ \\text{m}$; jarak B setelah $2\\ \\text{s}$: $s_B = \\frac{1}{2}\\cdot10\\cdot2^2 = 20\\ \\text{m}$. 2. Selisih $45 - 20 = 25\\ \\text{m}$. 3. Kesalahan umum: mengira selisihnya tetap — karena keduanya dipercepat $g$, selisih jarak justru membesar terhadap waktu." },
    { q: "Sebuah batu dilempar vertikal ke bawah dengan kecepatan awal $20\\ \\text{m/s}$ dari ketinggian $60\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Waktu yang dibutuhkan batu mencapai tanah adalah ...", options: ["$3\\ \\text{s}$", "$4\\ \\text{s}$", "$2\\ \\text{s}$", "$6\\ \\text{s}$"], answer: 2, solution: "1. $h = v_0 t + \\frac{1}{2}gt^2$: $60 = 20t + 5t^2$. 2. Bagi 5: $t^2 + 4t - 12 = 0 \\Rightarrow (t+6)(t-2) = 0 \\Rightarrow t = 2\\ \\text{s}$ (ambil akar positif). 3. Kesalahan umum: memakai rumus jatuh bebas $h = \\frac{1}{2}gt^2$ seolah $v_0 = 0$ — padahal ada suku $v_0 t$." },
    { q: "Sebuah benda jatuh bebas dari keadaan diam. Jarak yang ditempuh benda selama selang waktu antara sekon ke-$2$ dan sekon ke-$4$ adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$20\\ \\text{m}$", "$60\\ \\text{m}$", "$80\\ \\text{m}$", "$40\\ \\text{m}$"], answer: 1, solution: "1. $s(2) = \\frac{1}{2}\\cdot10\\cdot2^2 = 20\\ \\text{m}$; $s(4) = \\frac{1}{2}\\cdot10\\cdot4^2 = 80\\ \\text{m}$. 2. Jarak pada selang itu $= 80 - 20 = 60\\ \\text{m}$. 3. Kesalahan umum: menghitung $\\frac{1}{2}g(\\Delta t)^2 = 20\\ \\text{m}$ — rumus itu hanya berlaku untuk selang yang dimulai dari keadaan diam." },
    { q: "Sebuah bola dilempar vertikal ke atas dan kembali ke tangan pelempar setelah $8\\ \\text{s}$ ($g = 10\\ \\text{m/s}^2$). Ketinggian maksimum bola adalah ...", options: ["$80\\ \\text{m}$", "$160\\ \\text{m}$", "$40\\ \\text{m}$", "$320\\ \\text{m}$"], answer: 0, solution: "1. Waktu naik $= 8/2 = 4\\ \\text{s}$, maka $v_0 = g\\cdot t_{naik} = 10\\cdot4 = 40\\ \\text{m/s}$. 2. $h_{maks} = \\frac{v_0^2}{2g} = \\frac{1600}{20} = 80\\ \\text{m}$. 3. Kesalahan umum: memakai seluruh waktu $8\\ \\text{s}$ sebagai waktu naik sehingga hasilnya kegedean empat kali lipat." },
    { q: "Sebuah proyektil ditembakkan dengan kecepatan awal $25\\ \\text{m/s}$ membentuk sudut $53^\\circ$ terhadap horizontal ($\\sin53^\\circ = 0{,}8$; $g = 10\\ \\text{m/s}^2$). Tinggi maksimum proyektil adalah ...", options: ["$40\\ \\text{m}$", "$10\\ \\text{m}$", "$32\\ \\text{m}$", "$20\\ \\text{m}$"], answer: 3, solution: "1. Uraikan kecepatan awal vertikal: $v_{0y} = v_0\\sin53^\\circ = 25\\cdot0{,}8 = 20\\ \\text{m/s}$. 2. $h_{maks} = \\frac{v_{0y}^2}{2g} = \\frac{400}{20} = 20\\ \\text{m}$. 3. Kesalahan umum: memakai seluruh $v_0 = 25\\ \\text{m/s}$ bukan komponen vertikalnya — komponen horizontal tidak memengaruhi tinggi." },
    { q: "Sebuah proyektil ditembakkan dengan sudut elevasi $45^\\circ$ dan jatuh pada jarak mendatar $40\\ \\text{m}$ dari titik penembakan ($g = 10\\ \\text{m/s}^2$). Kecepatan awal proyektil adalah ...", options: ["$40\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$20\\ \\text{m/s}$", "$20\\sqrt{2}\\ \\text{m/s}$"], answer: 2, solution: "1. Sudut $45^\\circ$ memberi $\\sin2\\theta = \\sin90^\\circ = 1$, sehingga $R = \\frac{v_0^2}{g}$. 2. $40 = \\frac{v_0^2}{10} \\Rightarrow v_0^2 = 400 \\Rightarrow v_0 = 20\\ \\text{m/s}$. 3. Kesalahan umum: mengira nilai $R$ sama dengan $v_0$ secara numerik — dimensi dan rumusnya tidak cocok." },
    { q: "Sebuah bola ditembakkan horizontal dengan kecepatan $10\\ \\text{m/s}$ dari tepi tebing setinggi $45\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Jarak mendatar bola dari kaki tebing saat mencapai tanah adalah ...", options: ["$45\\ \\text{m}$", "$30\\ \\text{m}$", "$20\\ \\text{m}$", "$15\\ \\text{m}$"], answer: 1, solution: "1. Gerak vertikal menentukan waktu jatuh: $h = \\frac{1}{2}gt^2 \\Rightarrow 45 = 5t^2 \\Rightarrow t = 3\\ \\text{s}$. 2. Gerak horizontal berkecepatan tetap: $x = v_0 t = 10\\cdot3 = 30\\ \\text{m}$. 3. Kesalahan umum: memakai $v_0$ pada gerak vertikal — kecepatan awal horizontal tidak memengaruhi waktu jatuh." },
    { q: "Sebuah paket dijatuhkan horizontal dengan kecepatan $15\\ \\text{m/s}$ dari helikopter pada ketinggian $80\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$, abaikan gesekan udara). Waktu yang dibutuhkan paket mencapai tanah adalah ...", options: ["$4\\ \\text{s}$", "$8\\ \\text{s}$", "$2\\ \\text{s}$", "$16\\ \\text{s}$"], answer: 0, solution: "1. Kecepatan awal vertikal nol, jadi $h = \\frac{1}{2}gt^2$: $80 = 5t^2$. 2. $t^2 = 16 \\Rightarrow t = 4\\ \\text{s}$. 3. Kesalahan umum: memakai $h = gt^2$ (lupa faktor $\\frac{1}{2}$) atau mengira kecepatan horizontal $15\\ \\text{m/s}$ mempercepat jatuhnya." },
    { q: "Sebuah bola ditembakkan dengan kecepatan awal $40\\ \\text{m/s}$ membentuk sudut $60^\\circ$ terhadap horizontal. Besar kecepatan bola tepat di titik tertinggi lintasannya adalah ...", options: ["$0\\ \\text{m/s}$", "$40\\ \\text{m/s}$", "$20\\sqrt{3}\\ \\text{m/s}$", "$20\\ \\text{m/s}$"], answer: 3, solution: "1. Di titik tertinggi komponen vertikal kecepatan nol ($v_y = 0$). 2. Komponen horizontal selalu tetap: $v_x = v_0\\cos60^\\circ = 40\\cdot\\frac{1}{2} = 20\\ \\text{m/s}$. 3. Kesalahan umum: mengira kecepatan total nol di titik tertinggi — yang nol hanya komponen vertikalnya." },
    { q: "Sebuah meriam menembakkan peluru dengan kecepatan awal $50\\ \\text{m/s}$ pada sudut elevasi $30^\\circ$ ($g = 10\\ \\text{m/s}^2$). Waktu yang dihabiskan peluru di udara hingga kembali ke ketinggian semula adalah ...", options: ["$10\\ \\text{s}$", "$2{,}5\\ \\text{s}$", "$5\\ \\text{s}$", "$8\\ \\text{s}$"], answer: 2, solution: "1. $v_{0y} = 50\\sin30^\\circ = 25\\ \\text{m/s}$; waktu naik $t_{naik} = v_{0y}/g = 2{,}5\\ \\text{s}$. 2. Waktu total $= 2\\times2{,}5 = 5\\ \\text{s}$. 3. Kesalahan umum: lupa menggandakan — $2{,}5\\ \\text{s}$ baru waktu naiknya saja." },
    { q: "Dua proyektil ditembakkan dengan kecepatan awal yang sama, yang satu bersudut $30^\\circ$ dan yang lain $60^\\circ$ terhadap horizontal. Perbandingan jarak mendatar keduanya adalah ...", options: ["$1 : 2$", "$1 : 1$", "$2 : 1$", "$1 : 3$"], answer: 1, solution: "1. $R = \\frac{v_0^2\\sin2\\theta}{g}$; $\\sin(2\\cdot30^\\circ) = \\sin60^\\circ$ dan $\\sin(2\\cdot60^\\circ) = \\sin120^\\circ = \\sin60^\\circ$. 2. Kedua sudut menghasilkan $R$ yang sama, jadi perbandingannya $1 : 1$. 3. Miskonsepsi umum: sudut lebih besar selalu lebih jauh — sebenarnya $R$ maksimum pada $45^\\circ$ dan simetris terhadap sudut itu." },
    { q: "Sebuah bola ditendang dengan kecepatan awal $30\\ \\text{m/s}$. Agar mencapai jarak mendatar sejauh mungkin ($g = 10\\ \\text{m/s}^2$), sudut elevasi dan jarak maksimumnya adalah ...", options: ["$45^\\circ$ dan $90\\ \\text{m}$", "$45^\\circ$ dan $45\\ \\text{m}$", "$30^\\circ$ dan $180\\ \\text{m}$", "$60^\\circ$ dan $60\\ \\text{m}$"], answer: 0, solution: "1. Jarak mendatar $R = \\frac{v_0^2\\sin2\\theta}{g}$ maksimum saat $\\sin2\\theta = 1$, yaitu $\\theta = 45^\\circ$. 2. $R_{maks} = \\frac{30^2}{10} = \\frac{900}{10} = 90\\ \\text{m}$. 3. Kesalahan umum: memakai $\\sin\\theta$ bukan $\\sin2\\theta$ sehingga mendapat setengahnya ($45\\ \\text{m}$)." },
    { q: "Sebuah bandul diputar horizontal membentuk lingkaran berjari-jari $0{,}5\\ \\text{m}$ dengan frekuensi $2\\ \\text{Hz}$. Kelajuan linear bandul tersebut adalah ...", options: ["$\\pi\\ \\text{m/s}$", "$4\\pi\\ \\text{m/s}$", "$8\\pi\\ \\text{m/s}$", "$2\\pi\\ \\text{m/s}$"], answer: 3, solution: "1. $v = \\omega r = 2\\pi f\\cdot r$. 2. $v = 2\\pi\\cdot2\\cdot0{,}5 = 2\\pi\\ \\text{m/s}$. 3. Kesalahan umum: memakai diameter bukan jari-jari, atau lupa faktor $2\\pi$ dari $\\omega = 2\\pi f$." },
    { q: "Sebuah piringan hitam berputar dengan periode $0{,}25\\ \\text{s}$. Frekuensi putaran piringan tersebut adalah ...", options: ["$0{,}25\\ \\text{Hz}$", "$2\\ \\text{Hz}$", "$4\\ \\text{Hz}$", "$8\\ \\text{Hz}$"], answer: 2, solution: "1. Frekuensi adalah kebalikan periode: $f = \\frac{1}{T}$. 2. $f = \\frac{1}{0{,}25} = 4\\ \\text{Hz}$. 3. Kesalahan umum: menjawab $0{,}25\\ \\text{Hz}$ — itu periodenya, frekuensi adalah kebalikannya." },
    { q: "Sebuah kipas berputar dengan kecepatan sudut $4\\pi\\ \\text{rad/s}$. Frekuensi putaran kipas tersebut adalah ...", options: ["$4\\pi\\ \\text{Hz}$", "$2\\ \\text{Hz}$", "$8\\pi\\ \\text{Hz}$", "$0{,}5\\ \\text{Hz}$"], answer: 1, solution: "1. Hubungan kecepatan sudut dan frekuensi: $\\omega = 2\\pi f$. 2. $f = \\frac{\\omega}{2\\pi} = \\frac{4\\pi}{2\\pi} = 2\\ \\text{Hz}$. 3. Kesalahan umum: menjawab $4\\pi\\ \\text{Hz}$ — itu frekuensi sudut $\\omega$, bukan frekuensi $f$; keduanya berbeda faktor $2\\pi$." },
    { q: "Sebuah benda bergerak melingkar beraturan dengan kelajuan $6\\ \\text{m/s}$ pada lintasan berjari-jari $3\\ \\text{m}$. Percepatan sentripetal benda adalah ...", options: ["$12\\ \\text{m/s}^2$", "$6\\ \\text{m/s}^2$", "$36\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$"], answer: 0, solution: "1. $a_s = \\frac{v^2}{r}$, arahnya selalu menuju pusat lingkaran. 2. $a_s = \\frac{6^2}{3} = \\frac{36}{3} = 12\\ \\text{m/s}^2$. 3. Kesalahan umum: lupa mengkuadratkan $v$ sehingga mendapat $6/3 = 2\\ \\text{m/s}^2$." },
    { q: "Sebuah titik pada roda berputar dengan kecepatan sudut $2\\ \\text{rad/s}$ dan berjarak $2{,}5\\ \\text{m}$ dari pusat roda. Percepatan sentripetal titik tersebut adalah ...", options: ["$5\\ \\text{m/s}^2$", "$20\\ \\text{m/s}^2$", "$4\\ \\text{m/s}^2$", "$10\\ \\text{m/s}^2$"], answer: 3, solution: "1. $a_s = \\omega^2 r$. 2. $a_s = 2^2\\cdot2{,}5 = 4\\cdot2{,}5 = 10\\ \\text{m/s}^2$. 3. Kesalahan umum: memakai $a_s = \\omega r = 5\\ \\text{m/s}^2$ — $\\omega$ harus dikuadratkan." },
    { q: "Sebuah tikungan jalan miring dirancang agar mobil $10\\ \\text{m/s}$ dapat menikung tanpa mengandalkan gesekan pada jari-jari $20\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Nilai $\\tan\\theta$ dari kemiringan jalan tersebut adalah ...", options: ["$2$", "$1$", "$0{,}5$", "$0{,}25$"], answer: 2, solution: "1. Pada tikungan miring tanpa gesekan: $\\tan\\theta = \\frac{v^2}{rg}$. 2. $\\tan\\theta = \\frac{10^2}{20\\cdot10} = \\frac{100}{200} = 0{,}5$. 3. Miskonsepsi umum: mengira kemiringan bergantung pada massa mobil — massa saling meniadakan dalam penurunan rumus." },
    { q: "Roda sepeda berjari-jari $0{,}4\\ \\text{m}$ berputar $5\\ \\text{putaran}$ tiap sekon. Kelajuan titik di tepi roda adalah ...", options: ["$2\\pi\\ \\text{m/s}$", "$4\\pi\\ \\text{m/s}$", "$8\\pi\\ \\text{m/s}$", "$10\\pi\\ \\text{m/s}$"], answer: 1, solution: "1. $v = 2\\pi r f$ dengan $f = 5\\ \\text{Hz}$. 2. $v = 2\\pi\\cdot0{,}4\\cdot5 = 4\\pi\\ \\text{m/s}$. 3. Kesalahan umum: mengalikan $r$ dengan $f$ saja tanpa $2\\pi$ — putaran per sekon harus diubah ke radian per sekon." },
    { q: "Sebuah mobil $800\\ \\text{kg}$ menikung dengan jari-jari $25\\ \\text{m}$ pada kelajuan $10\\ \\text{m/s}$. Gaya sentripetal yang bekerja pada mobil adalah ...", options: ["$3200\\ \\text{N}$", "$8000\\ \\text{N}$", "$320\\ \\text{N}$", "$32000\\ \\text{N}$"], answer: 0, solution: "1. $F_s = m\\frac{v^2}{r}$, arahnya menuju pusat tikungan. 2. $F_s = 800\\cdot\\frac{10^2}{25} = 800\\cdot4 = 3200\\ \\text{N}$. 3. Kesalahan umum: lupa mengkuadratkan kecepatan sehingga mendapat $800\\cdot10/25 = 320\\ \\text{N}$." },
    { q: "Seseorang bermassa $60\\ \\text{kg}$ berdiri di atas timbangan dalam lift yang dipercepat ke atas $2\\ \\text{m/s}^2$ ($g = 10\\ \\text{m/s}^2$). Angka yang ditunjukkan timbangan adalah ...", options: ["$600\\ \\text{N}$", "$480\\ \\text{N}$", "$120\\ \\text{N}$", "$720\\ \\text{N}$"], answer: 3, solution: "1. $N - mg = ma$ karena lift dipercepat ke atas. 2. $N = m(g + a) = 60\\cdot(10 + 2) = 720\\ \\text{N}$. 3. Miskonsepsi umum: berat badan selalu $mg = 600\\ \\text{N}$ — timbangan mengukur gaya normal, yang berubah saat ada percepatan." },
    { q: "Seseorang bermassa $60\\ \\text{kg}$ berdiri di atas timbangan dalam lift yang dipercepat ke bawah $2\\ \\text{m/s}^2$ ($g = 10\\ \\text{m/s}^2$). Angka yang ditunjukkan timbangan adalah ...", options: ["$600\\ \\text{N}$", "$720\\ \\text{N}$", "$480\\ \\text{N}$", "$240\\ \\text{N}$"], answer: 2, solution: "1. $mg - N = ma$ karena lift dipercepat ke bawah. 2. $N = m(g - a) = 60\\cdot(10 - 2) = 480\\ \\text{N}$. 3. Kesalahan umum: memakai $N = m(g+a) = 720\\ \\text{N}$ — tanda percepatan mengikuti arah gerak lift." },
    { q: "Sebuah buku diam di atas meja. Pasangan gaya aksi-reaksi dari gaya berat buku (gaya gravitasi Bumi pada buku) adalah ...", options: ["gaya normal yang dikerjakan meja pada buku", "gaya gravitasi yang dikerjakan buku pada Bumi", "gaya gesek antara buku dan meja", "tidak ada pasangannya karena buku diam"], answer: 1, solution: "1. Pasangan aksi-reaksi selalu bekerja pada dua benda berbeda dan merupakan gaya sejenis. 2. Pasangan dari gaya gravitasi Bumi pada buku adalah gaya gravitasi buku pada Bumi (buku menarik Bumi ke atas). 3. Miskonsepsi umum: mengira gaya normal adalah reaksinya — normal dan berat bekerja pada benda yang sama (buku), jadi bukan pasangan aksi-reaksi." },
    { q: "Sebuah mobil yang melaju direm mendadak dan penumpangnya terdorong ke depan. Peristiwa ini terjadi karena ...", options: ["kelembaman tubuhnya sesuai Hukum I Newton", "dorongan mesin mobil yang tiba-tiba mati", "gaya aksi-reaksi dari sabuk pengaman", "gaya gesek antara ban dan jalan"], answer: 0, solution: "1. Saat direm, tidak ada gaya horizontal yang menarik tubuh penumpang ke depan. 2. Menurut Hukum I Newton (kelembaman), tubuh cenderung mempertahankan kecepatan semula sehingga tampak terdorong ke depan relatif terhadap mobil. 3. Miskonsepsi umum: mengira ada gaya dorong misterius ke depan — yang terjadi justru tidak adanya gaya yang menahan tubuh." },
    { q: "Benda bermassa $2\\ \\text{kg}$ dikenai dua gaya yang saling tegak lurus, $6\\ \\text{N}$ dan $8\\ \\text{N}$. Percepatan benda tersebut adalah ...", options: ["$7\\ \\text{m/s}^2$", "$14\\ \\text{m/s}^2$", "$2{,}5\\ \\text{m/s}^2$", "$5\\ \\text{m/s}^2$"], answer: 3, solution: "1. Resultan dua gaya tegak lurus: $F = \\sqrt{6^2 + 8^2} = \\sqrt{100} = 10\\ \\text{N}$. 2. $a = F/m = 10/2 = 5\\ \\text{m/s}^2$. 3. Kesalahan umum: menjumlahkan langsung $6 + 8 = 14\\ \\text{N}$ — gaya adalah vektor, resultannya memakai dalil Pythagoras." },
    { q: "Resultan gaya yang bekerja pada sebuah benda yang sedang bergerak adalah nol. Maka benda tersebut akan ...", options: ["berhenti seketika", "diperlambat sampai berhenti", "bergerak lurus beraturan dengan kecepatan tetap", "berbalik arah geraknya"], answer: 2, solution: "1. $\\Sigma F = 0$ berarti tidak ada perubahan kecepatan (Hukum I Newton). 2. Benda yang sedang bergerak akan terus bergerak lurus beraturan dengan kecepatan tetap. 3. Miskonsepsi umum: benda butuh gaya terus-menerus agar tetap bergerak — gaya dibutuhkan untuk mengubah kecepatan, bukan mempertahankannya." },
    { q: "Seekor kuda menarik gerobak ke depan, dan gerobak menarik kuda ke belakang dengan gaya yang sama besar. Gerobak tetap dapat bergerak maju karena ...", options: ["gaya yang dikerjakan kuda lebih besar dari gaya yang dikerjakan gerobak", "kedua gaya tarik-menarik itu bekerja pada benda yang berbeda", "gaya gesek menghilangkan gaya reaksi gerobak", "Hukum III Newton tidak berlaku untuk benda yang bergerak"], answer: 1, solution: "1. Gaya kuda pada gerobak dan gaya gerobak pada kuda memang sama besar dan berlawanan arah (Hukum III Newton). 2. Namun keduanya bekerja pada benda yang berbeda sehingga tidak saling meniadakan. 3. Gerobak bergerak karena gaya kuda padanya (dikurangi gesekan) tidak nol — pasangan reaksinya bekerja pada kuda, bukan pada gerobak." },
    { q: "Sebuah benda bermassa $3\\ \\text{kg}$ mengalami percepatan $4\\ \\text{m/s}^2$. Resultan gaya yang bekerja pada benda adalah ...", options: ["$12\\ \\text{N}$", "$7\\ \\text{N}$", "$0{,}75\\ \\text{N}$", "$1{,}33\\ \\text{N}$"], answer: 0, solution: "1. Hukum II Newton: $\\Sigma F = m\\cdot a$. 2. $\\Sigma F = 3\\cdot4 = 12\\ \\text{N}$ searah percepatan. 3. Kesalahan umum: menjumlahkan $3 + 4 = 7$ — massa dan percepatan dikalikan, bukan dijumlahkan." },
    { q: "Sebuah peti $10\\ \\text{kg}$ di atas lantai kasar dengan koefisien gesek statis $\\mu_s = 0{,}4$ ($g = 10\\ \\text{m/s}^2$). Gaya gesek statis maksimum antara peti dan lantai adalah ...", options: ["$100\\ \\text{N}$", "$4\\ \\text{N}$", "$400\\ \\text{N}$", "$40\\ \\text{N}$"], answer: 3, solution: "1. $f_{s,\\text{maks}} = \\mu_s N = \\mu_s mg$. 2. $f_{s,\\text{maks}} = 0{,}4\\cdot10\\cdot10 = 40\\ \\text{N}$. 3. Kesalahan umum: memakai massa langsung ($10\\ \\text{N}$) — gaya gesek sebanding dengan gaya normal, bukan massa saja." },
    { q: "Peti $10\\ \\text{kg}$ pada soal sebelumnya ($f_{s,\\text{maks}} = 40\\ \\text{N}$) didorong horizontal dengan gaya $30\\ \\text{N}$. Besar gaya gesek yang bekerja pada peti adalah ...", options: ["$40\\ \\text{N}$", "$0\\ \\text{N}$", "$30\\ \\text{N}$", "$10\\ \\text{N}$"], answer: 2, solution: "1. Karena $30\\ \\text{N} < f_{s,\\text{maks}} = 40\\ \\text{N}$, peti tetap diam. 2. Pada benda diam, gesekan statis menyesuaikan gaya pendorong: $f_s = 30\\ \\text{N}$. 3. Miskonsepsi umum: gesekan statis selalu $= \\mu_s N = 40\\ \\text{N}$ — nilai itu batas maksimumnya, bukan nilai yang selalu bekerja." },
    { q: "Balok $10\\ \\text{kg}$ di atas lantai kasar ditarik dengan gaya horizontal $50\\ \\text{N}$. Jika koefisien gesek kinetik $\\mu_k = 0{,}3$ ($g = 10\\ \\text{m/s}^2$), percepatan balok adalah ...", options: ["$5\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$", "$8\\ \\text{m/s}^2$", "$3\\ \\text{m/s}^2$"], answer: 1, solution: "1. $f_k = \\mu_k N = 0{,}3\\cdot100 = 30\\ \\text{N}$ melawan arah gerak. 2. $a = \\frac{50 - 30}{10} = 2\\ \\text{m/s}^2$. 3. Kesalahan umum: mengabaikan gesekan kinetik sehingga mendapat $50/10 = 5\\ \\text{m/s}^2$." },
    { q: "Balok $5\\ \\text{kg}$ diam pada bidang miring $37^\\circ$ ($\\sin37^\\circ = 0{,}6$; $\\cos37^\\circ = 0{,}8$; $g = 10\\ \\text{m/s}^2$). Besar gaya normal yang dikerjakan bidang pada balok adalah ...", options: ["$40\\ \\text{N}$", "$50\\ \\text{N}$", "$30\\ \\text{N}$", "$25\\ \\text{N}$"], answer: 0, solution: "1. Gaya normal tegak lurus bidang: $N = mg\\cos\\theta$. 2. $N = 5\\cdot10\\cdot\\cos37^\\circ = 50\\cdot0{,}8 = 40\\ \\text{N}$. 3. Kesalahan umum: memakai $mg\\sin\\theta = 30\\ \\text{N}$ — itu komponen berat sejajar bidang, bukan yang tegak lurus." },
    { q: "Sebuah balok meluncur di atas lantai kasar dengan kecepatan awal $12\\ \\text{m/s}$ dan berhenti setelah menempuh $18\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Koefisien gesek kinetik antara balok dan lantai adalah ...", options: ["$0{,}8$", "$0{,}2$", "$0{,}1$", "$0{,}4$"], answer: 3, solution: "1. $v^2 = v_0^2 - 2\\mu_k g s$: $0 = 12^2 - 2\\cdot\\mu_k\\cdot10\\cdot18$. 2. $360\\mu_k = 144 \\Rightarrow \\mu_k = 0{,}4$. 3. Kesalahan umum: lupa faktor $2$ pada rumus sehingga mendapat $0{,}8$ — dua kali nilai yang benar." },
    { q: "Sebuah mobil $20\\ \\text{m/s}$ direm hingga berhenti. Jika koefisien gesek kinetik antara ban dan jalan $\\mu_k = 0{,}5$ ($g = 10\\ \\text{m/s}^2$), jarak pengereman mobil adalah ...", options: ["$20\\ \\text{m}$", "$80\\ \\text{m}$", "$40\\ \\text{m}$", "$10\\ \\text{m}$"], answer: 2, solution: "1. Perlambatan oleh gesekan: $a = \\mu_k g = 0{,}5\\cdot10 = 5\\ \\text{m/s}^2$. 2. $s = \\frac{v_0^2}{2a} = \\frac{400}{10} = 40\\ \\text{m}$. 3. Miskonsepsi umum: mobil lebih berat butuh jarak lebih jauh — massa saling meniadakan, jarak pengereman oleh gesekan tidak bergantung pada massa." },
    { q: "Balok $10\\ \\text{kg}$ ditarik dengan gaya $50\\ \\text{N}$ yang membentuk sudut $37^\\circ$ terhadap horizontal ($\\sin37^\\circ = 0{,}6$; $g = 10\\ \\text{m/s}^2$). Besar gaya normal yang dikerjakan lantai pada balok adalah ...", options: ["$100\\ \\text{N}$", "$70\\ \\text{N}$", "$130\\ \\text{N}$", "$30\\ \\text{N}$"], answer: 1, solution: "1. Komponen vertikal gaya menarik ke atas: $F_y = 50\\sin37^\\circ = 50\\cdot0{,}6 = 30\\ \\text{N}$. 2. $N + F_y = mg \\Rightarrow N = 100 - 30 = 70\\ \\text{N}$. 3. Kesalahan umum: tetap memakai $N = mg = 100\\ \\text{N}$ — tarikan miring ke atas mengurangi beban yang menekan lantai." },
    { q: "Sebuah balok tepat akan meluncur saat bidang miring dimiringkan hingga sudut $37^\\circ$. Koefisien gesek statis antara balok dan bidang adalah ...", options: ["$0{,}75$", "$0{,}6$", "$0{,}8$", "$1{,}33$"], answer: 0, solution: "1. Tepat akan meluncur berarti $mg\\sin\\theta = \\mu_s mg\\cos\\theta$. 2. $\\mu_s = \\tan\\theta = \\tan37^\\circ = \\frac{0{,}6}{0{,}8} = 0{,}75$. 3. Kesalahan umum: memakai $\\sin37^\\circ = 0{,}6$ — ingat $\\mu_s = \\tan\\theta$, bukan $\\sin\\theta$." },
    { q: "Sebuah balok meluncur tanpa gesekan pada bidang miring $30^\\circ$ ($g = 10\\ \\text{m/s}^2$). Percepatan balok adalah ...", options: ["$10\\ \\text{m/s}^2$", "$8{,}7\\ \\text{m/s}^2$", "$2{,}5\\ \\text{m/s}^2$", "$5\\ \\text{m/s}^2$"], answer: 3, solution: "1. Komponen berat sejajar bidang: $F = mg\\sin\\theta$. 2. $a = \\frac{F}{m} = g\\sin30^\\circ = 10\\cdot0{,}5 = 5\\ \\text{m/s}^2$. 3. Miskonsepsi umum: percepatan bergantung pada massa — massa saling meniadakan, semua benda meluncur dengan percepatan yang sama." },
    { q: "Balok meluncur dari keadaan diam pada bidang miring licin sepanjang $10\\ \\text{m}$ dengan sudut kemiringan $30^\\circ$ ($g = 10\\ \\text{m/s}^2$). Kecepatan balok saat mencapai dasar bidang adalah ...", options: ["$20\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$10\\sqrt{2}\\ \\text{m/s}$"], answer: 2, solution: "1. $a = g\\sin30^\\circ = 5\\ \\text{m/s}^2$; $v^2 = v_0^2 + 2as = 0 + 2\\cdot5\\cdot10 = 100$. 2. $v = 10\\ \\text{m/s}$. 3. Kesalahan umum: memakai $v = \\sqrt{2gh}$ dengan $h = 10\\ \\text{m}$ — $10\\ \\text{m}$ adalah panjang bidang, bukan ketinggian vertikalnya." },
    { q: "Dua benda bermassa $3\\ \\text{kg}$ dan $2\\ \\text{kg}$ dihubungkan dengan tali ringan melalui katrol licin (mesin Atwood). Percepatan sistem adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$10\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$", "$3{,}3\\ \\text{m/s}^2$", "$6\\ \\text{m/s}^2$"], answer: 1, solution: "1. $a = \\frac{m_1 - m_2}{m_1 + m_2}g$. 2. $a = \\frac{3-2}{3+2}\\cdot10 = \\frac{1}{5}\\cdot10 = 2\\ \\text{m/s}^2$. 3. Kesalahan umum: memakai $a = g = 10\\ \\text{m/s}^2$ — massa yang lebih ringan menahan jatuhnya massa yang berat." },
    { q: "Pada sistem katrol soal sebelumnya ($3\\ \\text{kg}$ dan $2\\ \\text{kg}$; $a = 2\\ \\text{m/s}^2$), besar tegangan tali adalah ...", options: ["$24\\ \\text{N}$", "$30\\ \\text{N}$", "$20\\ \\text{N}$", "$12\\ \\text{N}$"], answer: 0, solution: "1. Tinjau massa $2\\ \\text{kg}$ yang bergerak naik: $T - m_2 g = m_2 a$. 2. $T = 2\\cdot(10 + 2) = 24\\ \\text{N}$. 3. Kesalahan umum: mengira $T = m_1 g = 30\\ \\text{N}$ — tegangan lebih kecil dari berat massa yang turun karena sistem dipercepat." },
    { q: "Balok $4\\ \\text{kg}$ di atas meja horizontal licin dihubungkan dengan tali melalui katrol ke beban $1\\ \\text{kg}$ yang menggantung. Percepatan sistem adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$10\\ \\text{m/s}^2$", "$2{,}5\\ \\text{m/s}^2$", "$5\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$"], answer: 3, solution: "1. Gaya penggerak hanya berat beban: $F = 1\\cdot10 = 10\\ \\text{N}$; massa total yang dipercepat $4 + 1 = 5\\ \\text{kg}$. 2. $a = \\frac{10}{5} = 2\\ \\text{m/s}^2$. 3. Kesalahan umum: membagi dengan massa balok saja ($10/4 = 2{,}5$) — yang dipercepat adalah kedua benda sekaligus." },
    { q: "Pada sistem soal sebelumnya (balok $4\\ \\text{kg}$ dan beban $1\\ \\text{kg}$; $a = 2\\ \\text{m/s}^2$), besar tegangan tali adalah ...", options: ["$10\\ \\text{N}$", "$40\\ \\text{N}$", "$8\\ \\text{N}$", "$2\\ \\text{N}$"], answer: 2, solution: "1. Tinjau balok $4\\ \\text{kg}$ di meja licin: satu-satunya gaya horizontal adalah $T$, jadi $T = m_1 a$. 2. $T = 4\\cdot2 = 8\\ \\text{N}$. 3. Kesalahan umum: mengira $T = m_2 g = 10\\ \\text{N}$ — beban $1\\ \\text{kg}$ dipercepat ke bawah sehingga tegangannya kurang dari beratnya." },
    { q: "Balok $2\\ \\text{kg}$ meluncur pada bidang miring kasar $37^\\circ$ dengan $\\mu_k = 0{,}25$ ($\\sin37^\\circ = 0{,}6$; $\\cos37^\\circ = 0{,}8$; $g = 10\\ \\text{m/s}^2$). Percepatan balok adalah ...", options: ["$6\\ \\text{m/s}^2$", "$4\\ \\text{m/s}^2$", "$8\\ \\text{m/s}^2$", "$2\\ \\text{m/s}^2$"], answer: 1, solution: "1. $a = g(\\sin\\theta - \\mu_k\\cos\\theta) = 10\\cdot(0{,}6 - 0{,}25\\cdot0{,}8)$. 2. $= 10\\cdot(0{,}6 - 0{,}2) = 4\\ \\text{m/s}^2$. 3. Kesalahan umum: memakai $a = g\\sin\\theta = 6\\ \\text{m/s}^2$ karena mengabaikan gesekan, atau salah tanda menjadi $g(\\sin\\theta + \\mu_k\\cos\\theta)$." },
    { q: "Dua benda masing-masing bermassa $5\\ \\text{kg}$ digantung pada kedua ujung tali yang melalui katrol licin. Besar tegangan tali adalah ... ($g = 10\\ \\text{m/s}^2$)", options: ["$50\\ \\text{N}$", "$100\\ \\text{N}$", "$0\\ \\text{N}$", "$25\\ \\text{N}$"], answer: 0, solution: "1. Kedua massa sama sehingga sistem setimbang ($a = 0$). 2. Tegangan menahan tepat satu beban: $T = mg = 5\\cdot10 = 50\\ \\text{N}$. 3. Miskonsepsi umum: kedua beban saling menarik sehingga $T = 100\\ \\text{N}$ — tegangan tali dihitung dari satu sisi saja, bukan dijumlahkan." },
{ q: "Sebuah gaya horizontal $20\\ \\text{N}$ mendorong balok sejauh $10\\ \\text{m}$ pada lantai licin searah gaya. Usaha yang dilakukan gaya tersebut adalah ...", options: ["$200\\ \\text{J}$", "$100\\ \\text{J}$", "$400\\ \\text{J}$", "$0$"], answer: 0, solution: "1. Untuk gaya searah perpindahan berlaku $W = F\\cdot s = 20\\cdot10 = 200\\ \\text{J}$. 2. Tanda positif karena gaya searah gerak, artinya gaya membantu gerakan benda. 3. Kesalahan umum: menjawab $0$ dengan alasan tidak ada sudut; sudut $0^\\circ$ justru memberi $\\cos 0^\\circ = 1$, usaha nol hanya terjadi jika gaya tegak lurus perpindahan." },
  { q: "Seorang anak menarik gerobak dengan tali yang membentuk sudut $37^\\circ$ terhadap arah perpindahan horizontal sejauh $10\\ \\text{m}$. Jika gaya tarik tali $40\\ \\text{N}$ dan $\\cos 37^\\circ = 0{,}8$, usaha yang dilakukan gaya tarik tersebut adalah ...", options: ["$400\\ \\text{J}$", "$320\\ \\text{J}$", "$240\\ \\text{J}$", "$160\\ \\text{J}$"], answer: 1, solution: "1. Usaha oleh gaya yang membentuk sudut: $W = F\\cdot s\\cdot\\cos\\theta = 40\\cdot10\\cdot0{,}8$. 2. $W = 400\\cdot0{,}8 = 320\\ \\text{J}$. 3. Kesalahan umum: lupa mengalikan $\\cos\\theta$ sehingga menjawab $400\\ \\text{J}$, atau tertukar memakai $\\sin 37^\\circ = 0{,}6$ ($240\\ \\text{J}$); yang benar, hanya komponen gaya searah perpindahan ($F\\cos\\theta$) yang melakukan usaha." },
  { q: "Balok digeser $5\\ \\text{m}$ ke kanan, sedangkan pada balok bekerja gaya $30\\ \\text{N}$ yang arahnya vertikal ke atas. Usaha yang dilakukan gaya $30\\ \\text{N}$ tersebut adalah ...", options: ["$150\\ \\text{J}$", "$30\\ \\text{J}$", "$0$", "$5\\ \\text{J}$"], answer: 2, solution: "1. Gaya tegak lurus arah perpindahan berarti sudutnya $\\theta = 90^\\circ$. 2. $W = F\\cdot s\\cdot\\cos 90^\\circ = 30\\cdot5\\cdot0 = 0$. 3. Kesalahan umum: tetap mengalikan $F\\cdot s = 150\\ \\text{J}$; gaya yang tegak lurus gerak tidak melakukan usaha, seperti gaya normal pada benda yang meluncur di lantai datar." },
  { q: "Gaya gesek $8\\ \\text{N}$ bekerja berlawanan arah dengan perpindahan balok sejauh $12\\ \\text{m}$. Usaha yang dilakukan gaya gesek tersebut adalah ...", options: ["$96\\ \\text{J}$", "$-48\\ \\text{J}$", "$-12\\ \\text{J}$", "$-96\\ \\text{J}$"], answer: 3, solution: "1. Sudut antara gaya gesek dan perpindahan $\\theta = 180^\\circ$, sehingga $\\cos 180^\\circ = -1$. 2. $W = F\\cdot s\\cdot\\cos 180^\\circ = 8\\cdot12\\cdot(-1) = -96\\ \\text{J}$. 3. Tanda negatif berarti gaya mengambil energi dari benda (mengurangi energi kinetiknya); kesalahan umum adalah memberi tanda positif karena kata 'usaha' terdengar selalu positif." },
  { q: "Dua gaya searah, $12\\ \\text{N}$ dan $8\\ \\text{N}$, bekerja pada sebuah benda yang berpindah $5\\ \\text{m}$ searah kedua gaya. Usaha total yang dilakukan kedua gaya tersebut adalah ...", options: ["$60\\ \\text{J}$", "$40\\ \\text{J}$", "$100\\ \\text{J}$", "$200\\ \\text{J}$"], answer: 2, solution: "1. Usaha total sama dengan usaha oleh gaya resultan: $F_{total} = 12 + 8 = 20\\ \\text{N}$. 2. $W_{total} = 20\\cdot5 = 100\\ \\text{J}$ (sama dengan $12\\cdot5 + 8\\cdot5$). 3. Kesalahan umum: hanya menghitung usaha salah satu gaya ($60\\ \\text{J}$ atau $40\\ \\text{J}$); setiap gaya yang searah gerak ikut menyumbang usaha." },
  { q: "Sebuah ember berisi air bermassa total $3\\ \\text{kg}$ diangkat vertikal setinggi $4\\ \\text{m}$ dengan kecepatan konstan ($g = 10\\ \\text{m/s}^2$). Usaha yang dilakukan gaya angkat tersebut adalah ...", options: ["$120\\ \\text{J}$", "$12\\ \\text{J}$", "$30\\ \\text{J}$", "$0$"], answer: 0, solution: "1. Kecepatan konstan berarti gaya angkat mengimbangi berat: $F = mg = 3\\cdot10 = 30\\ \\text{N}$ ke atas. 2. $W = F\\cdot h = 30\\cdot4 = 120\\ \\text{J}$. 3. Kesalahan umum: menjawab $0$ karena 'kecepatannya konstan'; usaha tetap ada karena gaya bekerja sepanjang perpindahan, yang nol hanyalah perubahan energi kinetiknya." },
  { q: "Sebuah mobil bermassa $800\\ \\text{kg}$ bergerak dengan kelajuan $15\\ \\text{m/s}$. Energi kinetik mobil tersebut adalah ...", options: ["$45\\ \\text{kJ}$", "$90\\ \\text{kJ}$", "$180\\ \\text{kJ}$", "$6\\ \\text{kJ}$"], answer: 1, solution: "1. $E_k = \\frac{1}{2}mv^2 = \\frac{1}{2}\\cdot800\\cdot15^2$. 2. $E_k = 400\\cdot225 = 90.000\\ \\text{J} = 90\\ \\text{kJ}$. 3. Kesalahan umum: lupa menguadratkan kelajuan ($\\frac{1}{2}\\cdot800\\cdot15 = 6\\ \\text{kJ}$) atau lupa faktor $\\frac{1}{2}$ ($180\\ \\text{kJ}$)." },
  { q: "Kelajuan sebuah benda dijadikan dua kali lipat dari semula, massanya tetap. Energi kinetik benda tersebut menjadi ...", options: ["tetap sama", "dua kali lipat", "delapan kali lipat", "empat kali lipat"], answer: 3, solution: "1. $E_k$ sebanding dengan $v^2$: jika $v' = 2v$ maka $E_k' = \\frac{1}{2}m(2v)^2 = 4\\cdot\\frac{1}{2}mv^2$. 2. Jadi energi kinetik menjadi empat kali lipat. 3. Kesalahan umum: mengira hubungannya linear (dua kali lipat); ingat kelajuan dikuadratkan sehingga efeknya kuadratik." },
  { q: "Balok bermassa $5\\ \\text{kg}$ berada di atas meja setinggi $3\\ \\text{m}$ dari lantai ($g = 10\\ \\text{m/s}^2$). Energi potensial gravitasi balok relatif terhadap lantai adalah ...", options: ["$150\\ \\text{J}$", "$15\\ \\text{J}$", "$50\\ \\text{J}$", "$75\\ \\text{J}$"], answer: 0, solution: "1. $E_p = m\\cdot g\\cdot h = 5\\cdot10\\cdot3$. 2. $E_p = 150\\ \\text{J}$. 3. Kesalahan umum: memakai $mg = 50\\ \\text{J}$ (lupa dikali ketinggian); energi potensial membutuhkan ketiga faktor sekaligus: massa, gravitasi, dan ketinggian." },
  { q: "Energi potensial sebuah pegas yang diregangkan $0{,}1\\ \\text{m}$ adalah $4\\ \\text{J}$. Jika regangan pegas digandakan menjadi $0{,}2\\ \\text{m}$, energi potensial yang tersimpan menjadi ...", options: ["$8\\ \\text{J}$", "$16\\ \\text{J}$", "$32\\ \\text{J}$", "$4\\ \\text{J}$"], answer: 1, solution: "1. $E_p = \\frac{1}{2}kx^2$ sebanding dengan kuadrat regangan. 2. Regangan menjadi $2$ kali berarti energi menjadi $2^2 = 4$ kali: $4\\cdot4\\ \\text{J} = 16\\ \\text{J}$. 3. Kesalahan umum: mengira hubungannya linear sehingga menjawab $8\\ \\text{J}$; sama seperti energi kinetik, kuadrat membuat efeknya berlipat ganda." },
  { q: "Benda bermassa $2\\ \\text{kg}$ berada $5\\ \\text{m}$ di bawah titik acuan energi potensial nol ($g = 10\\ \\text{m/s}^2$). Energi potensial gravitasi benda tersebut adalah ...", options: ["$100\\ \\text{J}$", "$0$", "$-50\\ \\text{J}$", "$-100\\ \\text{J}$"], answer: 3, solution: "1. Ketinggian relatif terhadap acuan adalah $h = -5\\ \\text{m}$. 2. $E_p = mgh = 2\\cdot10\\cdot(-5) = -100\\ \\text{J}$. 3. Energi potensial boleh bernilai negatif; tandanya hanya menunjukkan posisi relatif terhadap acuan yang kita pilih, bukan 'energi minus' yang aneh. Kesalahan umum adalah memaksa hasilnya selalu positif." },
  { q: "Benda A bermassa $2m$ bergerak dengan kelajuan $v$, sedangkan benda B bermassa $m$ bergerak dengan kelajuan $2v$. Perbandingan energi kinetik kedua benda tersebut adalah ...", options: ["energi kinetik B dua kali energi kinetik A", "keduanya sama besar", "energi kinetik A dua kali energi kinetik B", "energi kinetik A empat kali energi kinetik B"], answer: 0, solution: "1. $E_{kA} = \\frac{1}{2}(2m)v^2 = mv^2$ dan $E_{kB} = \\frac{1}{2}m(2v)^2 = 2mv^2$. 2. Jadi $E_{kB} = 2E_{kA}$. 3. Kelajuan berpengaruh secara kuadrat sedangkan massa linear; menggandakan kelajuan (benda B) lebih berpengaruh daripada menggandakan massa (benda A)." },
  { q: "Benda $1\\ \\text{kg}$ meluncur tanpa gesekan dari puncak bidang miring licin setinggi $4\\ \\text{m}$ ($g = 10\\ \\text{m/s}^2$). Kelajuan benda saat mencapai dasar bidang adalah ...", options: ["$4\\sqrt{5}\\ \\text{m/s}$", "$2\\sqrt{5}\\ \\text{m/s}$", "$8\\ \\text{m/s}$", "$\\sqrt{40}\\ \\text{m/s}$"], answer: 0, solution: "1. Energi mekanik kekal: $mgh = \\frac{1}{2}mv^2$, massa $m$ saling meniadakan di kedua ruas. 2. $v = \\sqrt{2gh} = \\sqrt{2\\cdot10\\cdot4} = \\sqrt{80} = 4\\sqrt{5}\\ \\text{m/s}$. 3. Kesalahan umum: memakai $v = \\sqrt{gh}$ (lupa faktor $2$) sehingga mendapat $2\\sqrt{5}\\ \\text{m/s}$; faktor $2$ berasal dari $\\frac{1}{2}mv^2$." },
  { q: "Bola dilempar vertikal ke atas dengan kelajuan awal $12\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$, abaikan gesekan udara). Ketinggian maksimum yang dicapai bola adalah ...", options: ["$14{,}4\\ \\text{m}$", "$7{,}2\\ \\text{m}$", "$3{,}6\\ \\text{m}$", "$12\\ \\text{m}$"], answer: 1, solution: "1. Di titik tertinggi $E_k = 0$, sehingga seluruh energi kinetik awal menjadi potensial: $\\frac{1}{2}mv_0^2 = mgh$. 2. $h = \\frac{v_0^2}{2g} = \\frac{144}{20} = 7{,}2\\ \\text{m}$. 3. Kesalahan umum: memakai $h = \\frac{v_0^2}{g} = 14{,}4\\ \\text{m}$ (lupa faktor $2$ dari $\\frac{1}{2}mv^2$)." },
  { q: "Sebuah bandul bermassa $0{,}5\\ \\text{kg}$ diayunkan; saat melewati titik terendah kelajuannya $6\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Ketinggian awal bandul ketika dilepaskan, diukur dari titik terendah, adalah ...", options: ["$3{,}6\\ \\text{m}$", "$0{,}9\\ \\text{m}$", "$1{,}8\\ \\text{m}$", "$9\\ \\text{m}$"], answer: 2, solution: "1. Kekekalan energi mekanik: $mgh = \\frac{1}{2}mv^2$, sehingga $h = \\frac{v^2}{2g}$. 2. $h = \\frac{36}{20} = 1{,}8\\ \\text{m}$. 3. Massa bandul tidak memengaruhi hasil karena saling meniadakan di kedua ruas; jangan terkecoh memasukkan $0{,}5\\ \\text{kg}$ ke dalam perhitungan akhir." },
  { q: "Balok $2\\ \\text{kg}$ dijatuhkan dari ketinggian $10\\ \\text{m}$; akibat hambatan udara ia menyentuh tanah dengan kelajuan $12\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Usaha yang dilakukan gaya non-konservatif (hambatan udara) adalah ...", options: ["$56\\ \\text{J}$", "$-200\\ \\text{J}$", "$-144\\ \\text{J}$", "$-56\\ \\text{J}$"], answer: 3, solution: "1. Usaha gaya non-konservatif sama dengan perubahan energi mekanik: $W_{nc} = \\Delta E_M = E_{k,akhir} - E_{p,awal}$. 2. $E_{k,akhir} = \\frac{1}{2}\\cdot2\\cdot12^2 = 144\\ \\text{J}$ dan $E_{p,awal} = 2\\cdot10\\cdot10 = 200\\ \\text{J}$, jadi $W_{nc} = 144 - 200 = -56\\ \\text{J}$. 3. Tanda negatif wajar: hambatan udara mengambil energi mekanik dan mengubahnya menjadi panas; kesalahan umum adalah memberi tanda positif." },
  { q: "Balok $2\\ \\text{kg}$ dijatuhkan tepat dari ujung atas sebuah pegas vertikal yang belum tertekan (konstanta pegas $200\\ \\text{N/m}$, $g = 10\\ \\text{m/s}^2$). Tekanan (kompresi) maksimum pegas tersebut adalah ...", options: ["$0{,}2\\ \\text{m}$", "$0{,}1\\ \\text{m}$", "$0{,}4\\ \\text{m}$", "$0{,}05\\ \\text{m}$"], answer: 0, solution: "1. Energi potensial gravitasi yang hilang seluruhnya menjadi energi pegas: $mgx = \\frac{1}{2}kx^2$. 2. $x = \\frac{2mg}{k} = \\frac{2\\cdot2\\cdot10}{200} = 0{,}2\\ \\text{m}$. 3. Kesalahan umum: menyamakan gaya $mg = kx$ sehingga mendapat $0{,}1\\ \\text{m}$; itu adalah posisi setimbang statis, bukan kompresi maksimum saat balok dijatuhkan." },
  { q: "Benda dijatuhkan tanpa kecepatan awal dari ketinggian $h$. Saat benda berada pada ketinggian $h/2$, perbandingan energi kinetik terhadap energi potensialnya ($E_k : E_p$) adalah ...", options: ["$E_k$ dua kali $E_p$", "sama besar ($1:1$)", "$E_p$ dua kali $E_k$", "$E_k$ sama dengan nol"], answer: 1, solution: "1. Energi mekanik total $E_M = mgh$ kekal selama jatuh. 2. Pada ketinggian $h/2$: $E_p = mg\\cdot\\frac{h}{2} = \\frac{1}{2}E_M$, sisanya $E_k = E_M - \\frac{1}{2}E_M = \\frac{1}{2}E_M$; keduanya sama besar. 3. Intuisi yang keliru: 'sudah jatuh setengah jalan, kecepatannya pasti besar'; padahal energi terbagi rata tepat di tengah ketinggian." },
  { q: "Motor listrik mengangkat beban $100\\ \\text{kg}$ setinggi $6\\ \\text{m}$ dalam waktu $5\\ \\text{s}$ ($g = 10\\ \\text{m/s}^2$). Daya rata-rata motor tersebut adalah ...", options: ["$600\\ \\text{W}$", "$1200\\ \\text{W}$", "$200\\ \\text{W}$", "$12000\\ \\text{W}$"], answer: 1, solution: "1. Usaha yang dilakukan $W = mgh = 100\\cdot10\\cdot6 = 6000\\ \\text{J}$. 2. Daya $P = \\frac{W}{t} = \\frac{6000}{5} = 1200\\ \\text{W}$. 3. Kesalahan umum: berhenti di $6000\\ \\text{J}$ lalu mengira itu daya; daya adalah usaha per satuan waktu dengan satuan watt ($\\text{J/s}$)." },
  { q: "Sebuah gaya $50\\ \\text{N}$ menarik benda sehingga bergerak dengan kecepatan konstan $4\\ \\text{m/s}$ searah gaya. Daya yang diberikan oleh gaya tersebut adalah ...", options: ["$200\\ \\text{W}$", "$12{,}5\\ \\text{W}$", "$800\\ \\text{W}$", "$50\\ \\text{W}$"], answer: 0, solution: "1. Daya sesaat untuk gaya searah kecepatan: $P = F\\cdot v$. 2. $P = 50\\cdot4 = 200\\ \\text{W}$. 3. Kesalahan umum: membagi $F/v = 12{,}5\\ \\text{W}$; periksa dimensinya, $\\text{N}\\cdot\\text{m/s} = \\text{J/s} = \\text{W}$ adalah dimensi daya yang benar." },
  { q: "Dua mesin melakukan usaha yang sama besar. Mesin A menyelesaikannya dalam waktu setengah dari waktu yang dibutuhkan mesin B. Daya mesin A dibandingkan dengan daya mesin B adalah ...", options: ["setengahnya", "sama besar", "empat kali lipat", "dua kali lipat"], answer: 3, solution: "1. $P = \\frac{W}{t}$ dengan usaha $W$ yang sama dan $t_A = \\frac{1}{2}t_B$. 2. $P_A = \\frac{W}{t_A} = \\frac{W}{t_B/2} = 2\\frac{W}{t_B} = 2P_B$. 3. Daya mengukur kecepatan melakukan usaha, bukan besar usahanya; usaha yang sama belum tentu dayanya sama." },
  { q: "Sebuah pompa melakukan usaha $3600\\ \\text{J}$ dalam waktu $2\\ \\text{menit}$. Daya rata-rata pompa tersebut adalah ...", options: ["$1800\\ \\text{W}$", "$7200\\ \\text{W}$", "$60\\ \\text{W}$", "$30\\ \\text{W}$"], answer: 3, solution: "1. Samakan satuan waktu ke sekon: $2\\ \\text{menit} = 120\\ \\text{s}$. 2. $P = \\frac{W}{t} = \\frac{3600}{120} = 30\\ \\text{W}$. 3. Kesalahan klasik: lupa mengonversi menit ke sekon sehingga menjawab $3600/2 = 1800\\ \\text{W}$; selalu samakan dulu satuannya." },
  { q: "Gaya konstan $20\\ \\text{N}$ bekerja selama $0{,}5\\ \\text{s}$ pada balok $2\\ \\text{kg}$ yang mula-mula diam di lantai licin. Kelajuan akhir balok tersebut adalah ...", options: ["$5\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$2{,}5\\ \\text{m/s}$", "$20\\ \\text{m/s}$"], answer: 0, solution: "1. Impuls $I = F\\cdot\\Delta t = 20\\cdot0{,}5 = 10\\ \\text{N}\\cdot\\text{s}$, dan $I = \\Delta p$. 2. $\\Delta p = m\\cdot v_{akhir}$ sehingga $v = \\frac{10}{2} = 5\\ \\text{m/s}$. 3. Kesalahan umum: mengira impuls $10$ langsung sama dengan kecepatan; impuls adalah perubahan momentum ($\\text{kg}\\cdot\\text{m/s}$) yang masih harus dibagi massa." },
  { q: "Bola $0{,}1\\ \\text{kg}$ yang diam ditendang hingga kelajuannya menjadi $20\\ \\text{m/s}$ dalam selang waktu $0{,}05\\ \\text{s}$. Gaya rata-rata yang bekerja pada bola tersebut adalah ...", options: ["$2\\ \\text{N}$", "$40\\ \\text{N}$", "$0{,}1\\ \\text{N}$", "$400\\ \\text{N}$"], answer: 1, solution: "1. Gaya rata-rata $F = \\frac{\\Delta p}{\\Delta t} = \\frac{m(v - 0)}{\\Delta t}$. 2. $F = \\frac{0{,}1\\cdot20}{0{,}05} = \\frac{2}{0{,}05} = 40\\ \\text{N}$. 3. Kesalahan umum: berhenti di $\\Delta p = 2\\ \\text{N}\\cdot\\text{s}$ lalu mengira itu gaya; gaya adalah impuls per satuan waktu dengan satuan newton." },
  { q: "Balok $1\\ \\text{kg}$ dan balok $3\\ \\text{kg}$ yang mula-mula diam menerima impuls yang sama besar. Pernyataan yang benar adalah ...", options: ["perubahan momentum kedua balok sama besar", "perubahan momentum balok $1\\ \\text{kg}$ lebih besar", "perubahan momentum balok $3\\ \\text{kg}$ lebih besar", "kelajuan akhir kedua balok sama besar"], answer: 0, solution: "1. Impuls sama dengan perubahan momentum: $I = \\Delta p$. 2. Karena $I$ sama, $\\Delta p$ keduanya sama besar; yang berbeda adalah kelajuan akhirnya ($v = \\Delta p/m$, balok yang ringan melaju lebih cepat). 3. Jangan tertukar: impuls menentukan perubahan momentum, bukan langsung menentukan kecepatannya." },
  { q: "Benda A ($2\\ \\text{kg}$) bergerak ke kanan dengan kelajuan $3\\ \\text{m/s}$, sedangkan benda B ($3\\ \\text{kg}$) bergerak ke kiri dengan kelajuan $2\\ \\text{m/s}$. Momentum total sistem kedua benda tersebut adalah ...", options: ["$12\\ \\text{kg}\\cdot\\text{m/s}$ ke kanan", "$0$", "$6\\ \\text{kg}\\cdot\\text{m/s}$ ke kanan", "$12\\ \\text{kg}\\cdot\\text{m/s}$ ke kiri"], answer: 1, solution: "1. Ambil arah kanan sebagai positif: $p_A = 2\\cdot3 = +6$ dan $p_B = 3\\cdot(-2) = -6$ (satuan $\\text{kg}\\cdot\\text{m/s}$). 2. $p_{total} = 6 + (-6) = 0$. 3. Momentum adalah vektor; kesalahan umum adalah menjumlahkan besarnya saja ($6 + 6 = 12$) tanpa memperhatikan arah yang berlawanan." },
  { q: "Peluru $0{,}02\\ \\text{kg}$ ditembakkan dengan kelajuan $200\\ \\text{m/s}$ lalu menancap pada balok kayu $1{,}98\\ \\text{kg}$ yang diam. Kelajuan balok beserta peluru sesaat setelah tumbukan adalah ...", options: ["$200\\ \\text{m/s}$", "$0{,}2\\ \\text{m/s}$", "$2\\ \\text{m/s}$", "$4\\ \\text{m/s}$"], answer: 2, solution: "1. Tumbukan tak lenting: momentum kekal, $m_p v_p = (m_p + m_b)v'$. 2. $v' = \\frac{0{,}02\\cdot200}{0{,}02 + 1{,}98} = \\frac{4}{2} = 2\\ \\text{m/s}$ searah tembakan. 3. Jangan memakai kekekalan energi kinetik di sini; pada tumbukan tak lenting sebagian energi berubah menjadi panas dan deformasi." },
  { q: "Bola $1\\ \\text{kg}$ bergerak dengan kelajuan $6\\ \\text{m/s}$ menumbuk lenting sempurna bola $3\\ \\text{kg}$ yang diam. Kelajuan bola $3\\ \\text{kg}$ sesaat setelah tumbukan adalah ...", options: ["$3\\ \\text{m/s}$", "$6\\ \\text{m/s}$", "$-3\\ \\text{m/s}$", "$1{,}5\\ \\text{m/s}$"], answer: 0, solution: "1. Untuk tumbukan lenting sempurna satu dimensi dengan $m_2$ mula-mula diam: $v_2' = \\frac{2m_1}{m_1+m_2}v_1$. 2. $v_2' = \\frac{2\\cdot1}{1+3}\\cdot6 = \\frac{2}{4}\\cdot6 = 3\\ \\text{m/s}$. 3. Nilai $-3\\ \\text{m/s}$ adalah kecepatan bola $1\\ \\text{kg}$ setelah tumbukan (ia memantul balik); jangan tertukar antara kedua bola." },
  { q: "Bola dijatuhkan dari ketinggian $1{,}8\\ \\text{m}$ dan memantul hingga ketinggian $0{,}8\\ \\text{m}$. Koefisien restitusi tumbukan bola dengan lantai adalah ...", options: ["$\\frac{4}{9}$", "$\\frac{2}{3}$", "$\\frac{1}{2}$", "$\\frac{3}{4}$"], answer: 1, solution: "1. Untuk pantulan vertikal berlaku $e = \\sqrt{\\frac{h'}{h}}$ karena $v = \\sqrt{2gh}$. 2. $e = \\sqrt{\\frac{0{,}8}{1{,}8}} = \\sqrt{\\frac{4}{9}} = \\frac{2}{3}$. 3. Kesalahan umum: lupa mengakarkuadratkan sehingga menjawab $\\frac{4}{9}$; koefisien restitusi membandingkan kecepatan, bukan ketinggian." },
  { q: "Dua bola identik bermassa $1\\ \\text{kg}$ bergerak saling mendekat masing-masing dengan kelajuan $4\\ \\text{m/s}$, lalu bertumbukan dan menempel. Energi kinetik yang hilang dalam tumbukan tersebut adalah ...", options: ["$32\\ \\text{J}$", "$8\\ \\text{J}$", "$16\\ \\text{J}$", "$0$"], answer: 2, solution: "1. $E_{k,awal} = 2\\cdot\\frac{1}{2}\\cdot1\\cdot4^2 = 16\\ \\text{J}$; momentum total sistem nol sehingga setelah menempel keduanya diam ($E_{k,akhir} = 0$). 2. Energi yang hilang $= 16 - 0 = 16\\ \\text{J}$, berubah menjadi panas, bunyi, dan deformasi. 3. Pada tumbukan tak lenting energi kinetik tidak kekal; yang selalu kekal adalah momentum." },
  { q: "Gaya $50\\ \\text{N}$ bekerja pada sebuah pintu dengan garis kerja tepat sejajar lengan gaya ($r = 0{,}8\\ \\text{m}$; sudut antara $\\vec{r}$ dan $\\vec{F}$ adalah $0^\\circ$). Besar torsi terhadap engsel pintu adalah ...", options: ["$0$", "$40\\ \\text{N}\\cdot\\text{m}$", "$50\\ \\text{N}\\cdot\\text{m}$", "$0{,}8\\ \\text{N}\\cdot\\text{m}$"], answer: 0, solution: "1. $\\tau = r\\cdot F\\cdot\\sin\\theta = 0{,}8\\cdot50\\cdot\\sin 0^\\circ$. 2. Karena $\\sin 0^\\circ = 0$, torsinya $0$; gaya yang sejajar lengan hanya menarik atau mendorong poros, tidak memutar. 3. Kesalahan umum: tetap mengalikan $r\\cdot F = 40$; torsi membutuhkan komponen gaya yang tegak lurus lengan." },
  { q: "Sebuah batang $0{,}6\\ \\text{m}$ diputar oleh kopel: dua gaya $10\\ \\text{N}$ yang sama besar tetapi berlawanan arah, masing-masing bekerja di kedua ujung batang dan tegak lurus batang. Torsi total terhadap pusat batang adalah ...", options: ["$3\\ \\text{N}\\cdot\\text{m}$", "$6\\ \\text{N}\\cdot\\text{m}$", "$12\\ \\text{N}\\cdot\\text{m}$", "$0$"], answer: 1, solution: "1. Masing-masing gaya memberi torsi $F\\cdot\\frac{L}{2} = 10\\cdot0{,}3 = 3\\ \\text{N}\\cdot\\text{m}$ dengan arah putar yang sama. 2. $\\tau_{total} = 3 + 3 = 6\\ \\text{N}\\cdot\\text{m}$ (atau langsung $\\tau = F\\cdot d = 10\\cdot0{,}6$). 3. Meski resultan gayanya nol, kopel tetap menghasilkan torsi; jangan terkecoh menjawab $0$." },
  { q: "Gaya $20\\ \\text{N}$ bekerja pada jarak $0{,}5\\ \\text{m}$ dari poros dengan sudut $30^\\circ$ terhadap lengan. Besar torsi yang dihasilkan adalah ...", options: ["$10\\ \\text{N}\\cdot\\text{m}$", "$5\\sqrt{3}\\ \\text{N}\\cdot\\text{m}$", "$5\\ \\text{N}\\cdot\\text{m}$", "$2{,}5\\ \\text{N}\\cdot\\text{m}$"], answer: 2, solution: "1. $\\tau = rF\\sin\\theta = 0{,}5\\cdot20\\cdot\\sin 30^\\circ$. 2. $\\tau = 10\\cdot\\frac{1}{2} = 5\\ \\text{N}\\cdot\\text{m}$. 3. Kesalahan umum: memakai $\\cos 30^\\circ$ sehingga mendapat $5\\sqrt{3}$; torsi memakai sinus sudut antara $\\vec{r}$ dan $\\vec{F}$, bukan kosinus." },
  { q: "Dengan konvensi torsi positif berlawanan arah jarum jam, sebuah torsi yang memutar benda searah jarum jam sebesar $8\\ \\text{N}\\cdot\\text{m}$ ditulis sebagai ...", options: ["$8\\ \\text{N}\\cdot\\text{m}$", "$0$", "$-8\\ \\text{N}\\cdot\\text{m}$", "tidak dapat ditentukan tandanya"], answer: 2, solution: "1. Tanda torsi mengikuti konvensi arah putaran yang disepakati. 2. Putaran searah jarum jam berlawanan dengan arah positif, jadi torsinya $-8\\ \\text{N}\\cdot\\text{m}$. 3. Tanda negatif di sini hanya menyatakan arah, bukan 'lebih kecil'; kesalahan umum adalah mengira torsi searah jarum jam selalu positif." },
  { q: "Sebuah jungkat-jungkit setimbang dengan anak bermassa $30\\ \\text{kg}$ duduk $2\\ \\text{m}$ dari poros. Agar tetap setimbang, anak bermassa $20\\ \\text{kg}$ harus duduk pada jarak ... dari poros di sisi yang berlawanan.", options: ["$3\\ \\text{m}$", "$2\\ \\text{m}$", "$1{,}5\\ \\text{m}$", "$6\\ \\text{m}$"], answer: 0, solution: "1. Setimbang berarti torsi kedua sisi sama besar: $m_1 g d_1 = m_2 g d_2$ ($g$ saling meniadakan). 2. $d_2 = \\frac{30\\cdot2}{20} = 3\\ \\text{m}$. 3. Anak yang lebih ringan harus duduk lebih jauh dari poros; inilah prinsip tuas: yang kalah massa menang jarak." },
  { q: "Pada sebuah batang, gaya $10\\ \\text{N}$ bekerja $0{,}3\\ \\text{m}$ dari poros dan memutar berlawanan arah jarum jam, sedangkan gaya $15\\ \\text{N}$ bekerja $0{,}2\\ \\text{m}$ dari poros dan memutar searah jarum jam. Torsi total terhadap poros tersebut adalah ...", options: ["$6\\ \\text{N}\\cdot\\text{m}$", "$0$", "$-6\\ \\text{N}\\cdot\\text{m}$", "$3\\ \\text{N}\\cdot\\text{m}$"], answer: 1, solution: "1. $\\tau_1 = +10\\cdot0{,}3 = +3$ dan $\\tau_2 = -15\\cdot0{,}2 = -3$ (satuan $\\text{N}\\cdot\\text{m}$). 2. $\\tau_{total} = 3 - 3 = 0$; batang berada dalam keseimbangan rotasi. 3. Torsi adalah besaran bertanda: gaya-gaya yang memutar berlawanan arah saling mengurangi, bukan dijumlahkan besarnya ($6$)." },
  { q: "Cincin tipis dan cakram pejal memiliki massa dan jari-jari yang sama. Benda yang momen inersianya lebih besar adalah ...", options: ["cincin tipis", "cakram pejal", "keduanya sama besar", "tergantung kecepatan sudutnya"], answer: 0, solution: "1. $I_{cincin} = mR^2$ sedangkan $I_{cakram} = \\frac{1}{2}mR^2$. 2. Karena seluruh massa cincin berada pada jarak $R$ dari sumbu, momen inersianya dua kali lipat cakram. 3. Momen inersia ditentukan oleh distribusi massa terhadap sumbu, bukan hanya massa total; massa yang jauh dari sumbu 'lebih berat' untuk diputar." },
  { q: "Batang homogen bermassa $3\\ \\text{kg}$ dan panjang $2\\ \\text{m}$ diputar terhadap sumbu yang melalui salah satu ujungnya dan tegak lurus batang. Momen inersia batang tersebut adalah ...", options: ["$1\\ \\text{kg}\\cdot\\text{m}^2$", "$4\\ \\text{kg}\\cdot\\text{m}^2$", "$12\\ \\text{kg}\\cdot\\text{m}^2$", "$2\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 1, solution: "1. $I_{ujung} = \\frac{1}{3}ML^2 = \\frac{1}{3}\\cdot3\\cdot2^2$. 2. $I = \\frac{1}{3}\\cdot3\\cdot4 = 4\\ \\text{kg}\\cdot\\text{m}^2$. 3. Jangan tertukar dengan $I_{pusat} = \\frac{1}{12}ML^2 = 1\\ \\text{kg}\\cdot\\text{m}^2$; sumbu di ujung memberi momen inersia empat kali lipat sumbu di pusat." },
  { q: "Bola pejal homogen bermassa $5\\ \\text{kg}$ dan berjari-jari $0{,}4\\ \\text{m}$ berputar terhadap sumbunya. Momen inersia bola tersebut adalah ...", options: ["$0{,}8\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}53\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}32\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}4\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 2, solution: "1. $I_{bola\\ pejal} = \\frac{2}{5}MR^2 = \\frac{2}{5}\\cdot5\\cdot(0{,}4)^2$. 2. $I = 2\\cdot0{,}16 = 0{,}32\\ \\text{kg}\\cdot\\text{m}^2$. 3. Hafalkan koefisiennya: bola pejal $\\frac{2}{5}$, bola berongga tipis $\\frac{2}{3}$ ($0{,}53$), cakram $\\frac{1}{2}$ ($0{,}4$); tertukar rumus adalah kesalahan paling umum." },
  { q: "Cakram pejal bermassa $2\\ \\text{kg}$ dan berjari-jari $0{,}5\\ \\text{m}$ diputar terhadap sumbu yang sejajar sumbu pusatnya tetapi melalui sebuah titik di tepinya. Momen inersia cakram tersebut adalah ...", options: ["$0{,}25\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}5\\ \\text{kg}\\cdot\\text{m}^2$", "$1{,}0\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}75\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 3, solution: "1. Teorema sumbu sejajar: $I = I_{pusat} + Md^2$ dengan jarak geser $d = R$. 2. $I = \\frac{1}{2}\\cdot2\\cdot0{,}25 + 2\\cdot0{,}25 = 0{,}25 + 0{,}5 = 0{,}75\\ \\text{kg}\\cdot\\text{m}^2$. 3. Suku $Md^2$ tidak boleh dilupakan; menggeser sumbu selalu memperbesar momen inersia." },
  { q: "Dua partikel masing-masing bermassa $2\\ \\text{kg}$ pada jarak $1\\ \\text{m}$ dan $3\\ \\text{kg}$ pada jarak $2\\ \\text{m}$ dari sumbu putar. Momen inersia sistem terhadap sumbu tersebut adalah ...", options: ["$14\\ \\text{kg}\\cdot\\text{m}^2$", "$5\\ \\text{kg}\\cdot\\text{m}^2$", "$7\\ \\text{kg}\\cdot\\text{m}^2$", "$20\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 0, solution: "1. $I = \\sum mr^2 = 2\\cdot1^2 + 3\\cdot2^2$. 2. $I = 2 + 12 = 14\\ \\text{kg}\\cdot\\text{m}^2$. 3. Jarak harus dikuadratkan; jawaban $5$ berasal dari $2\\cdot1 + 3\\cdot2$ (lupa kuadrat), kesalahan paling umum pada soal momen inersia partikel." },
  { q: "Dua batang bermassa sama dan panjang sama diputar terhadap sumbu di pusatnya. Batang P massanya terkonsentrasi di kedua ujung, sedangkan batang Q massanya terkonsentrasi di tengah. Pernyataan yang benar adalah ...", options: ["momen inersia Q lebih besar", "keduanya sama besar", "momen inersia P lebih besar", "keduanya nol"], answer: 2, solution: "1. Dari $I = \\sum mr^2$, massa yang jauh dari sumbu memberi kontribusi kuadrat jarak yang besar. 2. Massa batang P rata-rata lebih jauh dari sumbu, jadi $I_P > I_Q$. 3. Inilah alasan momen inersia disebut kelembaman rotasi yang bergantung pada distribusi massa; massa total sama belum tentu momen inersianya sama." },
  { q: "Batang homogen bermassa $6\\ \\text{kg}$ dan panjang $1\\ \\text{m}$ diputar terhadap sumbu yang melalui pusat massanya dan tegak lurus batang. Momen inersia batang tersebut adalah ...", options: ["$2\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}25\\ \\text{kg}\\cdot\\text{m}^2$", "$6\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}5\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 3, solution: "1. $I_{pusat} = \\frac{1}{12}ML^2 = \\frac{1}{12}\\cdot6\\cdot1^2$. 2. $I = 0{,}5\\ \\text{kg}\\cdot\\text{m}^2$. 3. Jangan tertukar dengan $\\frac{1}{3}ML^2 = 2$ (itu untuk sumbu di ujung); selalu periksa dulu di mana letak sumbu putarnya." },
  { q: "Silinder berongga tipis bermassa $4\\ \\text{kg}$ dan berjari-jari $0{,}3\\ \\text{m}$ berputar terhadap sumbu silindernya. Momen inersia silinder tersebut adalah ...", options: ["$0{,}36\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}18\\ \\text{kg}\\cdot\\text{m}^2$", "$0{,}144\\ \\text{kg}\\cdot\\text{m}^2$", "$1{,}44\\ \\text{kg}\\cdot\\text{m}^2$"], answer: 0, solution: "1. Untuk selubung tipis seluruh massa berjarak $R$ dari sumbu: $I = MR^2 = 4\\cdot(0{,}3)^2$. 2. $I = 4\\cdot0{,}09 = 0{,}36\\ \\text{kg}\\cdot\\text{m}^2$. 3. Jangan memakai $\\frac{1}{2}MR^2$ ($0{,}18$); itu rumus silinder pejal, sedangkan selubung tipis tidak memiliki faktor $\\frac{1}{2}$." },
  { q: "Benda tegar dengan momen inersia $2\\ \\text{kg}\\cdot\\text{m}^2$ berputar dengan kecepatan sudut $5\\ \\text{rad/s}$. Energi kinetik rotasi benda tersebut adalah ...", options: ["$50\\ \\text{J}$", "$25\\ \\text{J}$", "$5\\ \\text{J}$", "$10\\ \\text{J}$"], answer: 1, solution: "1. $E_{k,rot} = \\frac{1}{2}I\\omega^2 = \\frac{1}{2}\\cdot2\\cdot5^2$. 2. $E_k = 1\\cdot25 = 25\\ \\text{J}$. 3. Ada dua jebakan sekaligus: lupa faktor $\\frac{1}{2}$ ($50\\ \\text{J}$) dan lupa menguadratkan $\\omega$ ($5\\ \\text{J}$); rumusnya analog dengan $\\frac{1}{2}mv^2$." },
  { q: "Roda pejal berbentuk cakram bermassa $10\\ \\text{kg}$ dan berjari-jari $0{,}5\\ \\text{m}$ berputar terhadap porosnya dengan $\\omega = 4\\ \\text{rad/s}$. Energi kinetik rotasi roda tersebut adalah ...", options: ["$20\\ \\text{J}$", "$40\\ \\text{J}$", "$10\\ \\text{J}$", "$5\\ \\text{J}$"], answer: 2, solution: "1. $I = \\frac{1}{2}MR^2 = \\frac{1}{2}\\cdot10\\cdot0{,}25 = 1{,}25\\ \\text{kg}\\cdot\\text{m}^2$. 2. $E_k = \\frac{1}{2}\\cdot1{,}25\\cdot4^2 = 0{,}625\\cdot16 = 10\\ \\text{J}$. 3. Jika memakai $I = MR^2$ (rumus cincin) akan didapat $20\\ \\text{J}$; pastikan koefisien momen inersia sesuai dengan bentuk bendanya." },
  { q: "Roda A dan roda B berputar dengan energi kinetik rotasi yang sama. Jika momen inersia A empat kali momen inersia B ($I_A = 4I_B$), kecepatan sudut A dibandingkan dengan kecepatan sudut B adalah ...", options: ["dua kali lipat", "setengahnya", "empat kali lipat", "sama besar"], answer: 1, solution: "1. $\\frac{1}{2}I_A\\omega_A^2 = \\frac{1}{2}I_B\\omega_B^2$ sehingga $4I_B\\omega_A^2 = I_B\\omega_B^2$. 2. $\\omega_A^2 = \\frac{1}{4}\\omega_B^2$, jadi $\\omega_A = \\frac{1}{2}\\omega_B$. 3. Hubungannya berupa akar kuadrat, bukan linear; momen inersia empat kali lipat hanya membutuhkan kecepatan sudut setengahnya, bukan seperempatnya." },
  { q: "Torsi konstan $6\\ \\text{N}\\cdot\\text{m}$ memutar sebuah benda sebesar sudut $4\\pi\\ \\text{rad}$. Usaha yang dilakukan oleh torsi tersebut adalah ...", options: ["$12\\pi\\ \\text{J}$", "$48\\pi\\ \\text{J}$", "$6\\pi\\ \\text{J}$", "$24\\pi\\ \\text{J}$"], answer: 3, solution: "1. Usaha oleh torsi konstan $W = \\tau\\cdot\\Delta\\theta$, analog rotasi dari $W = F\\cdot s$. 2. $W = 6\\cdot4\\pi = 24\\pi\\ \\text{J}$. 3. Sudut harus dalam radian; jika memakai derajat ($720^\\circ$) tanpa konversi, hasilnya salah total." },
  { q: "Partikel bermassa $2\\ \\text{kg}$ bergerak lurus dengan kelajuan $5\\ \\text{m/s}$; jarak tegak lurus antara lintasan dan titik acuan adalah $3\\ \\text{m}$. Besar momentum sudut partikel terhadap titik acuan tersebut adalah ...", options: ["$15\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$30\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$10\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$90\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$"], answer: 1, solution: "1. $L = m\\cdot v\\cdot r_{\\perp} = 2\\cdot5\\cdot3$. 2. $L = 30\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$. 3. Yang dipakai adalah jarak tegak lurus dari titik acuan ke garis lintasan, bukan jarak sepanjang lintasan; dan jangan menambahkan faktor $\\frac{1}{2}$ seperti pada energi kinetik." },
  { q: "Benda tegar bermomen inersia $0{,}4\\ \\text{kg}\\cdot\\text{m}^2$ berputar dengan kecepatan sudut $10\\ \\text{rad/s}$. Besar momentum sudut benda tersebut adalah ...", options: ["$2\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$40\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$4\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$", "$0{,}4\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$"], answer: 2, solution: "1. $L = I\\cdot\\omega = 0{,}4\\cdot10$. 2. $L = 4\\ \\text{kg}\\cdot\\text{m}^2/\\text{s}$. 3. Rumus $L = I\\omega$ adalah analog rotasi dari $p = mv$; tidak ada faktor $\\frac{1}{2}$, sedangkan jawaban $2$ berasal dari kekeliruan memakai $\\frac{1}{2}I\\omega$." },
  { q: "Seorang penari es yang sedang berputar menarik kedua tangannya merapat ke tubuh sehingga momen inersianya menjadi setengah dari semula. Kecepatan sudutnya menjadi ...", options: ["setengah dari semula", "tetap", "empat kali lipat", "dua kali lipat dari semula"], answer: 3, solution: "1. Torsi luar nol sehingga momentum sudut kekal: $I_1\\omega_1 = I_2\\omega_2$. 2. $\\omega_2 = \\frac{I_1}{I_2}\\omega_1 = \\frac{I_1}{I_1/2}\\omega_1 = 2\\omega_1$. 3. Intuisi yang keliru: 'massa tidak berubah jadi kecepatannya tetap'; yang kekal adalah $I\\omega$, dan $I$ berubah ketika distribusi massa berubah." },
  { q: "Cakram bermomen inersia $3\\ \\text{kg}\\cdot\\text{m}^2$ berputar dengan kecepatan sudut $4\\ \\text{rad/s}$. Cakram kedua yang diam dan bermomen inersia sama ($3\\ \\text{kg}\\cdot\\text{m}^2$) dijatuhkan koaksial di atasnya hingga keduanya berputar bersama. Kecepatan sudut akhirnya adalah ...", options: ["$4\\ \\text{rad/s}$", "$2\\ \\text{rad/s}$", "$8\\ \\text{rad/s}$", "$1\\ \\text{rad/s}$"], answer: 1, solution: "1. Momentum sudut kekal karena torsi luar nol: $I_1\\omega_1 = (I_1 + I_2)\\omega'$. 2. $\\omega' = \\frac{3\\cdot4}{3+3} = \\frac{12}{6} = 2\\ \\text{rad/s}$. 3. Ini adalah analog rotasi dari tumbukan tak lenting: momentum (sudut) kekal, sedangkan energi kinetik (rotasi) berkurang." },
  { q: "Sebuah roda berputar berlawanan arah jarum jam jika dilihat dari depan, dengan sumbu putar $+z$ mengarah ke pengamat. Vektor momentum sudut roda tersebut mengarah ...", options: ["ke atas", "menjauhi pengamat", "ke arah pengamat", "ke bawah"], answer: 2, solution: "1. Kaidah tangan kanan: lengkungkan jari-jari mengikuti arah putaran, ibu jari menunjukkan arah $\\vec{L}$. 2. Putaran berlawanan arah jarum jam dilihat dari $+z$ membuat ibu jari menunjuk ke $+z$, yaitu ke arah pengamat. 3. Kesalahan umum: mengira vektornya menyinggung lingkaran seperti kecepatan; $\\vec{L}$ selalu searah sumbu putar, bukan searah gerak titiknya." },
  { q: "Torsi total yang bekerja pada suatu sistem benda tegar adalah nol. Momentum sudut sistem tersebut ...", options: ["berkurang", "bertambah", "nol", "tetap (kekal)"], answer: 3, solution: "1. Analog rotasi dari Hukum II Newton: $\\tau_{total} = \\frac{dL}{dt}$. 2. Jika $\\tau_{total} = 0$ maka $\\frac{dL}{dt} = 0$, artinya $L$ tetap (kekal). 3. Jangan tertukar: torsi nol membuat momentum sudut kekal, bukan nol; 'tidak ada perubahan' berbeda dengan 'nilainya nol'." },
  { q: "Roda berjari-jari $0{,}4\\ \\text{m}$ menggelinding tanpa slip dengan kecepatan sudut $5\\ \\text{rad/s}$. Kecepatan pusat massa roda tersebut adalah ...", options: ["$2\\ \\text{m/s}$", "$12{,}5\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$0{,}4\\ \\text{m/s}$"], answer: 0, solution: "1. Syarat menggelinding tanpa slip: $v_{cm} = \\omega R$. 2. $v_{cm} = 5\\cdot0{,}4 = 2\\ \\text{m/s}$. 3. Kesalahan umum: membagi $\\omega/R = 12{,}5$; periksa dimensinya, $\\omega R$ memberi $(1/\\text{s})\\cdot\\text{m} = \\text{m/s}$ yang benar." },
  { q: "Silinder pejal bermassa $4\\ \\text{kg}$ menggelinding tanpa slip dengan kelajuan pusat massa $2\\ \\text{m/s}$. Energi kinetik total silinder tersebut adalah ...", options: ["$8\\ \\text{J}$", "$12\\ \\text{J}$", "$16\\ \\text{J}$", "$4\\ \\text{J}$"], answer: 1, solution: "1. $E_{k,total} = E_{k,trans} + E_{k,rot} = \\frac{1}{2}Mv^2 + \\frac{1}{2}\\left(\\frac{1}{2}MR^2\\right)\\left(\\frac{v}{R}\\right)^2$. 2. $= \\frac{1}{2}\\cdot4\\cdot4 + \\frac{1}{4}\\cdot4\\cdot4 = 8 + 4 = 12\\ \\text{J}$. 3. Kesalahan paling umum: hanya menghitung energi translasi ($8\\ \\text{J}$) dan melupakan bahwa benda yang menggelinding juga berputar." },
  { q: "Bola pejal, silinder pejal, dan cincin tipis yang bermassa dan berjari-jari sama dilepas bersamaan dari puncak bidang miring yang sama dan menggelinding tanpa slip. Benda yang mencapai dasar paling cepat adalah ...", options: ["cincin tipis", "silinder pejal", "bola pejal", "ketiganya tiba bersamaan"], answer: 2, solution: "1. Percepatan menggelinding $a = \\frac{g\\sin\\theta}{1 + \\beta}$ dengan $\\beta = I/(MR^2)$: bola pejal $\\beta = \\frac{2}{5}$, silinder pejal $\\frac{1}{2}$, cincin tipis $1$. 2. Nilai $\\beta$ terkecil memberi $a$ terbesar, jadi bola pejal tiba paling cepat. 3. Makin besar porsi energi yang 'terkunci' dalam rotasi, makin lambat translasinya; cincin paling lambat karena momen inersianya terbesar." },
  { q: "Bola berongga tipis menggelinding tanpa slip menuruni bidang miring dengan sudut kemiringan $30^\\circ$ ($g = 10\\ \\text{m/s}^2$). Percepatan pusat massanya adalah ...", options: ["$5\\ \\text{m/s}^2$", "$10\\ \\text{m/s}^2$", "$3\\ \\text{m/s}^2$", "$1{,}5\\ \\text{m/s}^2$"], answer: 2, solution: "1. $a = \\frac{g\\sin\\theta}{1 + \\beta}$; untuk bola berongga tipis $\\beta = \\frac{2}{3}$. 2. $a = \\frac{10\\cdot\\sin 30^\\circ}{1 + 2/3} = \\frac{5}{5/3} = 3\\ \\text{m/s}^2$. 3. Jawaban $5\\ \\text{m/s}^2$ adalah percepatan meluncur tanpa rotasi ($g\\sin\\theta$); menggelinding selalu lebih lambat karena sebagian energi menjadi energi rotasi." },
  { q: "Sebuah bola menggelinding tanpa slip menuruni bidang miring. Jenis gaya gesek yang bekerja pada titik kontak antara bola dan bidang adalah gesek ...", options: ["kinetis", "nol (tidak ada gesekan)", "gesek udara", "statis"], answer: 3, solution: "1. Syarat tanpa slip berarti titik kontak sesaat diam relatif terhadap bidang. 2. Tidak ada gerak relatif berarti gesekannya statis; justru gesekan inilah yang menyediakan torsi agar bola berputar. 3. Miskonsepsi umum: 'gesekan menghambat, jadi menggelinding butuh lantai licin'; sebaliknya, tanpa gesekan statis bola hanya meluncur tanpa berputar." },
  { q: "Bola pejal dilepas dari ketinggian $7\\ \\text{m}$ pada sebuah bidang miring dan menggelinding tanpa slip ($g = 10\\ \\text{m/s}^2$). Kelajuan pusat massa bola saat mencapai dasar bidang adalah ...", options: ["$10\\ \\text{m/s}$", "$\\sqrt{140}\\ \\text{m/s}$", "$20\\ \\text{m/s}$", "$7\\ \\text{m/s}$"], answer: 0, solution: "1. Kekekalan energi: $mgh = \\frac{1}{2}Mv^2 + \\frac{1}{2}I\\omega^2 = \\frac{1}{2}Mv^2(1 + \\beta)$ dengan $\\beta = \\frac{2}{5}$ untuk bola pejal. 2. $v = \\sqrt{\\frac{2gh}{1{,}4}} = \\sqrt{\\frac{140}{1{,}4}} = \\sqrt{100} = 10\\ \\text{m/s}$. 3. $\\sqrt{140}\\ \\text{m/s}$ adalah kelajuan jika bola meluncur tanpa berputar; menggelinding membagi energi menjadi translasi dan rotasi sehingga kelajuannya lebih kecil." },
// ===== OSILASI & GELOMBANG (18) =====
  // --- GHS pegas & bandul (6) ---
  { q: "Sebuah pegas memiliki konstanta $150\\ \\text{N/m}$. Ketika pegas ditarik sejauh $0{,}04\\ \\text{m}$ dari posisi setimbangnya, besar gaya pemulih pegas adalah ...", options: ["$3{,}75\\ \\text{N}$", "$6000\\ \\text{N}$", "$6\\ \\text{N}$", "$0{,}6\\ \\text{N}$"], answer: 2, solution: "1. Hukum Hooke: $F = k\\,\\Delta x$. 2. Substitusi $k = 150\\ \\text{N/m}$ dan $\\Delta x = 0{,}04\\ \\text{m}$: $F = 150 \\times 0{,}04 = 6\\ \\text{N}$. 3. Arah gaya pemulih selalu menuju posisi setimbang (berlawanan dengan arah tarikan). Kesalahan umum: membalik rumus menjadi $F = k/\\Delta x$ atau lupa mengubah satuan sehingga mendapat $6000\\ \\text{N}$." },
  { q: "Sebuah beban bermassa $0{,}5\\ \\text{kg}$ digantung pada pegas dengan konstanta $50\\ \\text{N/m}$ lalu digetarkan. Periode getaran harmoniknya adalah ...", options: ["$0{,}2\\pi\\ \\text{s}$", "$0{,}1\\pi\\ \\text{s}$", "$2\\pi\\ \\text{s}$", "$\\pi\\ \\text{s}$"], answer: 0, solution: "1. Periode getaran pegas: $T = 2\\pi\\sqrt{m/k}$. 2. $m/k = 0{,}5/50 = 0{,}01$, sehingga $T = 2\\pi\\sqrt{0{,}01} = 2\\pi \\times 0{,}1 = 0{,}2\\pi\\ \\text{s}$. Kesalahan umum: tertukar rumus periode dan frekuensi — frekuensinya $f = 1/T = 5/\\pi\\ \\text{Hz}$, bukan $0{,}2\\pi\\ \\text{Hz}$." },
  { q: "Sebuah benda bermassa $0{,}5\\ \\text{kg}$ bergetar harmonik pada pegas dengan konstanta $50\\ \\text{N/m}$ dan amplitudo $0{,}2\\ \\text{m}$. Kelajuan maksimum benda adalah ...", options: ["$1\\ \\text{m/s}$", "$2\\ \\text{m/s}$", "$0{,}2\\ \\text{m/s}$", "$20\\ \\text{m/s}$"], answer: 1, solution: "1. $v_{maks} = A\\,\\omega$ dengan $\\omega = \\sqrt{k/m}$. 2. $\\omega = \\sqrt{50/0{,}5} = \\sqrt{100} = 10\\ \\text{rad/s}$. 3. $v_{maks} = 0{,}2 \\times 10 = 2\\ \\text{m/s}$ (tercapai saat benda melewati titik setimbang, $x = 0$). Kesalahan umum: mengira kelajuan maksimum terjadi di titik balik — justru di titik balik kelajuan nol dan di titik setimbanglah kelajuan maksimum." },
  { q: "Simpangan sebuah getaran harmonik memenuhi $y = 0{,}1\\sin\\left(\\frac{\\pi}{2}t\\right)$ ($y$ dalam meter, $t$ dalam sekon). Simpangan benda saat $t = 1\\ \\text{s}$ adalah ...", options: ["$0{,}1\\ \\text{m}$", "$0\\ \\text{m}$", "$0{,}05\\ \\text{m}$", "$-0{,}1\\ \\text{m}$"], answer: 0, solution: "1. Substitusi $t = 1\\ \\text{s}$: $y = 0{,}1\\sin\\left(\\frac{\\pi}{2}\\cdot 1\\right) = 0{,}1\\sin\\left(\\frac{\\pi}{2}\\right)$. 2. $\\sin\\left(\\frac{\\pi}{2}\\right) = 1$, jadi $y = 0{,}1\\ \\text{m}$ — benda tepat di titik balik (simpangan maksimum). 3. Cek silang: $\\omega = \\pi/2$ berarti $T = 2\\pi/\\omega = 4\\ \\text{s}$, dan $t = 1\\ \\text{s} = T/4$ memang saat simpangan maksimum pertama. Kesalahan umum: menghitung argumen sinus dalam derajat tanpa konversi — argumen fungsi sinus getaran selalu dalam radian." },
  { q: "Sebuah bandul sederhana berayun dengan periode $1{,}5\\ \\text{s}$. Jika panjang tali bandul dijadikan $4$ kali semula (simpangan tetap kecil), periode barunya adalah ...", options: ["$6\\ \\text{s}$", "$1{,}5\\ \\text{s}$", "$0{,}75\\ \\text{s}$", "$3\\ \\text{s}$"], answer: 3, solution: "1. Periode bandul $T = 2\\pi\\sqrt{L/g}$, jadi $T$ sebanding dengan $\\sqrt{L}$. 2. Panjang dijadikan $4$ kali: faktor pengali periode $= \\sqrt{4} = 2$. 3. $T_{baru} = 2 \\times 1{,}5 = 3\\ \\text{s}$. Kesalahan umum: mengira periode ikut menjadi $4$ kali (lupa ada akar kuadrat) — periode bandul sebanding dengan akar panjang tali, bukan panjang talinya langsung." },
  { q: "Pegas dengan konstanta $400\\ \\text{N/m}$ ditekan sehingga menyimpang $0{,}03\\ \\text{m}$ dari posisi setimbang. Energi potensial pegas pada saat itu adalah ...", options: ["$0{,}36\\ \\text{J}$", "$12\\ \\text{J}$", "$0{,}18\\ \\text{J}$", "$1{,}8\\ \\text{J}$"], answer: 2, solution: "1. $E_p = \\frac{1}{2}k(\\Delta x)^2$. 2. $E_p = \\frac{1}{2}\\cdot 400 \\cdot (0{,}03)^2 = 200 \\cdot 0{,}0009 = 0{,}18\\ \\text{J}$. Kesalahan umum: memakai $E_p = k\\Delta x = 12\\ \\text{J}$ (itu rumus gaya Hooke, bukan energi) atau lupa faktor $\\frac{1}{2}$ sehingga mendapat $0{,}36\\ \\text{J}$." },
  // --- periode-frekuensi (4) ---
  { q: "Sebuah bandul melakukan $150$ kali ayunan dalam waktu $50\\ \\text{s}$. Frekuensi ayunan bandul tersebut adalah ...", options: ["$\\frac{1}{3}\\ \\text{Hz}$", "$3\\ \\text{Hz}$", "$0{,}3\\ \\text{Hz}$", "$75\\ \\text{Hz}$"], answer: 1, solution: "1. Frekuensi $f = n/t$ (banyak getaran per satuan waktu). 2. $f = 150/50 = 3\\ \\text{Hz}$. Kesalahan umum: tertukar dengan periode $T = t/n = 1/3\\ \\text{s}$ — frekuensi adalah kebalikan periode, $f = 1/T$." },
  { q: "Sebuah getaran harmonik memiliki kecepatan sudut $\\omega = 4\\pi\\ \\text{rad/s}$. Frekuensi getarannya adalah ...", options: ["$2\\ \\text{Hz}$", "$4\\pi\\ \\text{Hz}$", "$8\\pi\\ \\text{Hz}$", "$0{,}5\\ \\text{Hz}$"], answer: 0, solution: "1. Hubungan kecepatan sudut dan frekuensi: $\\omega = 2\\pi f$. 2. $f = \\omega/(2\\pi) = 4\\pi/(2\\pi) = 2\\ \\text{Hz}$. Kesalahan umum: menganggap $\\omega$ sama dengan $f$ — $\\omega$ satuannya rad/s dan nilainya selalu $2\\pi$ kali frekuensi." },
  { q: "Periode suatu getaran diperbesar menjadi $4$ kali semula. Frekuensi getaran tersebut menjadi ...", options: ["tetap", "menjadi $4$ kali semula", "menjadi $\\frac{1}{4}$ kali semula", "menjadi $2$ kali semula"], answer: 2, solution: "1. Frekuensi dan periode berbanding terbalik: $f = 1/T$. 2. Jika $T' = 4T$, maka $f' = 1/(4T) = f/4$ — frekuensi menjadi seperempat semula. Kesalahan umum: mengira frekuensi ikut membesar $4$ kali; ingat $T$ besar artinya getaran lambat sehingga $f$ kecil." },
  { q: "Sebuah garputala bergetar dengan periode $0{,}02\\ \\text{s}$. Frekuensi bunyi yang dihasilkannya adalah ...", options: ["$20\\ \\text{Hz}$", "$0{,}02\\ \\text{Hz}$", "$0{,}5\\ \\text{Hz}$", "$50\\ \\text{Hz}$"], answer: 3, solution: "1. $f = 1/T = 1/0{,}02$. 2. $1/0{,}02 = 50\\ \\text{Hz}$ (garputala ini berbunyi rendah; garputala nada standar $440\\ \\text{Hz}$ berarti periodenya $1/440\\ \\text{s}$). Kesalahan umum: menuliskan $f = 0{,}02\\ \\text{Hz}$ — itu nilai periodenya, bukan frekuensinya." },
  // --- gelombang transversal/longitudinal & cepat rambat (4) ---
  { q: "Pada gelombang transversal, arah getaran partikel medium terhadap arah rambat gelombang adalah ...", options: ["sejajar", "tegak lurus", "berlawanan arah", "acak"], answer: 1, solution: "1. Definisi: pada gelombang transversal arah getar partikel tegak lurus arah rambat (contoh: gelombang pada tali). 2. Lawannya adalah gelombang longitudinal: arah getar sejajar arah rambat (contoh: gelombang bunyi di udara yang berupa rapatan-renggangan). Kesalahan umum: mengira gelombang bunyi itu transversal — bunyi adalah rapatan dan renggangan medium sehingga tergolong longitudinal." },
  { q: "Seutas tali ditegangkan dengan gaya $100\\ \\text{N}$. Jika massa per satuan panjang tali $0{,}04\\ \\text{kg/m}$, cepat rambat gelombang pada tali adalah ...", options: ["$50\\ \\text{m/s}$", "$25\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$2500\\ \\text{m/s}$"], answer: 0, solution: "1. Cepat rambat pada dawai: $v = \\sqrt{F/\\mu}$. 2. $v = \\sqrt{100/0{,}04} = \\sqrt{2500} = 50\\ \\text{m/s}$ (tali makin tegang dan ringan → gelombang makin cepat). Kesalahan umum: lupa mengakarkuadratkan sehingga mendapat $2500\\ \\text{m/s}$." },
  { q: "Sebuah gelombang merambat dengan panjang gelombang $4\\ \\text{m}$ dan periode $0{,}5\\ \\text{s}$. Cepat rambat gelombang tersebut adalah ...", options: ["$2\\ \\text{m/s}$", "$0{,}5\\ \\text{m/s}$", "$8\\ \\text{m/s}$", "$16\\ \\text{m/s}$"], answer: 2, solution: "1. $v = \\lambda/T$ (satu panjang gelombang ditempuh dalam satu periode). 2. $v = 4/0{,}5 = 8\\ \\text{m/s}$. Kesalahan umum: memakai $v = \\lambda\\cdot T = 2\\ \\text{m/s}$ — ingat $v = \\lambda f = \\lambda/T$, periode membagi bukan mengali." },
  { q: "Gelombang merambat pada suatu medium dengan kelajuan $200\\ \\text{m/s}$ dan frekuensi $50\\ \\text{Hz}$. Panjang gelombangnya adalah ...", options: ["$2{,}5\\ \\text{m}$", "$10000\\ \\text{m}$", "$0{,}25\\ \\text{m}$", "$4\\ \\text{m}$"], answer: 3, solution: "1. $v = \\lambda f \\Rightarrow \\lambda = v/f$. 2. $\\lambda = 200/50 = 4\\ \\text{m}$. Kesalahan umum: membalik menjadi $\\lambda = f/v = 0{,}25\\ \\text{m}$ — cek satuan: $(\\text{m/s})/\\text{Hz} = \\text{m}$, sudah benar." },
  // --- gelombang bunyi & efek Doppler (2) ---
  { q: "Sebuah mobil membunyikan klakson berfrekuensi $600\\ \\text{Hz}$ sambil menjauhi pengamat yang diam dengan kelajuan $60\\ \\text{m/s}$. Jika cepat rambat bunyi $340\\ \\text{m/s}$, frekuensi yang didengar pengamat adalah ...", options: ["$600\\ \\text{Hz}$", "$510\\ \\text{Hz}$", "$705\\ \\text{Hz}$", "$690\\ \\text{Hz}$"], answer: 1, solution: "1. Efek Doppler untuk sumber menjauhi pengamat diam: $f_p = \\frac{v}{v + v_s}f_s$. 2. $f_p = \\frac{340}{340 + 60}\\times 600 = \\frac{340}{400}\\times 600 = 0{,}85 \\times 600 = 510\\ \\text{Hz}$ (lebih rendah — nada terdengar menurun). Kesalahan umum: memakai tanda minus di penyebut (rumus untuk sumber mendekati) sehingga mendapat frekuensi yang malah naik." },
  { q: "Senar gitar sepanjang $0{,}6\\ \\text{m}$ dengan kedua ujung terikat merambatkan gelombang berkecepatan $300\\ \\text{m/s}$. Frekuensi nada dasar senar tersebut adalah ...", options: ["$250\\ \\text{Hz}$", "$500\\ \\text{Hz}$", "$125\\ \\text{Hz}$", "$1000\\ \\text{Hz}$"], answer: 0, solution: "1. Nada dasar dawai terikat: $L = \\lambda/2 \\Rightarrow \\lambda = 2L = 1{,}2\\ \\text{m}$. 2. $f_1 = v/\\lambda = 300/1{,}2 = 250\\ \\text{Hz}$. Kesalahan umum: memakai $f = v/L = 500\\ \\text{Hz}$ — itu frekuensi harmonik kedua; nada dasar dawai selalu setengah panjang gelombang." },
  // --- gelombang EM & spektrum (2) ---
  { q: "Di antara gelombang elektromagnetik berikut, yang memiliki frekuensi paling tinggi adalah ...", options: ["cahaya tampak", "sinar ultraviolet", "sinar-X", "sinar gamma"], answer: 3, solution: "1. Urutan spektrum EM dari frekuensi rendah ke tinggi: gelombang radio $\\rightarrow$ mikro $\\rightarrow$ inframerah $\\rightarrow$ cahaya tampak $\\rightarrow$ ultraviolet $\\rightarrow$ sinar-X $\\rightarrow$ sinar gamma. 2. Jadi frekuensi tertinggi adalah sinar gamma (panjang gelombang terpendek, energi foton terbesar). Kesalahan umum: mengira cahaya tampak yang tertinggi karena bisa dilihat — mata manusia hanya peka pada pita sempit di tengah spektrum." },
  { q: "Stasiun radio FM memancarkan gelombang berfrekuensi $100\\ \\text{MHz}$. Jika $c = 3\\times10^8\\ \\text{m/s}$, panjang gelombang siarannya adalah ...", options: ["$300\\ \\text{m}$", "$0{,}3\\ \\text{m}$", "$3\\ \\text{m}$", "$3\\times10^{16}\\ \\text{m}$"], answer: 2, solution: "1. $\\lambda = c/f$; ubah dahulu $100\\ \\text{MHz} = 100\\times10^6 = 10^8\\ \\text{Hz}$. 2. $\\lambda = (3\\times10^8)/10^8 = 3\\ \\text{m}$ (pita VHF memang berpanjang gelombang orde meter). Kesalahan umum: lupa mengubah MHz ke Hz sehingga mendapat $3\\times10^6\\ \\text{m}$." },
  // ===== FLUIDA STATIS & DINAMIS (17) =====
  // --- tekanan & tekanan hidrostatis (4) ---
  { q: "Seorang penyelam berada $10\\ \\text{m}$ di bawah permukaan danau ($\\rho_{air} = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$, tekanan udara luar $1\\times10^5\\ \\text{Pa}$). Tekanan total yang dialami penyelam adalah ...", options: ["$2\\times10^5\\ \\text{Pa}$", "$1\\times10^5\\ \\text{Pa}$", "$1\\times10^6\\ \\text{Pa}$", "$1\\times10^4\\ \\text{Pa}$"], answer: 0, solution: "1. Tekanan total = tekanan atmosfer + tekanan hidrostatis: $P = P_0 + \\rho g h$. 2. $\\rho g h = 1000\\cdot10\\cdot10 = 10^5\\ \\text{Pa}$, jadi $P = 10^5 + 10^5 = 2\\times10^5\\ \\text{Pa}$. Kesalahan umum: hanya menghitung $\\rho g h$ (tekanan gauge) dan lupa menambahkan tekanan udara $P_0$ di permukaan." },
  { q: "Sebuah paku ditekan dengan gaya $50\\ \\text{N}$. Jika luas ujung paku $1\\ \\text{mm}^2$, tekanan pada ujung paku adalah ...", options: ["$5\\times10^6\\ \\text{Pa}$", "$5\\times10^7\\ \\text{Pa}$", "$50\\ \\text{Pa}$", "$5\\times10^{-7}\\ \\text{Pa}$"], answer: 1, solution: "1. $P = F/A$; ubah dahulu $1\\ \\text{mm}^2 = 10^{-6}\\ \\text{m}^2$. 2. $P = 50/10^{-6} = 5\\times10^7\\ \\text{Pa}$ (inilah alasan paku yang runcing mudah menancap: luas kecil menghasilkan tekanan besar). Kesalahan umum: memakai $A = 1\\ \\text{m}^2$ tanpa konversi satuan sehingga mendapat $50\\ \\text{Pa}$." },
  { q: "Tekanan hidrostatis pada kedalaman $2\\ \\text{m}$ dibandingkan dengan tekanan pada kedalaman $5\\ \\text{m}$ (dalam fluida yang sama) berbanding ...", options: ["$5 : 2$", "$4 : 25$", "$2 : 5$", "$1 : 1$"], answer: 2, solution: "1. $P = \\rho g h$, jadi pada fluida yang sama $P$ sebanding lurus dengan $h$. 2. $P_1 : P_2 = h_1 : h_2 = 2 : 5$. Kesalahan umum: mengira tekanan bergantung pada volume atau bentuk wadah — tekanan hidrostatis hanya bergantung pada kedalaman dan massa jenis fluida." },
  { q: "Tekanan hidrostatis di dasar bendungan pada kedalaman $6\\ \\text{m}$ ($\\rho_{air} = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$) adalah ...", options: ["$6000\\ \\text{Pa}$", "$600000\\ \\text{Pa}$", "$600\\ \\text{Pa}$", "$60000\\ \\text{Pa}$"], answer: 3, solution: "1. $P = \\rho g h = 1000\\cdot10\\cdot6$. 2. $P = 60000\\ \\text{Pa} = 60\\ \\text{kPa}$ (inilah alasan dinding bendungan dibuat makin tebal ke arah bawah). Kesalahan umum: salah menempatkan nol ($6000$ atau $600000\\ \\text{Pa}$) karena tidak teliti mengalikan $1000\\times10\\times6$." },
  // --- hukum Pascal (3) ---
  { q: "Dongkrak hidrolik memiliki pengisap kecil $0{,}02\\ \\text{m}^2$ dan pengisap besar $0{,}5\\ \\text{m}^2$. Gaya $100\\ \\text{N}$ pada pengisap kecil menghasilkan gaya pada pengisap besar sebesar ...", options: ["$4\\ \\text{N}$", "$2500\\ \\text{N}$", "$250\\ \\text{N}$", "$25000\\ \\text{N}$"], answer: 1, solution: "1. Hukum Pascal: $P_1 = P_2 \\Rightarrow F_1/A_1 = F_2/A_2$. 2. $F_2 = F_1\\cdot A_2/A_1 = 100\\cdot(0{,}5/0{,}02) = 100\\cdot25 = 2500\\ \\text{N}$ (gaya dilipatgandakan $25$ kali). Kesalahan umum: membalik perbandingan menjadi $F_2 = F_1\\cdot A_1/A_2 = 4\\ \\text{N}$ — gaya besar justru dihasilkan di penampang yang besar." },
  { q: "Pada mesin hidrolik, luas penampang kecil $5\\ \\text{cm}^2$ dan luas penampang besar $200\\ \\text{cm}^2$. Untuk mengangkat beban $800\\ \\text{N}$ pada penampang besar, gaya yang harus diberikan pada penampang kecil adalah ...", options: ["$20\\ \\text{N}$", "$0{,}5\\ \\text{N}$", "$800\\ \\text{N}$", "$8000\\ \\text{N}$"], answer: 0, solution: "1. $F_1/A_1 = F_2/A_2 \\Rightarrow F_1 = F_2\\cdot A_1/A_2$. 2. $F_1 = 800\\cdot(5/200) = 800/40 = 20\\ \\text{N}$ — beban $800\\ \\text{N}$ terangkat hanya dengan gaya $20\\ \\text{N}$. Kesalahan umum: lupa bahwa keuntungan gaya $= A_2/A_1$, bukan $A_1/A_2$." },
  { q: "Pengisap kecil dongkrak hidrolik berluas $10\\ \\text{cm}^2$ ditekan turun sejauh $20\\ \\text{cm}$. Jika luas pengisap besar $50\\ \\text{cm}^2$, pengisap besar naik sejauh ...", options: ["$100\\ \\text{cm}$", "$20\\ \\text{cm}$", "$4\\ \\text{cm}$", "$0{,}4\\ \\text{cm}$"], answer: 2, solution: "1. Volume fluida tak termampatkan kekal: $A_1 x_1 = A_2 x_2$. 2. $x_2 = (10\\cdot20)/50 = 200/50 = 4\\ \\text{cm}$ (gaya yang besar dibayar dengan perpindahan yang kecil — sesuai kekekalan usaha). Kesalahan umum: mengira kedua pengisap berpindah sama jauh ($20\\ \\text{cm}$) atau memakai perbandingan gaya untuk perpindahan." },
  // --- Archimedes & tenggelam/terapung (5) ---
  { q: "Sebuah kapal bermassa $5000\\ \\text{ton}$ terapung tenang di laut. Besar gaya apung yang dialami kapal ($g = 10\\ \\text{m/s}^2$) adalah ...", options: ["$5\\times10^6\\ \\text{N}$", "$5\\times10^8\\ \\text{N}$", "$0\\ \\text{N}$", "$5\\times10^7\\ \\text{N}$"], answer: 3, solution: "1. Benda terapung setimbang: $F_A = W$. 2. $W = m g = (5\\times10^6\\ \\text{kg})(10\\ \\text{m/s}^2) = 5\\times10^7\\ \\text{N}$, jadi $F_A = 5\\times10^7\\ \\text{N}$ (sama dengan berat air laut yang dipindahkan badan kapal). Kesalahan umum: menjawab $5\\times10^6\\ \\text{N}$ (itu massa dalam kg, lupa dikali $g$) atau mengira gaya apung hanya bekerja pada benda yang tenggelam." },
  { q: "Sebuah benda padat bermassa jenis $1200\\ \\text{kg/m}^3$ dicelupkan ke dalam air ($\\rho = 1000\\ \\text{kg/m}^3$) lalu dilepas. Benda tersebut akan ...", options: ["tenggelam", "terapung", "melayang", "naik ke permukaan lalu terapung"], answer: 0, solution: "1. Bandingkan massa jenis: $\\rho_{benda} = 1200 > \\rho_{air} = 1000\\ \\text{kg/m}^3$. 2. Karena lebih besar, berat benda melebihi gaya apung maksimum sehingga benda tenggelam ke dasar. Kesalahan umum: mengira semua benda padat tenggelam atau semua mengapung — yang menentukan adalah perbandingan massa jenis benda dan fluida, bukan wujud bendanya." },
  { q: "Balok kayu bermassa jenis $600\\ \\text{kg/m}^3$ mengapung di air ($\\rho = 1000\\ \\text{kg/m}^3$). Persentase volume balok yang tercelup adalah ...", options: ["$40\\%$", "$60\\%$", "$100\\%$", "$6\\%$"], answer: 1, solution: "1. Terapung setimbang: $F_A = W \\Rightarrow \\rho_f V_{celup} g = \\rho_b V g$. 2. $V_{celup}/V = \\rho_b/\\rho_f = 600/1000 = 0{,}6 = 60\\%$. Kesalahan umum: memakai $\\rho_f/\\rho_b$ sehingga mendapat lebih dari $100\\%$ (tak mungkin) atau mengira benda terapung selalu tercelup seluruhnya." },
  { q: "Sebuah benda beratnya $30\\ \\text{N}$ di udara dan $22\\ \\text{N}$ saat tercelup seluruhnya di dalam air. Besar gaya apung yang dialami benda adalah ...", options: ["$52\\ \\text{N}$", "$22\\ \\text{N}$", "$8\\ \\text{N}$", "$30\\ \\text{N}$"], answer: 2, solution: "1. Berat semu memenuhi $W' = W - F_A$. 2. $F_A = W - W' = 30 - 22 = 8\\ \\text{N}$ (sama dengan berat air yang dipindahkan benda). Kesalahan umum: menjumlahkan $30 + 22 = 52\\ \\text{N}$ — gaya apung justru mengurangi berat terukur, bukan menambah." },
  { q: "Balok bervolume $0{,}01\\ \\text{m}^3$ tercelup $3/4$ bagiannya dalam air ($\\rho = 1000\\ \\text{kg/m}^3$, $g = 10\\ \\text{m/s}^2$). Gaya apung yang dialami balok adalah ...", options: ["$75\\ \\text{N}$", "$100\\ \\text{N}$", "$25\\ \\text{N}$", "$7{,}5\\ \\text{N}$"], answer: 0, solution: "1. $F_A = \\rho_f g V_{celup}$ — hanya volume yang tercelup yang dihitung. 2. $V_{celup} = \\frac{3}{4}\\cdot0{,}01 = 0{,}0075\\ \\text{m}^3$; $F_A = 1000\\cdot10\\cdot0{,}0075 = 75\\ \\text{N}$. Kesalahan umum: memakai seluruh volume balok sehingga mendapat $100\\ \\text{N}$ — gaya apung sama dengan berat fluida yang dipindahkan, bukan berat bendanya." },
  // --- persamaan kontinuitas & Bernoulli (5) ---
  { q: "Air mengalir dalam pipa berdiameter $4\\ \\text{cm}$ dengan kelajuan $1\\ \\text{m/s}$, lalu masuk ke pipa berdiameter $2\\ \\text{cm}$. Kelajuan air di pipa yang kecil adalah ...", options: ["$2\\ \\text{m/s}$", "$1\\ \\text{m/s}$", "$0{,}25\\ \\text{m/s}$", "$4\\ \\text{m/s}$"], answer: 3, solution: "1. Persamaan kontinuitas: $A_1 v_1 = A_2 v_2$ dengan $A$ sebanding $D^2$. 2. $v_2 = v_1(D_1/D_2)^2 = 1\\cdot(4/2)^2 = 4\\ \\text{m/s}$. Kesalahan umum: memakai perbandingan diameter secara linear ($2\\ \\text{m/s}$) — luas penampang sebanding dengan kuadrat diameter." },
  { q: "Sebuah bak berkapasitas $200\\ \\text{L}$ terisi penuh oleh sebuah keran dalam waktu $50\\ \\text{s}$. Debit aliran keran tersebut adalah ...", options: ["$10000\\ \\text{L/s}$", "$4\\ \\text{L/s}$", "$0{,}25\\ \\text{L/s}$", "$250\\ \\text{L/s}$"], answer: 1, solution: "1. Debit $Q = V/t$. 2. $Q = 200/50 = 4\\ \\text{L/s}$ ($= 4\\times10^{-3}\\ \\text{m}^3/\\text{s}$). Kesalahan umum: mengalikan $200\\times50$ — debit adalah volume per satuan waktu, jadi volume dibagi waktu." },
  { q: "Dinding tangki air yang terbuka bocor $5\\ \\text{m}$ di bawah permukaan air ($g = 10\\ \\text{m/s}^2$). Kelajuan air yang menyembur keluar dari kebocoran adalah ...", options: ["$10\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$25\\ \\text{m/s}$", "$100\\ \\text{m/s}$"], answer: 0, solution: "1. Teorema Torricelli: $v = \\sqrt{2gh}$. 2. $v = \\sqrt{2\\cdot10\\cdot5} = \\sqrt{100} = 10\\ \\text{m/s}$ (sama dengan kelajuan jatuh bebas dari ketinggian $h$). Kesalahan umum: memakai $v = gh$ atau lupa mengakarkuadratkan." },
  { q: "Udara ($\\rho = 1{,}2\\ \\text{kg/m}^3$) mengalir di atas sayap pesawat dengan kelajuan $80\\ \\text{m/s}$ dan di bawah sayap $70\\ \\text{m/s}$. Selisih tekanan (bawah dikurangi atas) yang menghasilkan gaya angkat adalah ...", options: ["$900\\ \\text{Pa}$", "$1500\\ \\text{Pa}$", "$180\\ \\text{Pa}$", "$9000\\ \\text{Pa}$"], answer: 0, solution: "1. Bernoulli: $P_{bawah} + \\frac{1}{2}\\rho v_{bawah}^2 = P_{atas} + \\frac{1}{2}\\rho v_{atas}^2$. 2. $\\Delta P = P_{bawah} - P_{atas} = \\frac{1}{2}\\rho(v_{atas}^2 - v_{bawah}^2) = \\frac{1}{2}\\cdot1{,}2\\cdot(80^2 - 70^2) = 0{,}6\\cdot(6400 - 4900) = 0{,}6\\cdot1500 = 900\\ \\text{Pa}$. Kesalahan umum: mengira tekanan lebih besar di sisi yang alirannya cepat — justru sebaliknya: aliran cepat → tekanan rendah, itulah yang mengangkat sayap." },
  { q: "Air ($\\rho = 1000\\ \\text{kg/m}^3$) mengalir ke atas melalui pipa vertikal. Di titik bawah tekanannya $30000\\ \\text{Pa}$ dan kelajuannya $1\\ \\text{m/s}$; di titik $2\\ \\text{m}$ lebih tinggi kelajuannya $3\\ \\text{m/s}$ ($g = 10\\ \\text{m/s}^2$). Tekanan di titik atas adalah ...", options: ["$46000\\ \\text{Pa}$", "$30000\\ \\text{Pa}$", "$10000\\ \\text{Pa}$", "$6000\\ \\text{Pa}$"], answer: 3, solution: "1. Bernoulli lengkap: $P_1 + \\frac{1}{2}\\rho v_1^2 + \\rho g h_1 = P_2 + \\frac{1}{2}\\rho v_2^2 + \\rho g h_2$. 2. $P_2 = 30000 + 500\\cdot(1 - 9) + 1000\\cdot10\\cdot(-2) = 30000 - 4000 - 20000 = 6000\\ \\text{Pa}$. Kesalahan umum: mengabaikan suku ketinggian $\\rho g\\Delta h$ — makin tinggi posisinya, tekanan makin turun meskipun kelajuan berubah." },
{ q: "Sebuah termometer X menetapkan titik beku air pada $20^\\circ\\text{X}$ dan titik didih air pada $120^\\circ\\text{X}$. Suhu $50^\\circ\\text{C}$ setara dengan ... pada termometer X.", options: ["$70^\\circ\\text{X}$", "$50^\\circ\\text{X}$", "$80^\\circ\\text{X}$", "$60^\\circ\\text{X}$"], answer: 0, solution: "1. Perbandingan interval dua skala suhu bersifat linier: $\\frac{C - C_{beku}}{C_{didih} - C_{beku}} = \\frac{X - X_{beku}}{X_{didih} - X_{beku}}$. 2. Substitusi: $\\frac{50 - 0}{100 - 0} = \\frac{X - 20}{120 - 20} \\Rightarrow \\frac{1}{2} = \\frac{X - 20}{100} \\Rightarrow X - 20 = 50 \\Rightarrow X = 70^\\circ\\text{X}$. 3. Kesalahan umum: menjawab $50^\\circ\\text{X}$ — angka suhu hanya sama jika titik nol dan besar skalanya sama, padahal termometer X bergeser $20^\\circ$ dari Celsius." },
    { q: "Sebatang logam sepanjang $2\\ \\text{m}$ pada suhu $20^\\circ\\text{C}$ dipanaskan hingga $120^\\circ\\text{C}$. Jika koefisien muai panjang logam $\\alpha = 12\\times10^{-6}/^\\circ\\text{C}$, pertambahan panjang batang adalah ...", options: ["$2{,}4\\ \\text{cm}$", "$2{,}4\\ \\text{mm}$", "$24\\ \\text{mm}$", "$0{,}24\\ \\text{mm}$"], answer: 1, solution: "1. Muai panjang: $\\Delta L = L_0\\alpha\\Delta T$. 2. $\\Delta T = 120 - 20 = 100^\\circ\\text{C}$, maka $\\Delta L = 2\\cdot12\\times10^{-6}\\cdot100 = 2400\\times10^{-6} = 2{,}4\\times10^{-3}\\ \\text{m} = 2{,}4\\ \\text{mm}$. 3. Kesalahan umum: lupa mengubah meter ke milimeter sehingga menjawab $2{,}4\\ \\text{cm}$ — padahal $10^{-3}\\ \\text{m} = 1\\ \\text{mm}$, bukan $1\\ \\text{cm}$." },
    { q: "Keping bimetal terdiri dari aluminium ($\\alpha = 24\\times10^{-6}/^\\circ\\text{C}$) dan besi ($\\alpha = 12\\times10^{-6}/^\\circ\\text{C}$) yang dikeling menjadi satu. Jika keping dipanaskan, yang terjadi adalah ...", options: ["keping tetap lurus", "keping melengkung ke arah aluminium", "keping melengkung ke arah besi", "keping menyusut memendek"], answer: 2, solution: "1. Aluminium memiliki $\\alpha$ dua kali besi, sehingga saat dipanaskan aluminium memuai lebih panjang daripada besi. 2. Karena keduanya terikat, keping terpaksa melengkung dengan sisi aluminium di luar (lebih panjang) dan sisi besi di dalam — jadi melengkung ke arah besi. 3. Miskonsepsi umum: mengira keping melengkung ke arah logam yang lebih memuai, padahal sisi yang lebih panjang justru menjadi sisi luar lengkungan." },
    { q: "Es bermassa $0{,}5\\ \\text{kg}$ pada suhu $0^\\circ\\text{C}$ dilebur seluruhnya menjadi air $0^\\circ\\text{C}$. Jika kalor lebur es $L = 3{,}36\\times10^5\\ \\text{J/kg}$, kalor yang diperlukan adalah ...", options: ["$336.000\\ \\text{J}$", "$84.000\\ \\text{J}$", "$16.800\\ \\text{J}$", "$168.000\\ \\text{J}$"], answer: 3, solution: "1. Kalor peleburan: $Q = mL$. 2. $Q = 0{,}5\\cdot3{,}36\\times10^5 = 1{,}68\\times10^5\\ \\text{J} = 168.000\\ \\text{J}$. 3. Kesalahan umum: memakai $m = 1\\ \\text{kg}$ sehingga mendapat $336.000\\ \\text{J}$ — massa harus ikut dikalikan, bukan diabaikan." },
    { q: "Air panas $0{,}4\\ \\text{kg}$ bersuhu $80^\\circ\\text{C}$ dicampur dengan air dingin $0{,}6\\ \\text{kg}$ bersuhu $20^\\circ\\text{C}$ dalam wadah terisolasi. Suhu campuran setelah setimbang adalah ...", options: ["$44^\\circ\\text{C}$", "$50^\\circ\\text{C}$", "$56^\\circ\\text{C}$", "$40^\\circ\\text{C}$"], answer: 0, solution: "1. Asas Black: kalor yang dilepas air panas = kalor yang diserap air dingin, $m_1c(T_1 - T_c) = m_2c(T_c - T_2)$. 2. Kalor jenis $c$ saling meniadakan: $0{,}4(80 - T_c) = 0{,}6(T_c - 20) \\Rightarrow 32 - 0{,}4T_c = 0{,}6T_c - 12 \\Rightarrow 44 = T_c$, jadi $T_c = 44^\\circ\\text{C}$ — lebih dekat ke suhu air dingin karena massanya lebih besar. 3. Kesalahan umum: mengambil rata-rata biasa $50^\\circ\\text{C}$ — suhu setimbang adalah rata-rata berbobot massa, bukan rata-rata aritmetik." },
    { q: "Sebuah benda bermassa $0{,}5\\ \\text{kg}$ memiliki kalor jenis $400\\ \\text{J/(kg}\\cdot^\\circ\\text{C)}$. Kapasitas kalor benda tersebut adalah ...", options: ["$400\\ \\text{J}/^\\circ\\text{C}$", "$200\\ \\text{J}/^\\circ\\text{C}$", "$800\\ \\text{J}/^\\circ\\text{C}$", "$2000\\ \\text{J}/^\\circ\\text{C}$"], answer: 1, solution: "1. Kapasitas kalor $C = m\\cdot c$ — kalor yang dibutuhkan untuk menaikkan suhu seluruh benda sebesar $1^\\circ\\text{C}$. 2. $C = 0{,}5\\cdot400 = 200\\ \\text{J}/^\\circ\\text{C}$. 3. Kesalahan umum: menjawab $400\\ \\text{J}/^\\circ\\text{C}$ — itu kalor jenis (per satuan massa), sedangkan kapasitas kalor sudah mencakup massa benda; keduanya tertukar." },
    { q: "Es $0{,}2\\ \\text{kg}$ pada $0^\\circ\\text{C}$ dilebur seluruhnya, lalu air hasil leburannya dipanaskan hingga $50^\\circ\\text{C}$ ($L_{es} = 3{,}36\\times10^5\\ \\text{J/kg}$, $c_{air} = 4200\\ \\text{J/(kg}\\cdot^\\circ\\text{C)}$). Total kalor yang dibutuhkan adalah ...", options: ["$67{,}2\\ \\text{kJ}$", "$42\\ \\text{kJ}$", "$109{,}2\\ \\text{kJ}$", "$10{,}92\\ \\text{kJ}$"], answer: 2, solution: "1. Dua tahap: peleburan $Q_1 = mL = 0{,}2\\cdot3{,}36\\times10^5 = 67.200\\ \\text{J}$, lalu pemanasan $Q_2 = mc\\Delta T = 0{,}2\\cdot4200\\cdot50 = 42.000\\ \\text{J}$. 2. Total $Q = Q_1 + Q_2 = 67.200 + 42.000 = 109.200\\ \\text{J} = 109{,}2\\ \\text{kJ}$. 3. Kesalahan umum: hanya menghitung salah satu tahap — kalor total adalah jumlah kalor laten (perubahan wujud) dan kalor sensibel (perubahan suhu)." },
    { q: "Sejumlah gas ideal berekspansi secara isotermik dan menyerap kalor $600\\ \\text{J}$ dari lingkungan. Perubahan energi dalam gas tersebut adalah ...", options: ["$0\\ \\text{J}$", "$600\\ \\text{J}$", "$-600\\ \\text{J}$", "$300\\ \\text{J}$"], answer: 0, solution: "1. Energi dalam gas ideal hanya bergantung pada suhu: $\\Delta U \\propto \\Delta T$. 2. Proses isotermik berarti suhu tetap ($\\Delta T = 0$), sehingga $\\Delta U = 0$ — seluruh $600\\ \\text{J}$ kalor berubah menjadi usaha pemuaian gas ($W = Q$). 3. Kesalahan umum: memakai $\\Delta U = Q - W$ dengan $W = 0$ — pada pemuaian isotermik gas justru melakukan usaha, bukan nol." },
    { q: "Gas dimampatkan secara adiabatik dan usaha sebesar $400\\ \\text{J}$ dilakukan pada gas oleh lingkungan. Perubahan energi dalam gas adalah ...", options: ["$-400\\ \\text{J}$", "$0\\ \\text{J}$", "$800\\ \\text{J}$", "$400\\ \\text{J}$"], answer: 3, solution: "1. Adiabatik: $Q = 0$. Konvensi fisika: $W$ positif jika sistem melakukan usaha, jadi usaha pada gas berarti $W = -400\\ \\text{J}$. 2. Hukum I: $\\Delta U = Q - W = 0 - (-400) = 400\\ \\text{J}$ — energi dalam (dan suhu) gas naik. 3. Kesalahan umum: salah tanda sehingga mendapat $-400\\ \\text{J}$ — ingat, memampatkan gas menambah energi dalamnya, bukan mengurangi." },
    { q: "Gas berekspansi pada tekanan tetap $2\\times10^5\\ \\text{Pa}$ dari volume $0{,}01\\ \\text{m}^3$ menjadi $0{,}03\\ \\text{m}^3$ sambil menyerap kalor $7000\\ \\text{J}$. Perubahan energi dalam gas adalah ...", options: ["$7000\\ \\text{J}$", "$3000\\ \\text{J}$", "$11.000\\ \\text{J}$", "$-3000\\ \\text{J}$"], answer: 1, solution: "1. Usaha pada tekanan tetap: $W = P\\Delta V = 2\\times10^5\\cdot(0{,}03 - 0{,}01) = 2\\times10^5\\cdot0{,}02 = 4000\\ \\text{J}$. 2. Hukum I: $\\Delta U = Q - W = 7000 - 4000 = 3000\\ \\text{J}$ — sebagian kalor dipakai untuk usaha pemuaian, sisanya menaikkan energi dalam. 3. Kesalahan umum: menjawab $7000\\ \\text{J}$ — lupa bahwa tidak semua kalor menjadi energi dalam karena gas melakukan usaha." },
    { q: "Sebuah mesin Carnot bekerja di antara reservoir panas $327^\\circ\\text{C}$ dan reservoir dingin $27^\\circ\\text{C}$. Efisiensi maksimum mesin tersebut adalah ...", options: ["$91{,}7\\%$", "$8{,}3\\%$", "$50\\%$", "$25\\%$"], answer: 2, solution: "1. Suhu mutlak: $T_1 = 327 + 273 = 600\\ \\text{K}$, $T_2 = 27 + 273 = 300\\ \\text{K}$. 2. Efisiensi Carnot $\\eta = 1 - \\frac{T_2}{T_1} = 1 - \\frac{300}{600} = 0{,}5 = 50\\%$. 3. Kesalahan umum: memakai Celsius langsung, $1 - 27/327 \\approx 91{,}7\\%$ — rumus Carnot hanya berlaku untuk suhu mutlak (kelvin)." },
    { q: "Mesin Carnot menyerap kalor $1000\\ \\text{J}$ dari reservoir panas dan memiliki efisiensi $25\\%$. Usaha yang dihasilkan mesin dalam satu siklus adalah ...", options: ["$250\\ \\text{J}$", "$750\\ \\text{J}$", "$4000\\ \\text{J}$", "$1000\\ \\text{J}$"], answer: 0, solution: "1. Efisiensi $\\eta = \\frac{W}{Q_1}$, dengan $Q_1$ kalor yang diserap dari reservoir panas. 2. $W = \\eta Q_1 = 0{,}25\\cdot1000 = 250\\ \\text{J}$; sisanya $750\\ \\text{J}$ dibuang ke reservoir dingin. 3. Kesalahan umum: menjawab $750\\ \\text{J}$ — itu kalor yang dibuang ($Q_2$), bukan usaha yang dihasilkan." },
    { q: "Dua muatan titik $q_1 = 2\\ \\mu\\text{C}$ dan $q_2 = 3\\ \\mu\\text{C}$ terpisah sejauh $0{,}1\\ \\text{m}$ di udara ($k = 9\\times10^9\\ \\text{N}\\cdot\\text{m}^2/\\text{C}^2$). Besar gaya Coulomb antara keduanya adalah ...", options: ["$0{,}54\\ \\text{N}$", "$5{,}4\\ \\text{N}$", "$54\\ \\text{N}$", "$0{,}054\\ \\text{N}$"], answer: 1, solution: "1. Hukum Coulomb: $F = k\\frac{q_1 q_2}{r^2}$. 2. $F = 9\\times10^9\\cdot\\frac{(2\\times10^{-6})(3\\times10^{-6})}{(0{,}1)^2} = \\frac{54\\times10^{-3}}{10^{-2}} = 5{,}4\\ \\text{N}$ (tolak-menolak karena sejenis). 3. Kesalahan umum: lupa menguadratkan $r$ sehingga membagi dengan $0{,}1$ saja dan mendapat $0{,}54\\ \\text{N}$." },
    { q: "Jarak antara dua muatan titik dijadikan dua kali semula, sedangkan kedua muatannya tetap. Besar gaya Coulomb yang baru menjadi ...", options: ["setengah kali semula", "dua kali semula", "tetap sama", "seperempat kali semula"], answer: 3, solution: "1. Dari $F = k\\frac{q_1 q_2}{r^2}$, gaya berbanding terbalik dengan kuadrat jarak. 2. Jika $r' = 2r$, maka $F' = \\frac{F}{(2)^2} = \\frac{F}{4}$ — seperempat kali semula. 3. Kesalahan umum: mengira gaya menjadi setengah — hubungan kuadrat berarti penggandaan jarak melipat-empatkan penurunan gaya." },
    { q: "Muatan A ($4\\ \\mu\\text{C}$) dan muatan B ($1\\ \\mu\\text{C}$) saling berinteraksi. Perbandingan besar gaya Coulomb yang dialami A oleh B terhadap gaya yang dialami B oleh A adalah ...", options: ["sama besar", "gaya pada A 4 kali gaya pada B", "gaya pada A seperempat gaya pada B", "gaya pada A 16 kali gaya pada B"], answer: 0, solution: "1. Gaya Coulomb adalah pasangan aksi-reaksi (Hukum III Newton): kedua muatan saling mengerjakan gaya yang sama besar dan berlawanan arah. 2. Besar muatan memengaruhi besar gaya totalnya, tetapi gaya pada A dan gaya pada B selalu sama besar — perbandingannya $1:1$. 3. Miskonsepsi umum: mengira muatan yang lebih besar mengalami gaya lebih besar — yang benar, keduanya merasakan gaya yang identik besarnya." },
    { q: "Sebuah muatan uji $2\\ \\mu\\text{C}$ mengalami gaya listrik $0{,}06\\ \\text{N}$ di suatu titik. Kuat medan listrik di titik tersebut adalah ...", options: ["$1{,}2\\times10^{-7}\\ \\text{N/C}$", "$0{,}03\\ \\text{N/C}$", "$3\\times10^4\\ \\text{N/C}$", "$30\\ \\text{N/C}$"], answer: 2, solution: "1. Definisi kuat medan: $E = \\frac{F}{q}$. 2. $E = \\frac{0{,}06}{2\\times10^{-6}} = 3\\times10^4\\ \\text{N/C}$. 3. Kesalahan umum: tidak mengubah $\\mu\\text{C}$ ke coulomb sehingga mendapat $0{,}06/2 = 0{,}03\\ \\text{N/C}$, atau tertukar memakai $E = F\\cdot q$." },
    { q: "Sebuah muatan titik $5\\ \\mu\\text{C}$ berada di udara ($k = 9\\times10^9\\ \\text{N}\\cdot\\text{m}^2/\\text{C}^2$). Kuat medan listrik pada jarak $0{,}2\\ \\text{m}$ dari muatan adalah ...", options: ["$2{,}25\\times10^5\\ \\text{N/C}$", "$1{,}125\\times10^6\\ \\text{N/C}$", "$4{,}5\\times10^4\\ \\text{N/C}$", "$1{,}125\\times10^7\\ \\text{N/C}$"], answer: 1, solution: "1. Medan muatan titik: $E = k\\frac{Q}{r^2}$. 2. $E = 9\\times10^9\\cdot\\frac{5\\times10^{-6}}{(0{,}2)^2} = \\frac{4{,}5\\times10^4}{0{,}04} = 1{,}125\\times10^6\\ \\text{N/C}$, menjauhi muatan karena positif. 3. Kesalahan umum: membagi dengan $r$ bukan $r^2$ sehingga mendapat $2{,}25\\times10^5\\ \\text{N/C}$." },
    { q: "Muatan $3\\ \\mu\\text{C}$ dipindahkan dari titik berpotensial $100\\ \\text{V}$ ke titik berpotensial $400\\ \\text{V}$. Usaha yang diperlukan untuk pemindahan tersebut adalah ...", options: ["$3\\times10^{-4}\\ \\text{J}$", "$1{,}2\\times10^{-3}\\ \\text{J}$", "$900\\ \\text{J}$", "$9\\times10^{-4}\\ \\text{J}$"], answer: 3, solution: "1. Usaha melawan medan listrik: $W = q\\Delta V = q(V_2 - V_1)$. 2. $W = 3\\times10^{-6}\\cdot(400 - 100) = 3\\times10^{-6}\\cdot300 = 9\\times10^{-4}\\ \\text{J}$ (positif: energi potensial muatan bertambah). 3. Kesalahan umum: memakai $V_2$ saja ($1{,}2\\times10^{-3}\\ \\text{J}$) — yang menentukan usaha adalah selisih potensial, bukan potensial akhirnya." },
    { q: "Sebuah kawat memiliki hambatan $12\\ \\Omega$. Jika panjang kawat dijadikan 3 kali semula dan diameternya dijadikan 2 kali semula (bahan sama), hambatan kawat yang baru adalah ...", options: ["$9\\ \\Omega$", "$18\\ \\Omega$", "$36\\ \\Omega$", "$4\\ \\Omega$"], answer: 0, solution: "1. Hambatan $R = \\rho\\frac{L}{A}$ dengan luas penampang $A \\propto d^2$. 2. $R' = R\\cdot\\frac{L'}{L}\\cdot\\left(\\frac{d}{d'}\\right)^2 = 12\\cdot3\\cdot\\left(\\frac{1}{2}\\right)^2 = 12\\cdot\\frac{3}{4} = 9\\ \\Omega$. 3. Kesalahan umum: lupa bahwa luas berbanding dengan kuadrat diameter sehingga mendapat $12\\cdot3/2 = 18\\ \\Omega$." },
    { q: "Arus konvensional dalam seutas kawat tembaga mengalir ke kanan. Arah aliran elektron-elektron di dalam kawat sebenarnya adalah ...", options: ["ke kanan", "diam, tidak bergerak", "ke kiri", "tegak lurus kawat"], answer: 2, solution: "1. Arus konvensional didefinisikan sebagai arah aliran muatan positif, sedangkan pembawa muatan dalam logam adalah elektron yang bermuatan negatif. 2. Karena muatannya negatif, elektron bergerak berlawanan dengan arah arus konvensional — yaitu ke kiri. 3. Miskonsepsi umum: mengira elektron mengalir searah arus konvensional — arus konvensional hanyalah konvensi historis dari sebelum elektron ditemukan." },
    { q: "Sebuah lampu bertuliskan $60\\ \\text{W}/220\\ \\text{V}$ dihubungkan ke tegangan $110\\ \\text{V}$ (anggap hambatan filamen tetap). Daya listrik yang dipakai lampu sekarang adalah ...", options: ["$30\\ \\text{W}$", "$15\\ \\text{W}$", "$120\\ \\text{W}$", "$60\\ \\text{W}$"], answer: 1, solution: "1. Daya $P = \\frac{V^2}{R}$ dengan $R$ tetap, sehingga $P$ sebanding dengan kuadrat tegangan. 2. $P' = 60\\cdot\\left(\\frac{110}{220}\\right)^2 = 60\\cdot\\frac{1}{4} = 15\\ \\text{W}$. 3. Kesalahan umum: mengira daya turun setengahnya ($30\\ \\text{W}$) — karena $P \\propto V^2$, tegangan yang menjadi setengah membuat daya menjadi seperempat." },
    { q: "Dua resistor $6\\ \\Omega$ dan $3\\ \\Omega$ dirangkai paralel lalu dihubungkan ke baterai $12\\ \\text{V}$. Kuat arus total yang keluar dari baterai adalah ...", options: ["$1{,}33\\ \\text{A}$", "$4\\ \\text{A}$", "$2\\ \\text{A}$", "$6\\ \\text{A}$"], answer: 3, solution: "1. Hambatan paralel: $\\frac{1}{R_p} = \\frac{1}{6} + \\frac{1}{3} = \\frac{1}{2} \\Rightarrow R_p = 2\\ \\Omega$. 2. Arus total $I = \\frac{V}{R_p} = \\frac{12}{2} = 6\\ \\text{A}$ (terbagi $2\\ \\text{A}$ dan $4\\ \\text{A}$ pada tiap cabang). 3. Kesalahan umum: menjumlahkan seperti rangkaian seri ($R = 9\\ \\Omega$) sehingga mendapat $1{,}33\\ \\text{A}$ — hambatan paralel selalu lebih kecil dari hambatan terkecilnya." },
    { q: "Dua lampu identik mula-mula dipasang seri, kemudian dipasang paralel pada sumber tegangan yang sama. Daya total pada susunan paralel adalah ... dibanding susunan seri.", options: ["4 kali", "2 kali", "sama besar", "setengah kali"], answer: 0, solution: "1. Misal tiap lampu berhambatan $R$ dan tegangan sumber $V$: $P_{seri} = \\frac{V^2}{2R}$, sedangkan $P_{paralel} = 2\\cdot\\frac{V^2}{R}$. 2. Perbandingan $\\frac{P_{paralel}}{P_{seri}} = \\frac{2V^2/R}{V^2/2R} = 4$ — susunan paralel 4 kali lebih besar dayanya (lebih terang). 3. Miskonsepsi umum: mengira seri lebih terang karena 'arusnya sama' — justru pada paralel tiap lampu mendapat tegangan penuh sumber." },
    { q: "Sebuah setrika listrik $300\\ \\text{W}$ digunakan selama $2\\ \\text{jam}$. Energi listrik yang dikonsumsi adalah ...", options: ["$600\\ \\text{kWh}$", "$0{,}15\\ \\text{kWh}$", "$0{,}6\\ \\text{kWh}$", "$1{,}2\\ \\text{kWh}$"], answer: 2, solution: "1. Energi $W = P\\cdot t$; ubah daya ke kilowatt: $300\\ \\text{W} = 0{,}3\\ \\text{kW}$. 2. $W = 0{,}3\\cdot2 = 0{,}6\\ \\text{kWh}$ (setara $2{,}16\\times10^6\\ \\text{J}$). 3. Kesalahan umum: menjawab $600\\ \\text{kWh}$ — lupa mengubah watt ke kilowatt sebelum mengalikan dengan jam." },
    { q: "Sebuah proton ($q = 1{,}6\\times10^{-19}\\ \\text{C}$) bergerak dengan kelajuan $2\\times10^6\\ \\text{m/s}$ tegak lurus medan magnet $0{,}5\\ \\text{T}$. Besar gaya Lorentz yang dialami proton adalah ...", options: ["$3{,}2\\times10^{-13}\\ \\text{N}$", "$1{,}6\\times10^{-13}\\ \\text{N}$", "$1{,}6\\times10^{-12}\\ \\text{N}$", "$8\\times10^{-14}\\ \\text{N}$"], answer: 1, solution: "1. Gaya Lorentz $F = qvB\\sin\\theta$; tegak lurus berarti $\\sin\\theta = 1$. 2. $F = 1{,}6\\times10^{-19}\\cdot2\\times10^6\\cdot0{,}5 = 1{,}6\\times10^{-13}\\ \\text{N}$. 3. Kesalahan umum: lupa mengalikan dengan $B = 0{,}5$ sehingga mendapat $3{,}2\\times10^{-13}\\ \\text{N}$, atau salah menempatkan pangkat sepuluh." },
    { q: "Sebuah elektron bergerak ke timur memasuki daerah bermedan magnet yang arahnya ke utara. Arah gaya Lorentz yang dialami elektron adalah ...", options: ["ke atas", "ke utara", "ke selatan", "ke bawah"], answer: 3, solution: "1. Kaidah tangan kanan: $\\vec{v}$ (timur) $\\times$ $\\vec{B}$ (utara) menunjuk ke atas. 2. Karena elektron bermuatan negatif, gaya $\\vec{F} = q(\\vec{v}\\times\\vec{B})$ berbalik arah menjadi ke bawah. 3. Kesalahan umum: menjawab 'ke atas' — lupa bahwa tanda muatan negatif membalik arah gaya Lorentz." },
    { q: "Seutas kawat lurus panjang $0{,}4\\ \\text{m}$ dialiri arus $5\\ \\text{A}$ dan membentuk sudut $30^\\circ$ terhadap medan magnet $0{,}3\\ \\text{T}$. Besar gaya magnetik pada kawat adalah ...", options: ["$0{,}3\\ \\text{N}$", "$0{,}6\\ \\text{N}$", "$0{,}52\\ \\text{N}$", "$0{,}03\\ \\text{N}$"], answer: 0, solution: "1. Gaya pada kawat berarus: $F = BIL\\sin\\theta$. 2. $F = 0{,}3\\cdot5\\cdot0{,}4\\cdot\\sin 30^\\circ = 0{,}6\\cdot0{,}5 = 0{,}3\\ \\text{N}$. 3. Kesalahan umum: mengabaikan faktor $\\sin 30^\\circ$ sehingga mendapat $0{,}6\\ \\text{N}$, atau keliru memakai $\\cos 30^\\circ$." },
    { q: "Arus $10\\ \\text{A}$ mengalir pada kawat lurus panjang ($\\mu_0 = 4\\pi\\times10^{-7}\\ \\text{T}\\cdot\\text{m/A}$). Besar induksi magnetik pada jarak $0{,}05\\ \\text{m}$ dari kawat adalah ...", options: ["$4\\times10^{-6}\\ \\text{T}$", "$8\\times10^{-5}\\ \\text{T}$", "$4\\times10^{-5}\\ \\text{T}$", "$2\\times10^{-5}\\ \\text{T}$"], answer: 2, solution: "1. Medan kawat lurus: $B = \\frac{\\mu_0 I}{2\\pi r}$. 2. $B = \\frac{4\\pi\\times10^{-7}\\cdot10}{2\\pi\\cdot0{,}05} = \\frac{4\\pi\\times10^{-6}}{0{,}1\\pi} = 4\\times10^{-5}\\ \\text{T}$. 3. Kesalahan umum: menghilangkan faktor $2$ pada penyebut ($2\\pi r$) sehingga mendapat $8\\times10^{-5}\\ \\text{T}$." },
    { q: "Sebuah solenoida memiliki $500$ lilitan, panjang $0{,}5\\ \\text{m}$, dan dialiri arus $2\\ \\text{A}$ ($\\mu_0 = 4\\pi\\times10^{-7}\\ \\text{T}\\cdot\\text{m/A}$). Besar induksi magnetik di pusat solenoida adalah ...", options: ["$4\\pi\\times10^{-4}\\ \\text{T}$", "$8\\pi\\times10^{-4}\\ \\text{T}$", "$1{,}6\\pi\\times10^{-6}\\ \\text{T}$", "$8\\pi\\times10^{-3}\\ \\text{T}$"], answer: 1, solution: "1. Medan pusat solenoida: $B = \\mu_0\\frac{NI}{L}$. 2. $B = 4\\pi\\times10^{-7}\\cdot\\frac{500\\cdot2}{0{,}5} = 4\\pi\\times10^{-7}\\cdot2000 = 8\\pi\\times10^{-4}\\ \\text{T}$. 3. Kesalahan umum: lupa mengalikan jumlah lilitan $N$ sehingga mendapat $1{,}6\\pi\\times10^{-6}\\ \\text{T}$ — medan solenoida sebanding dengan $N$." },
    { q: "Arus listrik pada kawat lurus mengalir vertikal ke atas. Arah medan magnet di titik yang terletak tepat di sebelah kanan kawat adalah ...", options: ["keluar bidang kertas", "ke atas searah arus", "ke kanan menjauhi kawat", "masuk bidang kertas"], answer: 3, solution: "1. Kaidah tangan kanan: genggam kawat dengan ibu jari ke arah arus (ke atas), maka jari-jari yang melingkar menunjukkan arah medan. 2. Di sebelah kanan kawat, garis medan menembus masuk bidang kertas (simbol $\\otimes$). 3. Kesalahan umum: menjawab 'keluar bidang' — itu arah medan di sebelah kiri kawat, bukan kanan." },
    { q: "Medan magnet $0{,}4\\ \\text{T}$ menembus bidang seluas $0{,}05\\ \\text{m}^2$ dengan sudut $60^\\circ$ antara arah medan dan garis normal bidang. Besar fluks magnetik yang menembus bidang adalah ...", options: ["$0{,}01\\ \\text{Wb}$", "$0{,}02\\ \\text{Wb}$", "$0{,}017\\ \\text{Wb}$", "$0{,}1\\ \\text{Wb}$"], answer: 0, solution: "1. Fluks magnetik $\\Phi = BA\\cos\\theta$, dengan $\\theta$ diukur dari garis normal bidang. 2. $\\Phi = 0{,}4\\cdot0{,}05\\cdot\\cos 60^\\circ = 0{,}02\\cdot0{,}5 = 0{,}01\\ \\text{Wb}$. 3. Kesalahan umum: mengabaikan $\\cos\\theta$ sehingga mendapat $0{,}02\\ \\text{Wb}$, atau keliru memakai $\\sin 60^\\circ$." },
    { q: "Kutub utara sebuah magnet batang digerakkan mendekati sebuah kumparan. Jika dilihat dari sisi magnet, arah arus induksi yang timbul pada kumparan adalah ...", options: ["searah jarum jam", "berlawanan arah jarum jam", "bolak-balik berubah arah", "tidak timbul arus"], answer: 1, solution: "1. Magnet mendekat berarti fluks magnetik menembus kumparan bertambah. 2. Menurut Hukum Lenz, arus induksi melawan perubahan ini dengan menciptakan kutub utara di sisi kumparan yang menghadap magnet (tolak-menolak) — dilihat dari sisi magnet, arus yang menghasilkan kutub utara menghadap pengamat berputar berlawanan arah jarum jam. 3. Kesalahan umum: menjawab searah jarum jam — itu justru memperkuat perubahan fluks, melanggar Hukum Lenz." },
    { q: "Kumparan $100$ lilitan seluas $0{,}02\\ \\text{m}^2$ berputar dalam medan magnet $0{,}5\\ \\text{T}$ dengan kecepatan sudut $20\\pi\\ \\text{rad/s}$. Besar GGL induksi maksimum yang dihasilkan adalah ...", options: ["$1\\ \\text{V}$", "$0{,}2\\pi\\ \\text{V}$", "$20\\pi\\ \\text{V}$", "$40\\pi\\ \\text{V}$"], answer: 2, solution: "1. GGL generator AC: $\\varepsilon_{maks} = NBA\\omega$. 2. $\\varepsilon_{maks} = 100\\cdot0{,}5\\cdot0{,}02\\cdot20\\pi = 20\\pi\\ \\text{V} \\approx 62{,}8\\ \\text{V}$. 3. Kesalahan umum: lupa mengalikan kecepatan sudut $\\omega$ sehingga hanya mendapat $NBA = 1\\ \\text{V}$, atau lupa jumlah lilitan $N$." },
    { q: "Sebuah transformator memiliki $200$ lilitan primer dan $50$ lilitan sekunder. Jika tegangan primer $220\\ \\text{V}$, tegangan sekundernya adalah ...", options: ["$880\\ \\text{V}$", "$220\\ \\text{V}$", "$110\\ \\text{V}$", "$55\\ \\text{V}$"], answer: 3, solution: "1. Rasio transformator ideal: $\\frac{V_s}{V_p} = \\frac{N_s}{N_p}$. 2. $V_s = 220\\cdot\\frac{50}{200} = 220\\cdot\\frac{1}{4} = 55\\ \\text{V}$ — trafo step-down karena $N_s < N_p$. 3. Kesalahan umum: membalik rasio menjadi $220\\cdot200/50 = 880\\ \\text{V}$ — tegangan sebanding lurus dengan jumlah lilitan, bukan berbanding terbalik." },
    { q: "Sebuah transformator memiliki efisiensi $80\\%$ dan daya pada kumparan primer $200\\ \\text{W}$. Daya yang tersedia pada kumparan sekunder adalah ...", options: ["$160\\ \\text{W}$", "$250\\ \\text{W}$", "$200\\ \\text{W}$", "$40\\ \\text{W}$"], answer: 0, solution: "1. Efisiensi $\\eta = \\frac{P_s}{P_p}\\times100\\%$. 2. $P_s = 0{,}8\\cdot200 = 160\\ \\text{W}$ — $40\\ \\text{W}$ hilang sebagai panas dan rugi-rugi inti. 3. Kesalahan umum: membalik menjadi $200/0{,}8 = 250\\ \\text{W}$ — daya sekunder trafo nyata selalu lebih kecil dari daya primer." }
  ]
};
